window.FOLIO_BOOK_ORIG_IN = window.FOLIO_BOOK_ORIG_IN || [];
window.FOLIO_BOOK_ORIG_IN.push({
  id: "song-of-roland",
  lang: "fro",
  langName: "Old French",
  edition: "La Chanson de Roland, edited by Joseph Bédier, L'Édition d'Art H. Piazza, Paris, 1920–1922",
  rights: "The poem is Old French and around nine hundred years old. Joseph Bédier's edition of it was published in 1920–1922 and he lived from 1864 to 1938, so his text is public domain in the United States under the pre-1929 publication rule and out of copyright wherever the term is life plus seventy years, which expired in 2009; where the term is life plus a hundred it runs until 2039. Bédier's own facing modern-French translation is not reproduced here — what is taken is his Old French text.",
  sourceName: "Wikisource",
  sourceUrl: "https://fr.wikisource.org/wiki/La_Chanson_de_Roland/Joseph_B%C3%A9dier",
  chapters: [
    { n: 1, html: "<p><span class=\"bk-n\">1</span> CARLES li reis, nostre emperere magnes,<br>Set anz tuz pleins ad estet en Espaigne&#160;:<br>Tresqu’en la mer cunquist la tere altaigne.<br>N’i ad castel ki devant lui remaigne&#160;;<br>Mur ne citet n’i est remés a fraindre,<br>Fors Sarraguce, ki est en une muntaigne.<br>Li reis Marsilie la tient, ki Deu nen aimet.<br>Mahumet sert e Apollin recleimet&#160;:<br>Nes poet guarder que mals ne l’i ateignet. aoi.</p>" },
    { n: 2, html: "<p><span class=\"bk-n\">2</span> LI reis Marsilie esteit en Sarraguce.<br>Alez en est en un verger suz l’umbre.<br>Sur un perrun de marbre bloi se culchet&#160;;<br>Envirun lui plus de vint milie humes.<br>Il en apelet e ses dux e ses cuntes&#160;:<br>«&#160;Oez, seignurs, quel pecchet nus encumbret.<br>Li empereres Carles de France dulce<br>En cest païs nos est venuz cunfundre.<br>Jo nen ai ost qui bataille li dunne,<br>Ne n’ai tel gent ki la sue derumpet.<br>Cunseilez mei cume mi savie hume,<br>Si me guarisez e de mort et de hunte&#160;!&#160;»<br>N’i ad paien ki un sul mot respundet,<br>Fors Blancandrins de Castel de Valfunde.</p>" },
    { n: 3, html: "<p><span class=\"bk-n\">3</span> Blancandrins fut des plus saives paiens&#160;;<br>De vasselage fut asez chevaler,<br>Prozdom i out pur sun seignur aider,<br>E dist al rei&#160;: «&#160;Ore ne vus esmaiez&#160;!<br>Mandez Carlun, a l’orguillus e al fier,<br>Fedeilz servises e mult granz amistez.<br>Vos li durrez urs e leons e chens,<br>Set cenz camelz e mil hosturs muers,<br>D’or e d’argent .IIII.C. muls cargez,<br>Cinquante carre qu’en ferat carier&#160;:<br>Ben en purrat luer ses soldeiers.<br>En ceste tere ad asez osteiet&#160;;<br>En France, ad Ais, s’en deit ben repairer.<br>Vos le sivrez a la feste seint Michel,<br>Si recevrez la lei de chrestiens,<br>Serez ses hom par honur e par ben.<br>S’en volt ostages, e vos l’en enveiez,<br>U dis u vint, pur lui afiancer.<br>Enveiuns i les filz de noz muillers&#160;:<br>Par num d’ocire i enveierai le men.<br>Asez est melz qu’il i perdent lé chefs<br>Que nus perduns l’onur ne la deintet,<br>Ne nus seiuns cunduiz a mendeier&#160;! &#160;» AOI.</p>" },
    { n: 4, html: "<p><span class=\"bk-n\">4</span> Dist Blancandrins&#160;: «&#160;Pa ceste meie destre<br>E par la barbe ki al piz me ventelet,<br>L’ost des Franceis verrez sempres desfere.<br>Francs s’en irunt en France, la lur tere.<br>Quant cascuns ert a sun meillor repaire,<br>Carles serat ad Ais, a sa capele,<br>A seint Michel tendrat mult halte feste.<br>Vendrat li jurz, si passerat li termes,<br>N’orrat de nos paroles ne nuveles.<br>Li reis est fiers e sis curages pesmes&#160;:<br>De nos ostages ferat trecher les testes.<br>Asez est mielz qu’il i perdent les testes<br>Que nus perduns clere Espaigne, la bele,<br>Ne nus aiuns les mals ne les suffraites&#160;! &#160;»<br>Dient paien&#160;: «&#160;Issi poet il ben estre&#160;!&#160;»</p>" },
    { n: 5, html: "<p><span class=\"bk-n\">5</span> Li reis Marsilie out sun cunseill finet,<br>Sin apelat Clarin de Balaguet,<br>Estamarin e Eudropin, sun per,<br>E Priamun e Guarlan le barbet<br>E Machiner e sun uncle, Maheu,<br>E Joüner e Malbien d’ultremer<br>E Blancandrins, por la raisun cunter.<br>Des plus feluns dis en ad apelez&#160;:<br>«&#160;Seignurs baruns, a Carlemagnes irez.<br>Il est al siege a Cordres la citet.<br>Branches d’olives en voz mains porterez,<br>Ço senefiet pais e humilitet.<br>Par voz saveirs sem puez acorder,<br>Jo vos durrai or e argent asez,<br>Teres e fiez tant cum vos en vuldrez.&#160;»<br>Dient paien&#160;: «&#160;De ço avun nus asez&#160;!&#160;» AOI.</p>" },
    { n: 6, html: "<p><span class=\"bk-n\">6</span> Li reis Marsilie out finet sun cunseill,<br>Dist a ses humes&#160;: «&#160;Seignurs, vos en ireiz.<br>Branches d’olive en voz mains portereiz,<br>Si me direz a Carlemagne le rei<br>Pur le soen Deu qu’il ait mercit de mei.<br>Ja einz ne verrat passer cest premer meis<br>Que jel sivrai od mil de mes fedeilz,<br>Si recevrai la chrestiene lei,<br>Serai ses hom par amur e par feid.<br>S’il voelt ostages, il en avrat par veir.&#160;»<br>Dist Blancandrins&#160;: «&#160;Mult bon plait en avreiz.&#160;» AOI.</p>" },
    { n: 7, html: "<p><span class=\"bk-n\">7</span> Dis blanches mules fist amener Marsilies,<br>Que li tramist li reis de Suatilie.<br>Li frein sunt d’or, les seles d’argent mises.<br>Cil sunt muntez ki le message firent,<br>Enz en lur mains portent branches d’olive.<br>Vindrent a Charles, ki France ad en baillie&#160;:<br>Nes poet guarder que alques ne l’engignent. AOI.</p>" },
    { n: 8, html: "<p><span class=\"bk-n\">8</span> Li empereres se fait e balz e liez&#160;:<br>Cordres ad prise e les murs peceiez,<br>Od ses cadables les turs en abatied&#160;;<br>Mult grant eschech en unt si chevaler<br>D’or e d’argent e de guarnemenz chers.<br>En la citet nen ad remés paien<br>Ne seit ocis u devient chrestien.<br>Li empereres est en un grant verger,<br>Ensembl’ od lui Rollant e Oliver,<br>Sansun li dux e Anseïs li fiers,<br>Gefreid d’Anjou, le rei gunfanuner,<br>E si i furent e Gerin e Gerers&#160;;<br>La u cist furent, des altres i out bien&#160;:<br>De dulce France i ad quinze milliers.<br>Sur palies blancs siedent cil cevaler,<br>As tables juent pur els esbaneier<br>E as eschecs li plus saive e li veill,<br>E escremissent cil bacheler leger.<br>Desuz un pin, delez un eglenter,<br>Un faldestoed i unt fait fut d’or mer&#160;:<br>La siet li reis ki dulce France tient.<br>Blanche ad la barbe e tut flurit le chef,<br>Gent ad le cors e le cuntenant fier&#160;:<br>S’est kil demandet, ne l’estoet enseigner.<br>E li message descendirent a pied,<br>Sil saluerent par amur e par bien.</p>" },
    { n: 9, html: "<p><span class=\"bk-n\">9</span> Blancandrins ad tut premereins parled<br>E dist al rei&#160;: «&#160;Salvet seiez de Deu,<br>Le glorius que devuns aürer&#160;!<br>Iço vus mandet reis Marsilies li bers&#160;:<br>Enquis ad mult la lei de salvetet.<br>De sun aveir vos voelt asez duner,<br>Urs e leuns e veltres enchaignez,<br>Set cenz cameilz e mil hosturs muez,<br>D’or e d’argent .IIII. cenz muls trussez,<br>Cinquante care que carier en ferez&#160;;<br>Tant i avrat de besanz esmerez<br>Dunt bien purrez voz soldeiers luer.<br>En cest païs avez estet asez&#160;;<br>En France ad Ais devez bien repairer.<br>La vos sivrat, ço dit, mis avoez.&#160;»<br>Li empereres tent ses mains vers Deu,<br>Baisset sun chef, si cumencet a penser. AOI.</p>" },
    { n: 10, html: "<p><span class=\"bk-n\">10</span> Li empereres en tint sun chef enclin.<br>De sa parole ne fut mie hastifs,<br>Sa custume est qu’il parolet a leisir.<br>Quant se redrecet, mult par out fier lu vis&#160;;<br>Dist as messages&#160;: «&#160;Vus avez mult ben dit.<br>Li reis Marsilies est mult mis enemis&#160;:<br>De cez paroles que vos avez ci dit,<br>En quel mesure en purrai estre fiz&#160;?<br>— Vos par hostages&#160;», ço dist li Sarrazins,<br>«&#160;Dunt vos avrez u dis u quinze u vint.<br>Pa num d’ocire i metrai un mien filz<br>E sin avrez, ço quid, de plus gentilz.<br>Quant vus serez el palais seignurill,<br>A la grant feste seint Michel del Peril,<br>Mis avoez la vos sivrat, ço dit.<br>Enz en voz bainz que Deus pur vos i fist,<br>La vuldrat il chrestiens devenir.&#160;»<br>Charles respunt&#160;: «&#160;Uncore purrat guarir.&#160;» AOI.</p>" },
    { n: 11, html: "<p><span class=\"bk-n\">11</span> Bels fut li vespres e li soleilz fut cler.<br>Les dis mulez fait Charles establer.<br>El grant verger fait li reis tendre un tref,<br>Les dis messages ad fait enz hosteler&#160;;<br>.XII. serjanz les unt ben cunreez&#160;;<br>La noit demurent tresque vint al jur cler.<br>Li empereres est par matin levet,<br>Messe e matines ad li reis escultet.<br>Desuz un pin en est li reis alez,<br>Ses baruns mandet pur sun cunseill finer&#160;:<br>Par cels de France voelt il del tut errer. AOI.</p>" },
    { n: 12, html: "<p><span class=\"bk-n\">12</span> Li empereres s’en vait desuz un pin,<br>Ses baruns mandet pur sun cunseill fenir,<br>Le duc Oger e l’arcevesque Turpin,<br>Richard li velz e sun nevold Henri<br>E de Gascuigne li proz quens Acelin,<br>Tedbald de Reins e Milun sun cusin,<br>E si i furent e Gerers e Gerin&#160;;<br>Ensembl’ od els li quens Rollant i vint<br>E Oliver, li proz e li gentilz&#160;;<br>Des Francs de France en i ad plus de mil&#160;;<br>Guenes i vint, ki la traïsun fist.<br>Des ore cumencet le cunseill que mal prist. AOI.</p>" },
    { n: 13, html: "<p><span class=\"bk-n\">13</span> «&#160;Seignurs barons,&#160;» dist li emperere Carles,<br>«&#160;Li reis Marsilie m’ad tramis ses messages.<br>De sun aveir me voelt duner grant masse,<br>Urs e leuns e veltres caeignables,<br>Set cenz cameilz e mil hosturs muables,<br>Quatre cenz muls cargez de l’or d’Arabe,<br>Avoec iço plus de cinquante care.<br>Mais il me mandet que en France m’en alge&#160;:<br>Il me sivrat ad Ais, a mun estage,<br>Si recevrat la nostre lei plus salve&#160;;<br>Chrestiens ert, de mei tendrat ses marches&#160;;<br>Mais jo ne sai quels en est sis curages.&#160;»<br>Dient Franceis&#160;: «&#160;Il nus i cuvent guarde&#160;!&#160;» AOI.</p>" },
    { n: 14, html: "<p><span class=\"bk-n\">14</span> Li empereres out sa raisun fenie.<br>Li quens Rollant, ki ne l’otriet mie,<br>En piez se drecet, si li vint cuntredire.<br>Il dist al rei&#160;: «&#160;Ja mar crerez Marsilie&#160;!<br>Set anz ad pleins qu’en Espaigne venimes&#160;;<br>Jo vos cunquis e Noples e Commibles,<br>Pris ai Valterne e la tere de Pine<br>E Balasgued e Tuele e Sezilie&#160;:<br>Li reis Marsilie i fist mult que traïtre.<br>De ses paiens enveiat quinze,<br>Chascuns portout une branche d’olive,<br>Nuncerent vos cez paroles meïsme.<br>A voz Franceis un cunseill en presistes,<br>Loerent vos alques de legerie&#160;;<br>Dous de voz cuntes al paien tramesistes,<br>L’un fut Basan e li altres Basilies&#160;;<br>Les chef en prist es puis desuz Haltilie.<br>Faites la guer cum vos l’avez enprise,<br>En Sarraguce menez vostre ost banie,<br>Metez le sege a tute vostre vie,<br>Si vengez cels que li fels fist ocire&#160;!&#160;» AOI.</p>" },
    { n: 15, html: "<p><span class=\"bk-n\">15</span> Li emperere en tint sun chef enbrunc,<br>Si duist sa barbe, afaitad sun gernun,<br>Ne ben ne mal ne respunt sun nevuld.<br>Franceis se taisent, ne mais que Guenelun.<br>En piez se drecet, si vint devant Carlun,<br>Mult fierement cumencet sa raisun<br>E dist al rei&#160;: «&#160;Ja mar crerez bricun,<br>Ne mei ne altre, se de vostre prod nun&#160;!<br>Quant ço vos mandet li reis Marsiliun<br>Qu’il devendrat jointes ses mains tis hom<br>E tute Espaigne tendrat par vostre dun,<br>Puis recevrat la lei que nus tenum,<br>Qui ço vos lodet que cest plait degetuns,<br>Ne li chalt, sire, de quel mort nus muriuns.<br>Cunseill d’orguill n’est dreiz que a plus munt&#160;;<br>Laissum les fols, as sages nus tenuns&#160;!&#160;» AOI.</p>" },
    { n: 16, html: "<p><span class=\"bk-n\">16</span> Après iço i est Neimes venud,<br>Meillor vassal n’aveit en la curt nul,<br>E dist al rei&#160;: «&#160;Ben l’avez entendud&#160;:<br>Guenes li quens ço vus ad respondud&#160;;<br>Saveir i ad, mais qu’il seit entendud.<br>Li reis Marsilie est de guere vencud&#160;:<br>Vos li avez tuz ses castels toluz,<br>Od voz caables avez fruiset ses murs,<br>Ses citez arses e ses humes vencuz.<br>Quant il vos mandet qu’aiez mercit de lui,<br>Pecchet fereit ki dunc li fesist plus.<br>U par ostage vos en voelt faire soürs,<br>Ceste grant guerre ne deit munter a plus.&#160;»<br>Dient Franceis&#160;: «&#160;Ben ad parlet li dux.&#160;» AOI.</p>" },
    { n: 17, html: "<p><span class=\"bk-n\">17</span> «&#160;Seignurs baruns, qui i enveieruns,<br>En Sarraguce, al rei Marsiliuns&#160;?&#160;»<br>Respunt dux Neimes&#160;: «&#160;Jo irai, par vostre dun&#160;!<br>Livrez m’en ore le guant e le bastun.&#160;»<br>Respunt li reis&#160;: «&#160;Vos estes saives hom.<br>Par ceste barbe e par cest men gernun,<br>Vos n’irez pas uan de mei si luign.<br>Alez sedeir, quant nuls ne vos sumunt&#160;!</p>" },
    { n: 18, html: "<p><span class=\"bk-n\">18</span> Seignurs baruns, qui i purruns enveier,<br>Al Sarrazin ki Sarraguce tient&#160;?&#160;»<br>Respunt Rollant&#160;: «&#160;Jo i puis aler mult ben&#160;!<br>— Nu ferez certes,&#160;» dist li quens Oliver.<br>«&#160;Vostre curages est mult pesmes e fiers&#160;:<br>Jo me crendreie que vos vos meslisez.<br>Se li reis voelt, jo i puis aler ben.&#160;».<br>Respunt li reis&#160;: «&#160;Ambdui vos en taisez&#160;!<br>Ne vos ne il n’i porterez les piez.<br>Par ceste barbe que veez blancheier,<br>Li duze per mar i serunt jugez&#160;!&#160;»<br>Franceis se taisent, as les vus aquisez.</p>" },
    { n: 19, html: "<p><span class=\"bk-n\">19</span> Turpins de Reins en est levet del renc<br>E dist al rei&#160;: «&#160;Laisez ester voz Francs&#160;!<br>En cest païs avez estet set anz,<br>Mult unt oüd e peines e ahans.<br>Dunez m’en, sire, le bastun e le guant<br>E jo irai al Sarazin espan,<br>Sin vois vedeir alques de sun semblant.&#160;»<br>Li empereres respunt par maltalant&#160;:<br>«&#160;Alez sedeir desur cel palie blanc&#160;!<br>N’en parlez mais, se jo nel vos cumant&#160;!&#160;» AOI.</p>" },
    { n: 20, html: "<p><span class=\"bk-n\">20</span> «&#160;Francs chevalers,&#160;» dist li emperere Carles,<br>«&#160;Car m’eslisez un barun de ma marche,<br>Qu’a Marsiliun me portast mun message.&#160;»<br>Ço dist Rollant&#160;: «&#160;Ço ert Guenes, mis parastre.&#160;»<br>Dient Franceis&#160;: «&#160;Car il le poet ben faire.<br>Se lui lessez, n’i trametrez plus saive.&#160;»<br>E li quens Guenes en fut mult anguisables.<br>De sun col getet ses grandes pels de martre<br>E est remés en sun blialt de palie.<br>Vairs out les oeilz e mult fier lu visage&#160;;<br>Gent out le cors e les costez out larges&#160;;<br>Tant par fut bels tuit si per l’en esguardent.<br>Dist a Rollant&#160;: «&#160;Tut fol, pur quei t’esrages&#160;?<br>Ço set hom ben que jo sui tis parastres,<br>Si as juget qu’a Marsiliun en alge.<br>Se Deus ço dunet que jo de la repaire,<br>Jo t’en muvra un si grant contraire<br>Ki durerat a trestut tun edage.&#160;»<br>Respunt Rollant&#160;: «&#160;Orgoill oi e folage.<br>Ço set hom ben n’ai cure de manace.<br>Mai saives hom il deit faire message&#160;:<br>Si li reis voelt, prez sui por vus le face&#160;!&#160;» AOI.</p>" },
    { n: 21, html: "<p><span class=\"bk-n\">21</span> Guenes respunt&#160;: «&#160;Pur mei n’iras tu mie&#160;!<br>Tu n’ies mes hom ne jo ne sui tis sire.<br>Carles comandet que face sun servise&#160;:<br>En Sarraguce en irai a Marsilie.<br>Einz i frai un poi de legerie<br>Que jo n’esclair ceste meie grant ire.&#160;»<br>Quant l’ot Rollant, si cumençat a rire. AOI.</p>" },
    { n: 22, html: "<p><span class=\"bk-n\">22</span> Quant ço veit Guenes qu’ore s’en rit Rollant,<br>Dunc ad tel doel pur poi d’ire ne fent&#160;;<br>A ben petit que il ne pert le sens,<br>E dit al cunte&#160;: «&#160;Jo ne vus aim nient&#160;:<br>Sur mei avez turnet fals jugement.<br>Dreiz emperere, veiz me ci en present&#160;:<br>Ademplir voeill vostre comandement..</p>" },
    { n: 23, html: "<p><span class=\"bk-n\">23</span> En Sarraguce sai ben qu’aler m’estoet. AOI.<br>Hom ki la vait repairer ne s’en poet.<br>Ensur que tut si ai jo vostre soer,<br>Sin ai un filz, ja plus bels n’en estoet.<br>Ço est Baldewin,&#160;» ço dit, «&#160;ki ert prozdoem.<br>A lui lais jo mes honurs e mes fieus.<br>Guadez le ben, ja nel verrai des oilz.&#160;»<br>Carles respunt&#160;: «&#160;Tro avez tendre coer.<br>Puis quel comant, aler vus en estoet.&#160;»</p>" },
    { n: 24, html: "<p><span class=\"bk-n\">24</span> Ço dist li reis&#160;: «&#160;Guenes, venez avant, AOI.<br>Si recevez le bastun e lu guant.<br>Oït l’avez, sur vos le jugent Franc.<br>— Sire,&#160;» dist Guenes, «&#160;ço ad tut fait Rollant&#160;!<br>Ne l’amerai a trestut mun vivant,<br>Ne Oliver, por ço qu’il est si cumpainz,<br>Li duze per, por ço qu’il l’aiment tant.<br>Desfi les en, sire, vostre veiant.&#160;»<br>Ço dist li reis&#160;: «&#160;Trop avez mal talant.<br>Or irez vos certes, quant jol cumant.<br>— Jo i puis aler, mais n’i avrai guarant. AOI.<br>Nu l’out Basilies ne sis freres Basant.&#160;»</p>" },
    { n: 25, html: "<p><span class=\"bk-n\">25</span> Li empereres li tent sun guant, le destre&#160;;<br>Mais li quens Guenes iloec ne volsist estre&#160;:<br>Quant le dut prendre, si li caït a tere.<br>Dient Franceis&#160;: «&#160;Deus, que purrat ço estre&#160;?<br>De cest message nos avendrat grant perte.<br>— Seignurs,&#160;» dist Guenes, «&#160;vos en orrez noveles&#160;!&#160;»</p>" },
    { n: 26, html: "<p><span class=\"bk-n\">26</span> «&#160;Sire,&#160;» dist Guenes, «&#160;dunez mei le cungied.<br>Quant aler dei, n’i ai plus que targer.&#160;»<br>Ço dist li reis&#160;: «&#160;Al Jhesu e al mien&#160;!&#160;»<br>De sa main destre l’ad asols e seignet,<br>Puis li livrat le bastun e le bref.</p>" },
    { n: 27, html: "<p><span class=\"bk-n\">27</span> Guenes li quens s’en vait a sun ostel,<br>De garnemenz se prent a cunreer,<br>De ses meillors que il pout recuvrer&#160;:<br>Esperuns d’or ad en ses piez fermez,<br>Ceint Murglies, s’espee, a sun costed&#160;;<br>En Tachebrun, sun destrer, est munted&#160;;<br>L’estreu li tint sun uncle Guinemer.<br>La veïsez tant chevaler plorer,<br>Ki tuit li dient&#160;: «&#160;Tant mare fustes ber&#160;!<br>En la cort al rei mult i avez ested,<br>Noble vassal vos i solt hom clamer.<br>Ki ço jugat que doüsez aler<br>Par Charlemagne n’ert guariz ne tensez.<br>Li quens Rollant nel se doüst penser,<br>Que estrait estes de mult grant parented.&#160;»<br>Enprès li dient&#160;: «&#160;Sire, car nos menez&#160;!&#160;»<br>Ço respunt Guenes&#160;: «&#160;Ne placet Damnedeu&#160;!<br>Mielz est que sul moerge que tant bon chevaler.<br>En dulce France, seignurs, vos en irez&#160;:<br>De meie part ma muiller saluez,<br>E Pinabel, mun ami e mun per,<br>E Baldewin, mun filz que vos savez&#160;;<br>E lui aidez e pur seignur le tenez.&#160;»<br>Entret en sa veie, si s’est achiminez. AOI.</p>" },
    { n: 28, html: "<p><span class=\"bk-n\">28</span> Guenes chevalchet suz une olive halte,<br>Asemblet s’est as sarrazins messages,<br>Mais Blancandrins ki envers lu s’atarget&#160;;<br>Par grant saveir parolet li uns a l’altre.<br>Dist Blancandrins&#160;: «&#160;Merveilus hom est Charles,<br>Ki cunquist Puille e trestute Calabre&#160;!<br>Vers Engletere passat il la mer salse,<br>Ad oes seint Perre en cunquist le chevage&#160;:<br>Que nus requert ça en la nostre marche&#160;?&#160;»<br>Guenes respunt&#160;: «&#160;Itels est sis curages.<br>Jamais n’ert hume ki encuntre lui vaille.&#160;» AOI.</p>" },
    { n: 29, html: "<p><span class=\"bk-n\">29</span> Dist Blancandrins&#160;: «&#160;Francs sunt mult gentilz home<br>Mult grant mal funt e cil duc e cil cunte<br>A lur seignur, ki tel cunseill li dunent&#160;:<br>Lui e altrui travaillent e cunfundent.&#160;»<br>Guenes respunt&#160;: «&#160;Jo ne sai veirs nul hume,<br>Ne mès Rollant, ki uncore en avrat hunte.<br>Er matin sedeit li emperere suz l’umbre,<br>Vint i ses niés, out vestue sa brunie,<br>E out predet dejuste Carcasonie&#160;;<br>En sa main tint une vermeille pume&#160;:<br>Tenez, bel sire, dist Rollant a sun uncle,<br>De trestuz reis vos present les curunes.<br>Li soens orgoilz le devreit ben cunfundre,<br>Kar chascun jur de mort s’abandunet.<br>Seit ki l’ociet, tute pais puis avriumes.&#160;» AOI.</p>" },
    { n: 30, html: "<p><span class=\"bk-n\">30</span> Dist Blancandrins&#160;: «&#160;Mult est pesmes Rollant,<br>Ki tute gent voelt faire recreant<br>E tutes teres met en chalengement&#160;!<br>Par quele gent quiet il espleiter tant&#160;?&#160;»<br>Guenes respunt&#160;: «&#160;Par la franceise gent.<br>Il l’aiment tant ne li faldrunt nient&#160;;<br>Or e argent lur met tant en present,<br>Muls e destrers e palies e guarnemenz&#160;;<br>L’emperere meïsmes ad tut a sun talent&#160;:<br>Cunquerrat li les teres d’ici qu’en Orient.&#160;» AOI.</p>" },
    { n: 31, html: "<p><span class=\"bk-n\">31</span> Tant chevalcherent Guenes e Blancandrins<br>Que l’un a l’altre la sue feit plevit<br>Que il querreient que Rollant fust ocis.<br>Tant chevalcherent e veies e chemins<br>Qu’en Sarraguce descendent suz un if.<br>Un faldestoet out suz l’umbre d’un pin&#160;;<br>Envolupet fut d’un palie alexandrin&#160;:<br>La fut li reis ki tute Espaigne tint&#160;;<br>Tut entur lui vint milie Sarrazins,<br>N’i ad celoi ki mot sunt ne mot tint,<br>Pur les nuveles qu’il vuldreient oïr.<br>Atant as vos Guenes e Blanchandrins.</p>" },
    { n: 32, html: "<p><span class=\"bk-n\">32</span> Blancandrins vint devant Marsiliun,<br>Par le puign tint le cunte Guenelun,<br>E dist al rei&#160;: «&#160;Salvez seiez de Mahum<br>E d’Apollin, qui seintes leis tenuns&#160;!<br>Vostre message fesime a Charlun.<br>Ambes ses mains en levat cuntremunt,<br>Loat sun Deu, ne fist altre respuns.<br>Ci vos enveiet un sun noble barun<br>Ki est de France, si est mult riches hom&#160;:<br>Par lui orrez si avrez pais u nun.&#160;»<br>Respunt Marsilie&#160;: «&#160;Or diet, nus l’orrum&#160;!&#160;» AOI.</p>" },
    { n: 33, html: "<p><span class=\"bk-n\">33</span> Mais li quens Guenes se fut ben purpenset.<br>Par grant saver cumencet a parler<br>Cume celui ki ben faire le set,<br>E dist al rei&#160;: «&#160;Salvez seiez de Deu,<br>Li glorius, qui devum aürer&#160;!<br>Iço vus mandet Carlemagnes li ber,<br>Que recevez seinte chrestientet&#160;;<br>Demi Espaigne vos voelt en fiu duner.<br>Se cest’ acorde ne vulez otrier,<br>Pris e liez serez par poested&#160;;<br>Al siege ad Ais en serez amenet,<br>Par jugement serez iloec finet&#160;;<br>La murrez vus a hunte e a viltet.&#160;»<br>Li reis Marsilies en fut mult esfreed.<br>Un algier tint, ki d’or fut enpenet&#160;;<br>Ferir l’en volt, se n’en fust desturnet. AOI.</p>" },
    { n: 34, html: "<p><span class=\"bk-n\">34</span> Li reis Marsilies ad la culur muee,<br>De sun algeir ad la hanste crollee.<br>Quant le vit Guenes, mist la main a l’espee,<br>Cuntre dous deie l’ad del furrel getee,<br>Si li ad dit&#160;: «&#160;Mult estes bele e clere&#160;!<br>Tant vus avrai en curt a rei portee&#160;!<br>Ja nel dirat de France li emperere<br>Que suls i moerge en l’estrange cuntree,<br>Einz vos avrunt li meillor cumperee&#160;!&#160;»<br>Dient paien&#160;: «&#160;Desfaimes la mellee&#160;!&#160;»</p>" },
    { n: 35, html: "<p><span class=\"bk-n\">35</span> Tant li preierent li meillor Sarrazin<br>Qu’el faldestoed s’es Marsilies asis.<br>Dist l’algalifes&#160;: «&#160;Mal nos avez baillit,<br>Que li Franceis asmastes a ferir.<br>Vos doüssez esculter e oïr.<br>— Sire,&#160;» dist Guenes, «&#160;mei l’avent a suffrir.<br>Jo ne lerreie, por tut l’or que Deus fist<br>Ne por tut l’aveir ki seit en cest païs,<br>Que jo ne li die, se tant ai de leisir,<br>Que Charles li mandet, li reis poesteïfs,<br>Par mei li mandet sun mortel enemi.&#160;»<br>Afublez est d’un mantel sabelin,<br>Ki fut cuvert d’un palie alexandrin&#160;:<br>Getet le a tere, sil receit Blancandrin&#160;:<br>Mais de s’espee ne volt mie guerpir&#160;;<br>En sun puign destre par l’orie punt la tint.<br>Dient paien&#160;: «&#160;Noble baron ad ci&#160;!&#160;» AOI.</p>" },
    { n: 36, html: "<p><span class=\"bk-n\">36</span> Envers le rei s’est Guenes aproismet,<br>Si li ad dit&#160;: «&#160;A tort vos curuciez,<br>Quar ço vos mandet Carles, ki France tient,<br>Que recevez la lei de chrestiens&#160;;<br>Demi Espaigne vus durat il en fiet,<br>L’altre meitet avrat Rollant, sis niés&#160;:<br>Mult orguillos parçuner i avrez&#160;!<br>Si ceste acorde ne volez otrier,<br>En Sarraguce vus vendrat aseger.<br>Par poestet serez pris e liez&#160;;<br>Menet serez dreit ad Ais le siet.<br>Vus n’i avrez palefreid ne destrer,<br>Ne mul ne mule que puissez chevalcher&#160;;<br>Getet serez sur un malvais sumer.<br>Par jugement iloec perdrez le chef.<br>Nostre emperere vus enveiet cest bref.&#160;»<br>El destre poign al paien l’ad livret.</p>" },
    { n: 37, html: "<p><span class=\"bk-n\">37</span> Marsilies fut esculurez de l’ire,<br>Freint le seel, getet en ad la cire,<br>Guardet al bref, vit la raisun escrite&#160;:<br>«&#160;Carle me mandet, ki France ad en baillie,<br>Que me remembre de la dolur e de l’ire,<br>Ço est de Basan e de sun frere Basilie<br>Dunt pris les chefs as puis de Haltoïe&#160;;<br>Se de mun cors voeil aquiter la vie,<br>Dunc li envei mun uncle l’algalife&#160;;<br>Altrement ne m’amerat il mie.&#160;»<br>Après parlat ses filz envers Marsilies<br>E dist al rei&#160;: «&#160;Guenes ad dit folie.<br>Tant ad erret nen est dreiz que plus vivet.<br>Livrez le mei, jo en ferai la justise.&#160;»<br>Quant l’oït Guenes, l’espee en ad branlie&#160;;<br>Vait s’apuier suz le pin a la tige.</p>" },
    { n: 38, html: "<p><span class=\"bk-n\">38</span> Enz el verger s’en est alez li reis,<br>Ses meillors humes en meinet ensembl’od sei,<br>E Blancandrins i vint, al canud peil,<br>E Jurfaret, ki est ses filz e ses heirs,<br>E l’algalifes, sun uncle e sis fedeilz.<br>Dist Blancandrins&#160;: «&#160;Apelez le Franceis&#160;:<br>De nostre prod m’ad plevie sa feid.&#160;»<br>Ço dist li reis&#160;: «&#160;E vos l’i ameneiz.&#160;»<br>Guenelun prist par la main destre ad deiz,<br>Enz el verger l’en meinet josqu’al rei.<br>La purparolent la traïsun seinz dreit. AOI.</p>" },
    { n: 39, html: "<p><span class=\"bk-n\">39</span> «&#160;Bel sire Guenes,&#160;» ço li ad dit Marsilie,<br>«&#160;Jo vos ai fait alques de legerie,<br>Quant por ferir vus demustrai grant ire.<br>Guaz vos en dreit par cez pels sabelines,<br>Melz en valt l’or que ne funt cinc cenz livres&#160;:<br>Einz demain noit en iert bele l’amendise.&#160;»<br>Guenes respunt&#160;: «&#160;Jo nel desotrei mie.<br>Deus, se lui plaist, a bien le vos mercie&#160;»&#160;! AOI.</p>" },
    { n: 40, html: "<p><span class=\"bk-n\">40</span> Ço dist Marsilies&#160;: «&#160;Guenes, par veir sacez,<br>En talant ai que mult vos voeill amer.<br>De Carlemagne vos voeill oïr parler.<br>Il est mult vielz, si ad sun tens uset&#160;;<br>Men escient dous cenz anz ad passet.<br>Par tantes teres ad sun cors demened,<br>Tanz colps ad pris sur sun escut bucler,<br>Tanz riches reis cunduiz a mendisted&#160;:<br>Quant ert il mais recreanz d’osteier&#160;?&#160;»<br>Guenes respunt&#160;: «&#160;Carles n’est mie tels.<br>N’est hom kil veit e conuistre le set<br>Que ço ne diet que l’emperere est ber.<br>Tant nel vos sai ne preiser ne loer<br>Que plus n’i ad d’onur e de bontet.<br>Sa grant valor, kil purreit acunter&#160;?<br>De tel barnage l’ad Deus enluminet<br>Meilz voelt murir que guerpir sun barnet.&#160;»</p>" },
    { n: 41, html: "<p><span class=\"bk-n\">41</span> Dist li païens&#160;: «&#160;Mult me puis merveiller<br>De Carlemagne, ki est canuz e vielz&#160;!<br>Men escientre dous cenz anz ad e mielz.<br>Par tantes teres ad sun cors traveillet,<br>Tanz cols ad pris de lances e d’espiez,<br>Tanz riches reis cunduiz a mendistiet&#160;:<br>Quant ert il mais recreanz d’osteier&#160;?<br>— Ço n’iert,&#160;» dist Guenes, «&#160;tant cum vivet sis niés&#160;:<br>N’at tel vassal suz la cape del ciel.<br>Mult par est proz sis cumpainz, Oliver&#160;;<br>Les .XII. pers, que Carles ad tant chers,<br>Funt les enguardes a .XX. milie chevalers.<br>Soürs est Carles, que nuls home ne crent.&#160;» AOI.</p>" },
    { n: 42, html: "<p><span class=\"bk-n\">42</span> Dist li Sarrazins&#160;: «&#160;Merveille en ai grant<br>De Carlemagne, ki est canuz e blancs&#160;!<br>Mien escientre plus ad de. II.C. anz.<br>Par tantes teres est alet cunquerant,<br>Tanz colps ad pris de bons espiez trenchanz,<br>Tanz riches reis morz e vencuz en champ&#160;:<br>Quant ier il mais d’osteier recreant&#160;?<br>— Ço n’iert,&#160;» dist Guenes, «&#160;tant cum vivet Rollant&#160;:<br>N’ad tel vassal d’ici qu’en Orient.<br>Mult par est proz Oliver, sis cumpainz&#160;;<br>Li .XII. per, que Carles aimet tant,<br>Funt les enguardes a .XX. milie de Francs.<br>Soürs est Carles, ne crent hume vivant.&#160;» AOI.</p>" },
    { n: 43, html: "<p><span class=\"bk-n\">43</span> «&#160;Bel sire Guenes,&#160;» dist Marsilies li reis,<br>«&#160;Jo ai tel gent, plus bele ne verreiz&#160;;<br>Quatre cenz milie chevalers puis aveir.<br>Puis m’en cumbatre a Carle e a Franceis&#160;?&#160;»<br>Guenes respunt&#160;: «&#160;Ne vus a ceste feiz&#160;!<br>De voz paiens mult grant perte i avreiz.<br>Lessez la folie, tenez vos al saveir.<br>L’empereür tant li dunez aveir<br>N’i ait Franceis ki tot ne s’en merveilt.<br>Par .XX. hostages que li enveiereiz<br>En dulce France s’en repairerat li reis&#160;;<br>Sa rereguarde lerrat derere sei.<br>Iert i sis niés. li quens Rollant, ço crei,<br>E Oliver, li proz e li curteis.<br>Mort sunt li cunte, se est ki mei en creit.<br>Carles verrat sun grant orguill cadeir&#160;;<br>N’avrat talent que ja mais vus guerreit.&#160;» AOI.</p>" },
    { n: 44, html: "<p><span class=\"bk-n\">44</span> «&#160;Bel sire Guenes. . . . . . . . .<br>Cum faitement purrai Rollant ocire&#160;?&#160;»<br>Guenes respont&#160;: «&#160;Ço vos sai jo ben dire.<br>Li reis serat as meillors porz de Sizer&#160;;<br>Sa rereguarde avrat detrés sei mise&#160;;<br>Iert i sis niés, li quens Rollant, li riches,<br>E Oliver, en qui il tant se fiet.<br>.XX. milie Francs unt en lur cumpaignie.<br>De voz paiens lur enveiez .C. milie&#160;:<br>Une bataille lur i rendent cil primes&#160;;<br>La gent de France iert blecee e blesmie&#160;;<br>Nel di por ço, des voz iert la martirie.<br>Altre bataille lur livrez de meïsme&#160;:<br>De quel que seit Rollant n’estoerdrat mie.<br>Dunc avrez faite gente chevalerie&#160;;<br>N’avrez mais guere en tute vostre vie. AOI.</p>" },
    { n: 45, html: "<p><span class=\"bk-n\">45</span> Chi purreit faire que Rollant i fust mort,<br>Dunc perdreit Carles le destre braz del cors,<br>Si remeindreient les merveilluses oz&#160;;<br>N’asemblereit jamais Carles si grant esforz&#160;;<br>Tere Major remeindreit en repos.&#160;»<br>Quan l’ot Marsilie, si l’ad baiset el col,<br>Puis si cumencet a venir ses tresors. AOI.</p>" },
    { n: 46, html: "<p><span class=\"bk-n\">46</span> Ço dist Marsilies&#160;: «&#160;Qu’en parlereient . . . . .<br>Cunseill n’est proz dunt hume . . . . . . .<br>La traïsun me jurrez de Rollant.<br>Ço respunt Guenes&#160;: «&#160;Issi seit cum vos plaist&#160;!&#160;»<br>Sur les reliques de s’espee Murgleis<br>La traïsun jurat e si s’en est forsfait. AOI.</p>" },
    { n: 47, html: "<p><span class=\"bk-n\">47</span> Un faldestoed i out d’un olifant.<br>Marsilies fait porter un livre avant&#160;:<br>La lei i fut Mahum e Tervagan.<br>Ço ad juret li Sarrazins espans,<br>Se en rereguarde troevet le cors Rollant,<br>Cumbatrat sei a trestute sa gent<br>E, se il poet, murrat i veirement.<br>Guenes respunt&#160;: «&#160;Ben seit vostre comant&#160;!&#160;» AOI.</p>" },
    { n: 48, html: "<p><span class=\"bk-n\">48</span> Atant i vint uns paiens, Valdabruns.<br>Icil en vait al rei Marsiliun.<br>Cler en riant l’ad dit a Guenelun&#160;:<br>«&#160;Tenez m’espee, meillur n’en at nuls hom&#160;;<br>Entre les helz ad plus de mil manguns.<br>Par amistiez, bel sire, la vos duins<br>Que nos aidez de Rollant le barun,<br>Qu’en rereguarde trover le poüsum.<br>— Ben serat fait,&#160;» li quens Guenes respunt&#160;;<br>Puis se baiserent es vis e es mentuns.</p>" },
    { n: 49, html: "<p><span class=\"bk-n\">49</span> Après i vint un paien, Climorins.<br>Cler en riant a Guenelun l’ad dit&#160;:<br>«&#160;Tenez mun helme, unches meillor ne vi…,<br>Si nos aidez de Rollant li marchis,<br>Par quel mesure le poüssum hunir.<br>— Ben serat fait,&#160;» Guenes respundit&#160;;<br>Puis se baiserent es buches e es vis. AOI.</p>" },
    { n: 50, html: "<p><span class=\"bk-n\">50</span> Atant i vint la reïne Bramimunde&#160;:<br>«&#160;Jo vos aim mult, sire,&#160;» dist ele al cunte,<br>«&#160;Car mult vos priset mi sire e tuit si hume.<br>A vostre femme enveierai dous nusches,<br>Bien i ad or, matices e jacunces&#160;:<br>Eles valent mielz que tut l’aveir de Rume.<br>Vostre emperere si bones n’en out unches.&#160;»<br>Il les ad prises, en sa hoese les butet. AOI.</p>" },
    { n: 51, html: "<p><span class=\"bk-n\">51</span> Li reis apelet Malduit, sun tresorer&#160;:<br>«&#160;L’aveir Carlun est il apareilliez&#160;?&#160;»<br>E cil respunt&#160;: «&#160;Oïl, sire, asez bien&#160;:<br>.VII. C. cameilz, d’or e argent cargiez,<br>E .XX. hostages, des plus gentilz desuz cel.&#160;» AOI.</p>" },
    { n: 52, html: "<p><span class=\"bk-n\">52</span> Marsilies tint Guenelun par l’espalle,<br>Si li ad dit&#160;: «&#160;Mult par ies ber e sage.<br>Par cele lei que vos tenez plus salve,<br>Guardez de nos ne turnez le curage.<br>De mun aveir vos voeill dunner grant masse,<br>.X. muls cargez del plus fin or d’Arabe&#160;;<br>Ja mais n’iert an altretel ne vos face.<br>Tenez les clefs de ceste citet large&#160;;<br>Le grant aveir en presentez al rei Carles&#160;:<br>Pois me jugez Rollant a rereguarde.<br>Sel pois trover a port ne a passage,<br>Liverrai lui une mortel bataille.&#160;»<br>Guenes respunt&#160;: «&#160;Mei est vis que trop targe&#160;!&#160;»<br>Pois est munted, entret en sun veiage. AOI.</p>" },
    { n: 53, html: "<p><span class=\"bk-n\">53</span> Li empereres aproismet sun repaire.<br>Venuz en est a la citet de Galne&#160;:<br>Li quens Rollant, il l’ad e prise e fraite&#160;;<br>Puis icel jur en fut cent anz deserte.<br>De Guenelun atent li reis nuveles<br>E le treüd d’Espaigne, la grant tere.<br>Par main en l’albe, si cum li jurz esclairet,<br>Guenes li quens est venuz as herberges. AOI.</p>" },
    { n: 54, html: "<p><span class=\"bk-n\">54</span> Li empereres est par matin levet&#160;;<br>Messe e matines ad li reis escultet.<br>Sur l’erbe verte estut devant sun tref.<br>Rollant i fut e Oliver li ber,<br>Neimes li dux e des altres asez.<br>Guenes i vint, li fels, li parjurez.<br>Par grant veisdie cumencet a parler<br>E dist al rei&#160;: «&#160;Salvez seiez de Deu&#160;!<br>De Sarraguce ci vos aport les clefs&#160;;<br>Mult grant aveir vos en faz amener<br>E .XX. hostages, faites les ben guarder,<br>E si vos mandet reis Marsilies li ber<br>De l’algalifes nel devez pas blasmer,<br>Kar a mes oilz vi .IIII. C. milie armez,<br>Halbers vestuz, alquanz healmes fermez,<br>Ceintes espees as punz d’or neielez,<br>Ki l’en cunduistrent tresqu’en la mer&#160;:<br>De Marcilie s’en fuient por la chrestientet<br>Que il ne voelent ne tenir ne guarder.<br>Einz qu’il oüssent .IIII. liues siglet,<br>Sis aquillit e tempeste e ored&#160;:<br>La sunt neiez, jamais nes en verrez&#160;;<br>Se il fust vis, jo l’oüsse amenet.<br>Del rei paien, sire, par veir creez<br>Ja ne verrez cest premer meis passet<br>Qu’il vos sivrat en France le regnet,<br>Si recevrat la lei que vos tenez,<br>Jointes ses mains iert vostre comandet&#160;;<br>De vos tendrat Espaigne le regnet.&#160;»<br>Ço dist li reis&#160;: «&#160;Graciet en seit Deus&#160;!<br>Ben l’avez fait&#160;; mult grant prod i avrez.&#160;»<br>Par mi cel ost funt mil grailles suner.<br>Franc desherbergent, funt lur sumers trosser,<br>Vers dulce France tuit sunt achiminez. AOI.</p>" },
    { n: 55, html: "<p><span class=\"bk-n\">55</span> Carles li magnes ad Espaigne guastede,<br>Les castels pris, les citez violees.<br>Ço dit li reis que sa guere out finee.<br>Vers dulce France chevalchet l’emperere…<br>. . . . . . . . . . . . . . . . . . . . .<br>Li quens Rollant ad l’enseigne fermee,<br>En sum un tertre contre le ciel levee.<br>Franc se herbergent par tute la cuntree.<br>Paien chevalchent par cez greignurs valees,<br>Halbercs vestuz e trés bien. . . . . . .<br>Healmes lacez e ceintes lur espees,<br>Escuz as cols e lances adubees.<br>En un bruill par sum les puis remestrent.<br>.IIII. C. milie atendent l’ajurnee.<br>Deus&#160;! quel dulur que li Franceis nel sevent&#160;! AOI.</p>" },
    { n: 56, html: "<p><span class=\"bk-n\">56</span> Tresvait le jur, la noit est aserie.<br>Carles se dort, li empereres riches.<br>Sunjat qu’il eret as greignurs porz de Sizer,<br>Entre ses poinz teneit sa hanste fraisnine.<br>Guenes li quens l’ad sur lui saisie.<br>Par tel aïr l’at estrussee e brandie<br>Qu’envers le cel en volent les escicles.<br>Carles se dort, qu’il ne s’esveillet mie.</p>" },
    { n: 57, html: "<p><span class=\"bk-n\">57</span> Après iceste altre avisiun sunjat&#160;:<br>Qu’il ert en France, a sa capele, ad Ais.<br>El destre braz li morst uns uers si mals.<br>Devers Ardene vit venir uns leuparz,<br>Sun cors demenie mult fierement asalt.<br>D’enz de sale uns veltres avalat,<br>Que vint a Carles lé galops e les salz.<br>La destre oreille al premer uer trenchat,<br>Ireement se cumbat al lepart.<br>Dient Franceis que grant bataille i ad&#160;;<br>Il ne sevent liquels d’els la veintrat.<br>Carles se dort, mie ne s’esveillat. AOI.</p>" },
    { n: 58, html: "<p><span class=\"bk-n\">58</span> Tresvait la noit e apert la clere albe.<br>Par mi cel host. . . . . . . . . . . . . . .<br>Li empereres mult fierement chevalchet.<br>«&#160;Seignurs barons,&#160;» dist li emperere Carles,<br>«&#160;Veez les porz e les destreiz passages&#160;!<br>Kar me jugez ki ert en la rereguarde.&#160;»<br>Guenes respunt&#160;: «&#160;Rollant, cist miens fillastre&#160;:<br>N’avez baron de si grant vasselage.&#160;»<br>Quant l’ot li reis, fierement le reguardet,<br>Si li ad dit&#160;: «&#160;Vos estes vifs diables.<br>El cors vos est entree mortel rage.<br>E ki serat devant mei en l’ansguarde&#160;?&#160;»<br>Guenes respunt&#160;: «&#160;Oger de Denemarche&#160;:<br>N’avez barun ki mielz de lui la facet.&#160;»</p>" },
    { n: 59, html: "<p><span class=\"bk-n\">59</span> Li quens Rollant, quant il s’oït juger, AOI.<br>Dunc ad parled a lei de chevaler&#160;:<br>«&#160;Sire parastre, mult vos dei aveir cher&#160;:<br>La rereguarde avez sur mei jugiet&#160;!<br>N’i perdrat Carles, li reis ki France tient,<br>Men escientre palefreid ne destrer,<br>Ne mul ne mule que deiet chevalcher,<br>Ne n’i perdrat ne runcin ne sumer<br>Que as espees ne seit einz eslegiet.&#160;»<br>Guenes respunt&#160;: «&#160;Veir dites, jol sai bien.&#160;» AOI.</p>" },
    { n: 60, html: "<p><span class=\"bk-n\">60</span> Quant ot Rollant qu’il ert en la rereguarde,<br>Ireement parlat a sun parastre&#160;:<br>«&#160;Ahi&#160;! culvert, malvais hom de put aire,<br>Quias le guant me caïst en la place,<br>Cume fist a tei le bastun devant Carle&#160;? AOI.</p>" },
    { n: 61, html: "<p><span class=\"bk-n\">61</span> Dreiz emperere,&#160;» dist Rollant le barun,<br>«&#160;Dunez mei l’arc que vos tenez el poign.<br>Men escientre nel me reproverunt<br>Que il me chedet cum fist a Guenelun<br>De sa main destre, quant reçut le bastun.&#160;»<br>Li empereres en tint sun chef enbrunc,<br>Si duist sa barbe e detoerst sun gernun,<br>Ne poet muer que des oilz ne plurt.</p>" },
    { n: 62, html: "<p><span class=\"bk-n\">62</span> Après iço i est Neimes venud,<br>Meillor vassal n’out en la curt de lui,<br>E dist al rei&#160;: «&#160;Ben l’avez entendut&#160;;<br>Li quens Rollant, il est mult irascut.<br>La rereguarde est jugee sur lui&#160;:<br>N’avez baron ki jamais la remut.<br>Dunez li l’arc que vos avez tendut,<br>Si li truvez ki trés bien li aiut&#160;!&#160;»<br>Li reis li dunet e Rollant l’a reçut.</p>" },
    { n: 63, html: "<p><span class=\"bk-n\">63</span> Li empereres apelet ses niés Rollant&#160;:<br>«&#160;Bel sire niés, or savez veirement<br>Demi mun host vos lerrai en present.<br>Retenez les, ço est vostre salvement.&#160;»<br>Ço dit li quens&#160;: «&#160;Jo n’en ferai nient.<br>Deus me cunfunde, se la geste en desment&#160;!<br>.XX. milie Francs retendrai ben vaillanz.<br>Passez les porz trestut soürement&#160;:<br>Ja mar crendrez nul hume a mun vivant&#160;!&#160;»</p>" },
    { n: 64, html: "<p><span class=\"bk-n\">64</span> Li quens Rollant est muntet el destrer.<br>Cuntre lui vient sis cumpainz Oliver.<br>Vint i Gerins e li proz quens Gerers,<br>E vint i Otes, si i vint Berengers<br>E vint i Astors e Anseïs li veillz,<br>Vint i Gerart de Rossillon li fiers&#160;;<br>Venuz i est li riches dux Gaifiers.<br>Dist l’arcevesque&#160;: «&#160;Jo irai, par mun chef&#160;!<br>— E jo od vos,&#160;» ço dist li quens Gualters&#160;;<br>«&#160;Hom sui Rollant, jo ne li dei faillir.&#160;»<br>Entr’els eslisent .XX. milie chevalers. AOI.</p>" },
    { n: 65, html: "<p><span class=\"bk-n\">65</span> Li quens Rollant Gualter de l’Hum apelet&#160;:<br>«&#160;Prenez mil Francs de France, nostre tere,<br>Si purprenez les destreiz e les tertres,<br>Que l’emperere nis un des soens n’i perdet.&#160;» AOI.<br>Respunt Gualter&#160;: «&#160;Pur vos le dei ben faire.&#160;»<br>Od mil Franceis de France, la lur tere,<br>Gualter desrenget les destreiz e les tertres&#160;:<br>N’en descendrat pur malvaises nuveles<br>Enceis qu’en seient .VII.C. espees traites.<br>Reis Almaris del regne de Belferne<br>Une bataille lur livrat le jur pesme.</p>" },
    { n: 66, html: "<p><span class=\"bk-n\">66</span> Halt sunt li pui e li val tenebrus,<br>Les roches bises, les destreiz merveillus.<br>Le jur passerent Franceis a grant dulur.<br>De .XV. liues en ot hom la rimur.<br>Puis que il venent a la Tere Majur,<br>Virent Guascuigne, la tere lur seignur&#160;;<br>Dunc lur remembret des fius e des honurs,<br>E des pulcele e des gentilz oixurs&#160;:<br>Cel nen i ad ki de pitet ne plurt.<br>Sur tuz les altres est Carles anguissus&#160;:<br>As porz d’Espaigne ad lesset sun nevold.<br>Pitet l’en prent, ne poet muer n’en plurt. AOI.</p>" },
    { n: 67, html: "<p><span class=\"bk-n\">67</span> Li .XII. per sunt remés en Espaigne.<br>.XX. milie Francs unt en lur cumpaigne,<br>Nen unt poür ne de murir dutance.<br>Li emperere s’en repairet en France&#160;;<br>Suz sun mantel en fait la cuntenance.<br>Dejuste lui li dux Neimes chevalchet<br>E dit al rei&#160;: «&#160;De quei avez pesance&#160;?&#160;»<br>Carles respunt&#160;: «&#160;Tort fait kil me demandet&#160;!<br>Si grant doel ai ne puis muer nel pleigne.<br>Par Guenelun serat destruite France.<br>Enoit m’avint un’ avisiun d’angele<br>Qu’entre mes puinz me depeçout ma hanste&#160;:<br>Chi ad juget mis nés a rereguarde.<br>Jo l’ai lesset en une estrange marche.<br>Deus&#160;! se jol pert, ja n’en avrai escange.&#160;» AOI.</p>" },
    { n: 68, html: "<p><span class=\"bk-n\">68</span> Carles li magnes ne poet muer n’en plurt.<br>.C. milie Francs pur lui unt grant tendrur<br>E de Rollant merveilluse poür.<br>Guenes li fels en ad fait traïsun&#160;:<br>Del rei paien en ad oüd granz duns,<br>Or e argent, palies e ciclatuns,<br>Muls e chevals e cameilz e leuns.<br>Marsilies mandet d’Espaigne les baruns,<br>Cuntes, vezcuntes e dux e almaçurs,<br>Les amirafles e les filz as cunturs&#160;:<br>.IIII. C. milie en ajustet en .III. jurz.<br>En Sarraguce fait suner ses taburs&#160;;<br>Mahumet levent en la plus halte tur&#160;:<br>N’i ad paien nel prit e ne l’aort.<br>Puis si chevalchent par mult grant cuntençun<br>La Tere Certeine e les vals et les munz&#160;:<br>De cels de France virent les gunfanuns.<br>La rereguarde des .XII. cumpaignuns<br>Ne lesserat bataille ne lur dunt.</p>" },
    { n: 69, html: "<p><span class=\"bk-n\">69</span> Li niés Marsilie, il est venuz avant<br>Sur un mulet od un bastun tuchant.<br>Dist a sun uncle belement en riant&#160;:<br>«&#160;Bel sire reis, jo vos ai servit tant,<br>Sin ai oüt e peines e ahans,<br>Faites batailles e vencues en champ&#160;!<br>Dunez m’un feu, ço est le colp de Rollant&#160;;<br>Jo l’ocirai a mun espiet trenchant.<br>Se Mahumet me voelt estre guarant,<br>De tute Espaigne aquiterai les pans<br>Des porz d’Espaigne entresqu’a Durestant.<br>Las serat Carles, si recrerrunt si Franc&#160;;<br>Ja n’avrez mais guere en tut vostre vivant.&#160;»<br>Li reis Marsilie l’en ad dunet le guant. AOI.</p>" },
    { n: 70, html: "<p><span class=\"bk-n\">70</span> Li niés Marsilies tient le guant en sun poign,<br>Sun uncle apelet de mult fiere raisun&#160;:<br>«&#160;Bel sire reis, fait m’avez un grant dun.<br>Eslisez mei .XII. de voz baruns,<br>Sim cumbatrai as .XII. cumpaignuns.&#160;»<br>Tut premerein l’en respunt Falsaron,<br>Icil ert frere al rei Marsiliun&#160;:<br>«&#160;Bel sire niés, e jo e vos i irum.<br>Ceste bataille veirement la ferum<br>La rereguarde de la grant host Carlun.<br>Il est juget que nus les ocirum.&#160;» AOI.</p>" },
    { n: 71, html: "<p><span class=\"bk-n\">71</span> Reis Corsalis, il est de l’altre part.<br>Barbarins est e mult de males arz.<br>Cil ad parlet a lei de bon vassal&#160;:<br>Pur tut l’or Deu ne volt estre cuard.....<br>. . . . . . . . . . . . . . . . . . .<br>As vos poignant Malprimis de Brigant,<br>Plus curt a piet que ne fait un cheval.<br>Devant Marsilie cil s’escriet mult halt&#160;:<br>«&#160;Jo conduirai mun cors en Rencesvals&#160;;<br>Se truis Rollant, ne lerrai que nel mat&#160;!&#160;»</p>" },
    { n: 72, html: "<p><span class=\"bk-n\">72</span> Uns amurafles i ad de Balaguez,<br>Cors ad mult gent e le vis fier e cler&#160;;<br>Puis que il est sur sun cheval muntet,<br>Mult se fait fiers de ses armes porter&#160;;<br>De vasselage est il ben alosez&#160;;<br>Fust chrestiens, asez oüst barnet.<br>Devant Marsilie cil en est escriet&#160;:<br>«&#160;En Rencesvals irai mun cors juer&#160;!<br>Se truis Rollant, de mort serat finet<br>E Oliver e tuz les .XII. pers.<br>Franceis murrunt a doel e a viltiet.<br>Carles li magnes velz est e redotez&#160;:<br>Recreanz ert de sa guerre mener,<br>Si nus remeindrat Espaigne en quitedet.&#160;»<br>Li reis Marsilie mult l’en ad merciet. AOI.</p>" },
    { n: 73, html: "<p><span class=\"bk-n\">73</span> Uns almaçurs i ad de Moriane&#160;;<br>N’ad plus felun en la tere d’Espaigne.<br>Devant Marsilie ad faite sa vantance&#160;:<br>«&#160;En Rencesvals guierai ma cumpaigne,<br>.XX. milie ad escuz e a lances.<br>Se trois Rollant, de mort li duins fiance.<br>Jamais n’ert jor que Carles ne se pleignet.&#160;» AOI.</p>" },
    { n: 74, html: "<p><span class=\"bk-n\">74</span> D’altre part est Turgis de Turteluse,<br>Cil est uns quens, si est la citet sue.<br>De chrestiens voelt faire male vode,<br>Devant Marsilie as altres si s’ajustet,<br>Ço dist al rei&#160;: «&#160;Ne vos esmaiez unches&#160;!<br>Plus valt Mahum que seint Perre de Rume&#160;:<br>Se lui servez, l’onur del camp ert nostre.<br>En Rencesvals a Rollant irai juindre,<br>De mort n’avrat guarantisun por hume.<br>Veez m’espee, ki est e bone e lunge&#160;:<br>A Durendal jo la metrai encuntre&#160;;<br>Asez orrez laquele irat desure.<br>Françeis murrunt, si a nus s’abandunent&#160;;<br>Carles li velz avrat e deol e hunte.<br>Jamais en tere ne porterat curone.&#160;»</p>" },
    { n: 75, html: "<p><span class=\"bk-n\">75</span> De l’altre part est Escremiz de Valterne.<br>Sarrazins est, si est sue la tere.<br>Devant Marsilie s’escriet en la presse&#160;:<br>«&#160;En Rencesvals irai l’orgoill desfaire.<br>Se trois Rollant, n’en porterat la teste,<br>Ne Oliver, ki les altres cadelet.<br>Li .XII. per tuit sunt jugez a perdre.<br>Franceis murrunt e France en ert deserte.<br>De bons vassals avrat Carles suffraite.&#160;» AOI.</p>" },
    { n: 76, html: "<p><span class=\"bk-n\">76</span> D’altre part est uns paiens, Esturganz&#160;;<br>Estramariz i est, un soens cumpainz&#160;:<br>Cil sunt felun, traïtur suduiant.<br>Ço dist Marsilie&#160;: «&#160;Seignurs, venez avant&#160;!<br>En Rencesvals irez as porz passant,<br>Si aiderez a cunduire ma gent.&#160;»<br>E cil respundent&#160;: «&#160;A vostre comandement&#160;!<br>Nus asaldrum Oliver e Rollant&#160;;<br>Li .XII. per n’avrunt de mort guarant.<br>Noz espees sunt bones e trenchant&#160;;<br>Nus les feruns vermeilles de chald sanc.<br>Franceis murrunt, Carles en ert dolent.<br>Tere Majur vos metrum en present.<br>Venez i, reis, sil verrez veirement&#160;:<br>L’empereor vos metrum en present.&#160;»</p>" },
    { n: 77, html: "<p><span class=\"bk-n\">77</span> Curant i vint Margariz de Sibilie&#160;;<br>Cil tient la tere entre qu’as Cazmarine.<br>Pur sa beltet dames li sunt amies&#160;:<br>Cele nel veit vers lui ne s’esclargisset&#160;;<br>Quant ele le veit, ne poet muer ne riet&#160;;<br>N’i ad paien de tel chevalerie.<br>Vint en la presse, sur les altres s’escriet<br>E dist al rei&#160;: «&#160;Ne vos esmaiez mie&#160;!<br>En Rencesvals irai Rollant ocire,<br>Ne Oliver n’en porterat la vie.<br>Li .XII. per sunt remés en martirie.<br>Veez m’espee, ki d’or est enheldie,<br>Si la tramist li amiralz de Primes.<br>Jo vos plevis qu’en vermeill sanc ert mise.<br>Franceis murrunt e France en ert hunie.<br>Carles li velz, a la barbe flurie,<br>Jamais n’ert jurn qu’il n’en ait doel e ire.<br>Jusqu’a un an avrum France saisie&#160;;<br>Gesir porrum el burc de seint Denise.&#160;»<br>Li reis paiens parfundement l’enclinet. AOI.</p>" },
    { n: 78, html: "<p><span class=\"bk-n\">78</span> De l’altre part est Chernubles de Munigre.<br>Josqu’a la tere si chevoel li balient.<br>Greignor fais portet par giu, quant il s’enveiset,<br>Que .IIII. mulez ne funt, quant il sumeient.<br>Icele tere, ço dit, dun il esteit,<br>Soleill n’i luist ne blet n’i poet pas creistre,<br>Pluie n’i chet, rusee n’i adeiset,<br>Piere n’i ad que tute ne seit neire&#160;:<br>Dient alquanz que diables i meignent.<br>Ce dist Chernubles&#160;: «&#160;Ma bone espee ai ceinte.<br>En Rencesvals jo la teindrai vermeille.<br>Se trois Rollant li proz enmi ma veie,<br>Se ne l’asaill, dunc ne faz jo que creire,<br>Si cunquerrai Durendal od la meie.<br>Franceis murrunt e France en ert deserte.&#160;»<br>A icez moz li .XII. per s’alient.<br>Itels. C. mille Sarrazins od els meinent<br>Ki de bataille s’arguent e hasteient.<br>Vunt s’aduber desuz une sapide.</p>" },
    { n: 79, html: "<p><span class=\"bk-n\">79</span> Paien s’adubent des osbercs sarazineis,<br>Tuit li plusur en sunt dublez en treis.<br>Lacent lor elmes mult bons, sarraguzeis,<br>Ceignent espees de l’acer vianeis&#160;;<br>Escuz unt genz, espiez valentineis,<br>E gunfanuns blancs e blois e vermeilz.<br>Laissent les muls e tuz les palefreiz,<br>Es destrers muntent, si chevalchent estreiz.<br>Clers fut li jurz e bels fut li soleilz,<br>N’unt garnement que tut ne reflambeit.<br>Sunent mil grailles por ço que plus bel seit&#160;:<br>Granz est la noise, si l’oïrent Franceis.<br>Dist Oliver&#160;: «&#160;Sire cumpainz, ce crei,<br>De Sarrazins purum bataille aveir.&#160;»<br>Respont Rollant&#160;: «&#160;E Deus la nus otreit&#160;!<br>Ben devuns ci estre pur nostre rei.<br>Pur sun seignor deit hom susfrir destreiz<br>E endurer e granz chalz e granz freiz,<br>Sin deit hom perdre e del quir e del peil.<br>Or guart chascuns que granz colps i empleit,<br>Que malvaise cançun de nus chantet ne seit&#160;!<br>Paien unt tort e chrestiens unt dreit.<br>Malvaise essample n’en serat ja de mei.&#160;» AOI.</p>" },
    { n: 80, html: "<p><span class=\"bk-n\">80</span> Oliver est desur un pui . . . . . . . . .<br>Guardet su destre par mi un val herbus,<br>Si veit venir cele gent paienur,<br>Sin apelat Rollant, sun cumpaignun&#160;:<br>«&#160;Devers Espaigne vei venir tel bruur,<br>Tanz blancs osbercs, tanz elmes flambïus&#160;!<br>Icist ferunt nos Franceis grant irur.<br>Guenes le sout, li fel, li traïtur,<br>Ki nus jugat devant l’empereür.<br>— Tais, Oliver,&#160;» li quens Rollant respunt&#160;;<br>«&#160;Mis parrastre est, ne voeill que mot en suns.&#160;»</p>" },
    { n: 81, html: "<p><span class=\"bk-n\">81</span> Oliver est desur un pui muntet.<br>Or veit il ben d’Espaigne le regnet<br>E Sarrazins, ki tant sunt asemblez.<br>Luisent cil elme, ki ad or sunt gemmez,<br>E cil escuz e cil osbercs safrez<br>E cil espiez, cil gunfanun fermez.<br>Sul les escheles ne poet il acunter&#160;:<br>Tant en i ad que mesure n’en set&#160;;<br>E lui meïsme en est mult esguaret.<br>Cum il einz pout, del pui est avalet,<br>Vint as Franceis, tut lur ad acuntet.</p>" },
    { n: 82, html: "<p><span class=\"bk-n\">82</span> Dist Oliver&#160;: «&#160;Jo ai païens veüz&#160;:<br>Unc mais nuls hom en tere n’en vit plus.<br>Cil devant sunt .C. milie ad escuz,<br>Helmes laciez e blancs osbercs vestuz&#160;;<br>Dreites cez hanstes, luisent cil espiet brun.<br>Bataille avrez, unches mais tel ne fut.<br>Seignurs Franceis, de Deu aiez vertut&#160;!<br>El camp estez, que ne seium vencuz&#160;!&#160;»<br>Dient Franceis&#160;: «&#160;Dehet ait ki s’en fuit&#160;!<br>Ja pur murir ne vus en faldrat uns.&#160;» AOI.</p>" },
    { n: 83, html: "<p><span class=\"bk-n\">83</span> Dist Oliver&#160;: «&#160;Paien unt grant esforz&#160;;<br>De noz Franceis m’i semblet aveir mult poi&#160;!<br>Cumpaign Rollant, kar sunez vostre corn,<br>Si l’orrat Carles, si returnerat l’ost.&#160;»<br>Respunt Rollant&#160;: «&#160;Jo fereie que fols&#160;!<br>En dulce France en perdreie mun los.<br>Sempres ferrai de Durendal granz colps&#160;;<br>Sanglant en ert li branz entresqu’a l’or.<br>Felun paien mar i vindrent as porz&#160;:<br>Jo vos plevis. tuz sunt jugez a mort.&#160;» AOI.</p>" },
    { n: 84, html: "<p><span class=\"bk-n\">84</span> «&#160;Cumpainz Rollant, l’olifan car sunez,<br>Si l’orrat Carles, ferat l’ost returner,<br>Succurrat nos li reis od sun barnet.<br>Respont Rollant&#160;: «&#160;Ne placet Damnedeu<br>Que mi parent pur mei seient blasmet<br>Ne France dulce ja cheet en viltet&#160;!<br>Einz i ferrai de Durendal asez,<br>Ma bone espee que ai ceint al costet&#160;:<br>Tut en verrez le brant ensanglentet.<br>Felun paien mar i sunt asemblez&#160;:<br>Jo vos plevis, tuz sunt a mort livrez.&#160;» AOI.</p>" },
    { n: 85, html: "<p><span class=\"bk-n\">85</span> «&#160;Cumpainz Rollant, sunez vostre olifan,<br>Si l’orrat Carles, ki est as porz passant.<br>Je vos plevis, ja returnerunt Franc.<br>— Ne placet Deu,&#160;» ço li respunt Rollant,<br>«&#160;Que ço seit dit de nul hume vivant,<br>Ne pur paien, que ja seie cornant&#160;!<br>Ja n’en avrunt reproece mi parent.<br>Quant jo serai en la bataille grant<br>E jo ferrai e mil colps e .VII. cenz,<br>De Durendal verrez l’acer sanglent.<br>Franceis sunt bon, si ferrunt vassalment&#160;;<br>Ja cil d’Espaigne n’avrunt de mort guarant.&#160;»</p>" },
    { n: 86, html: "<p><span class=\"bk-n\">86</span> Dist Oliver&#160;: «&#160;D’iço ne sai jo blasme.<br>Jo ai veüt les Sarrazins d’Espaigne&#160;:<br>Cuverz en sunt li val e les muntaignes<br>E li lariz e trestutes les plaignes.<br>Granz sunt les oz de cele gent estrange&#160;;<br>Nus i avum mult petite cumpaigne.&#160;»<br>Respunt Rollant&#160;: «&#160;Mis talenz en est graigne.<br>Ne placet Damnedeu ne ses angles<br>Que ja pur mei perdet sa valur France&#160;!<br>Melz voeill murir que huntage me venget.<br>Pur ben ferir l’emperere plus nos aimet.&#160;»</p>" },
    { n: 87, html: "<p><span class=\"bk-n\">87</span> Rollant est proz e Oliver est sage.<br>Ambedui unt meveillus vasselage&#160;:<br>Puis que il sunt as chevals e as armes.<br>Ja pur murir n’eschiverunt bataille.<br>Bon sunt li cunte e lur paroles haltes.<br>Felun paien par grant irur chevalchent.<br>Dist Oliver&#160;: «&#160;Rollant, veez en alques&#160;:<br>Cist nus sunt près, mais trop nus est loinz Carles.<br>Vostre olifan suner, vos nel deignastes&#160;;<br>Fust i li reis, n’i oüssum damage.<br>Guardez amunt devers les porz d’Espaigne,<br>Veeir poez, dolente est la rereguarde&#160;;<br>Ki ceste fait, ja mais n’en ferat altre.&#160;»<br>Respunt Rollant&#160;: «&#160;Ne dites tel ultrage&#160;!<br>Mal seit del coer ki el piz se cuardet&#160;!<br>Nus remeindrum en estal en la place&#160;;<br>Par nos i ert e li colps e li caples.&#160;» AOI.</p>" },
    { n: 88, html: "<p><span class=\"bk-n\">88</span> Quant Rollant veit que la bataille serat,<br>Plus se fait fiers que leon ne leupart.<br>Franceis escriet, Oliver apelat&#160;:<br>«&#160;Sire cumpainz, amis, nel dire ja&#160;!<br>Li emperere, ki Franceis nos laisat,<br>Itels .XX. milie en mist a une part<br>Sun escientre n’en i out un cuard.<br>Pur sun seignur deit hom susfrir granz mals<br>E endurer e forz freiz e granz chalz,<br>Sin deit hom perdre del sanc e de la char.<br>Fier de ta lance e jo de Durendal,<br>Ma bone espee, que li reis me dunat.<br>Se jo i moerc, dire poet ki l’avrat<br>. . . Que ele fut a noble vassal.&#160;»</p>" },
    { n: 89, html: "<p><span class=\"bk-n\">89</span> D’altre part est li arcevesques Turpin.<br>Sun cheval broche e muntet un lariz&#160;;<br>Franceis apelet, un sermun lur ad dit&#160;:<br>«&#160;Seignurs baruns, Carles nus laissat ci&#160;;<br>Pur nostre rei devum nus ben murir.<br>Chrestientet aidez a sustenir&#160;!<br>Bataille avrez, vos en estes tuz fiz,<br>Kar a voz oilz veez les Sarrazins.<br>Clamez voz culpes, si preiez Deu mercit&#160;;<br>Asoldrai vos pur vos anmes guarir.<br>Se vos murez, esterez seinz martirs,<br>Sieges avrez el greignor pareïs.&#160;»<br>Franceis descendent, a tere se sunt mis,<br>E l’arcevesque de Deu les beneïst&#160;:<br>Par penitence les cumandet a ferir.</p>" },
    { n: 90, html: "<p><span class=\"bk-n\">90</span> Franceis se drecent, si se metent sur piez.<br>Ben sunt asols e quites de lur pecchez,<br>E l’arcevesque de Deu les ad seignez,<br>&#160;Puis sunt muntez sur lur curanz destrers.<br>Adobez sunt a lei de chevalers<br>E de bataille sunt tuit apareillez.<br>Li quens Rollant apelet Oliver&#160;:<br>«&#160;Sire cumpainz, mult ben le saviez<br>Que Guenelun nos ad tuz espiez.<br>Pris en ad or e aveir e deners.<br>Li emperere nos devreit ben venger.<br>Li reis Marsilie de nos ad fait marchet&#160;;<br>Mais as espees l’estuvrat esleger.&#160;» AOI.</p>" },
    { n: 91, html: "<p><span class=\"bk-n\">91</span> As porz d’Espaigne en est passet Rollant<br>Sur Veillantif, sun bon cheval curant.<br>Portet ses armes, mult li sunt avenanz,<br>Mais sun espiet vait li bers palmeiant,<br>Cuntre le ciel vait la mure turnant,<br>Laciet en su un gunfanun tut blanc&#160;;<br>Les renges li batent josqu’as mains.<br>Cors ad mult gent, le vis cler e riant.<br>Sun cumpaignun après le vait sivant,<br>E cil de France le cleiment a guarant.<br>Vers Sarrazins reguardet fierement<br>E vers Franceis humeles e dulcement,<br>Si lur ad dit un mot curteisement&#160;:<br>«&#160;Seignurs barons, suef, le pas tenant&#160;!<br>Cist paien vont grant martirie querant.<br>Encoi avrum un eschec bel e gent&#160;:<br>Nuls reis de France n’out unkes si vaillant.&#160;»<br>A cez paroles vunt les oz ajustant. AOI.</p>" },
    { n: 92, html: "<p><span class=\"bk-n\">92</span> Dist Oliver&#160;: «&#160;N’ai cure de parler.<br>Vostre olifan ne deignastes suner,<br>Ne de Carlun mie vos n’en avez.<br>Il n’en set mot, n’i ad culpes li bers.<br>Cil ki la sunt ne funt mie a blasmer.<br>Kar chevalchez a quanque vos puez&#160;!<br>Seignors baruns, el camp vos retenez&#160;!<br>Pur Deu vos pri, ben seiez purpensez<br>De colps ferir, de receivre e de duner&#160;!<br>L’enseigne Carle n’i devum ublier.&#160;»<br>A icest mot sunt Franceis escriet.<br>Ki dunc oïst Munjoie demander,<br>De vasselage li poüst remembrer.<br>Puis si chevalchent, Deus&#160;! par si grant fiertet&#160;!<br>Brochent ad ait pur le plus tost aler,<br>Si vunt ferir, que fereient il el&#160;?<br>E Sarrazins nes unt mie dutez&#160;;<br>Francs e paiens, as les vus ajustez.</p>" },
    { n: 93, html: "<p><span class=\"bk-n\">93</span> Li niés Marsilie, il ad a num Aelroth&#160;;<br>Tut premereins chevalchet devant l’ost.<br>De noz Franceis vait disant si mals moz&#160;:<br>«&#160;Feluns Franceis, hoi justerez as noz.<br>Traït vos ad ki a guarder vos out.<br>Fols est li reis ki vos laissat as porz.<br>Enquoi perdrat France dulce sun los,<br>Charles li magnes le destre braz del cors.&#160;»<br>Quant l’ot Rollant, Deus&#160;! si grant doel en out&#160;!<br>Sun cheval brochet, laiset curre a esforz,<br>Vait le ferir li quens quanque il pout.<br>L’escut li freint e l’osberc li desclot,<br>Trenchet le piz, si li briset les os,<br>Tute l’eschine li desevret del dos,<br>Od sun espiet l’anme li getet fors,<br>Enpeint le ben, fait li brandir le cors,<br>Pleine sa hanste del cheval l’abat mort,<br>En dous meitiez li ad briset le col.<br>Ne leserat, ço dit, que n’i parolt&#160;:<br>«&#160;Ultre, culvert&#160;! Carles n’est mie fol,<br>Ne traïsun unkes amer ne volt.<br>Il fist que proz qu’il nus laisad as porz.<br>Oi n’en perdrat France dulce sun los.<br>Ferez i, Francs, nostre est li premers colps&#160;!<br>Nos avum dreit, mais cist glutun unt tort.&#160;» AOI.</p>" },
    { n: 94, html: "<p><span class=\"bk-n\">94</span> Un duc i est, si ad num Falsaron&#160;;<br>Icil er frere al rei Marsiliun.<br>Il tint la tere Dathan e Abirun.<br>Suz cel nen at plus encrisme felun.<br>Entre les dous oilz mult out large le front,<br>Grant demi pied mesurer i pout hom.<br>Asez ad doel quant vit mort sun nevold,<br>Ist de la prese, si se met en bandun,<br>E si escriet l’enseigne paienor.<br>Envers Franceis est mult cuntrarius&#160;:<br>«&#160;Enquoi perdrat France dulce s’onur&#160;!&#160;»<br>Ot le Oliver, sin ad mult grant irur.<br>Le cheval brochet des oriez esperuns,<br>Vait le ferir en guise de baron.<br>L’escut li freint e l’osberc li derumpt,<br>El cors li met les pans del gunfanun,<br>Pleine sa hanste l’abat mort des arçuns&#160;;<br>Guardet a tere, veit gesir le glutun,<br>Si li ad dit par mult fiere raison&#160;:<br>«&#160;De voz manaces, culvert, jo n’ai essoign.<br>Ferez i, Francs, kar trés ben les veintrum&#160;!&#160;»<br>Munjoie escriet, ço est l’enseigne Carlun. AOI.</p>" },
    { n: 95, html: "<p><span class=\"bk-n\">95</span> Uns reis i est, si ad num Corsablix,<br>Barbarins est, d’un estrage païs,<br>Si apelad les altres Sarrazins&#160;:<br>«&#160;Ceste bataille ben la puum tenir,<br>Kar de Franceis i ad asez petit.<br>Cels ki ci sunt devum aveir mult vil.<br>Ja pur Charles n’i ert un sul guarit&#160;:<br>Or est le jur qu’els estuvrat murir.&#160;»<br>Ben l’entendit li arcevesques Turpin,<br>Suz ciel n’at hume que tant voeillet haïr.<br>Sun cheval brochet des esperuns d’or fin,<br>Par grant vertut si l’est alet ferir.<br>L’escut li freinst, l’osberc li descumfist,<br>Sun grant espiet par mi le cors li mist,<br>Empeint le ben, que mort le fait brandir,<br>Pleine sa hanste l’abat mort el chemin.<br>Guardet a tere, veit le glutun gesir,<br>Ne laisserat que n’i parolt, ço dit&#160;:<br>«&#160;Culvert paien, vos i avez mentit&#160;!<br>Carles, mi sire, nus est guarant tuz dis.<br>Nostre Franceis n’unt talent de fuïr.<br>Voz cumpaignuns feruns trestuz restifs.<br>Nuveles vos di, mort vos estoet susfrir.<br>Ferez, Franceis&#160;! Nul de vus ne s’ublit&#160;!<br>Cist premer colp est nostre, Deu mercit&#160;!&#160;»<br>Munjoie escriet por le camp retenir.</p>" },
    { n: 96, html: "<p><span class=\"bk-n\">96</span> E Gerins fiert Malprimis de Brigal.<br>Sis bons escuz un dener ne li valt&#160;:<br>Tute li freint la bucle de cristal,<br>L’une meitiet li turnet cuntreval&#160;;<br>L’osberc li rumpt entresque a la charn,<br>Sun bon espiet enz el cors li enbat&#160;;<br>Li paiens chet cuntreval a un quat.<br>L’anme de lui en portet Sathanas. AOI.</p>" },
    { n: 97, html: "<p><span class=\"bk-n\">97</span> E sis cumpainz Gerers fiert l’amurafle.<br>L’escut li freint e l’osberc li desmailet,<br>Sun bon espiet li met en la curaille,<br>Empeint le bien, par mi le cors li passet,<br>Que mort l’abat el camp, pleine sa hanste.<br>Dist Oliver&#160;: «&#160;Gente est nostre bataille&#160;!&#160;»</p>" },
    { n: 98, html: "<p><span class=\"bk-n\">98</span> Sansun li dux, il vait ferir l’almaçur.<br>L’escut li freinst, ki est ad or e a flurs,<br>Li bons osbercs ne li est guarant prod,<br>Trenchet li le coer, le firie e le pulmun,<br>Que l’abat mort, qui qu’en peist u qui nun.<br>Dist l’arcevesque&#160;: «&#160;Cist colp est de baron&#160;!&#160;»</p>" },
    { n: 99, html: "<p><span class=\"bk-n\">99</span> E Anseïs laiset le cheval curre,<br>Si vait ferir Turgis de Turteluse.<br>L’escut li freint desuz l’oree bucle,<br>De sun osberc li derumpit les dubles,<br>Del bon espiet el cors li met la mure,<br>Empeinst le ben, tut le fer li mist ultre,<br>Pleine sa hanste el camp mort le tresturnet.<br>Ço dist Rollant&#160;: «&#160;Cist colp est de produme&#160;!&#160;»</p>" },
    { n: 100, html: "<p><span class=\"bk-n\">100</span> Et Engelers li Guascuinz de Burdele<br>Sun cheval brochet, si li laschet la resne,<br>Si vait ferir Escremiz de Valterne.<br>L’escut del col li freint e escantelet,<br>De sun osberc li rompit la ventaille,<br>Sil fiert el piz entre les dous furceles,<br>Pleine sa hanste l’abat mort de la sele.<br>Après li dist&#160;: «&#160;Turnet estes a perdre&#160;!&#160;» AOI.</p>" },
    { n: 101, html: "<p><span class=\"bk-n\">101</span> E Otes fiet un paien, Estorgans,<br>Sur sun escut en la pene devant,<br>Que tut li trenchet le vermeill e le blanc&#160;;<br>De sun osberc li ad rumput les pans,<br>El cors li met sun bon espiet trechant,<br>Que mort l’abat de sun cheval curant.<br>Après li dist&#160;: «&#160;Ja n’i avrez guarant&#160;!&#160;»</p>" },
    { n: 102, html: "<p><span class=\"bk-n\">102</span> E Berenger, il fiert Astramariz.<br>L’escut li freinst, l’osberc li descumfist,<br>Sun fort escut par mi le cors li mist,<br>Que mort l’abat entre mil Sarrazins.<br>Des .XII. pers li .X. en sunt ocis&#160;;<br>Ne mès que dous n’en i ad remés vifs&#160;:<br>Ço est Chernubles e li quens Margariz.</p>" },
    { n: 103, html: "<p><span class=\"bk-n\">103</span> Margariz est mult vaillant chevalers,<br>E bels e forz e isnels e legers.<br>Le cheval brochet, vait ferir Oliver.<br>L’escut li freint suz la bucle d’or mer,<br>Lez le costet li conduist sun espiet.<br>Deus le guarit, qu’el cors ne l’ad tuchet.<br>La hanste fruisset, mie n’en abatiet.<br>Ultre s’en vait, qu’il n’i ad desturber&#160;;<br>Sunet sun gresle pur les soens ralier.</p>" },
    { n: 104, html: "<p><span class=\"bk-n\">104</span> La bataille est merveilleuse e cumune.<br>Li quens Rollant mie ne s’asoüret,<br>Fiert de l’espiet tant cume hanste li duret&#160;;<br>A .XV. cols l’ad fraite e perdue&#160;;<br>Trait Durendal, sa bone espee, nue,<br>Sun cheval brochet, si vait ferir Chernuble.<br>L’elme li freint u li carbuncle luisent.<br>Trenchet le cors e la cheveleüre,<br>Si li trenchat les oilz e la faiture,<br>Le blanc osberc, dunt la maile est menue,<br>E tut le cors tresqu’en la furcheüre.<br>Enz en la sele, ki est a or batue,<br>El cheval est l’espee aresteüe&#160;;<br>Trenchet l’eschine, hunc n’i out quis jointure,<br>Tut abat mort el pred sur l’erbe drue.<br>Après li dist&#160;: «&#160;Culvert, mar i moüstes&#160;!<br>De Mahumet ja n’i avrez aiude.<br>Par tel glutun n’ert bataille oi vencue.&#160;»</p>" },
    { n: 105, html: "<p><span class=\"bk-n\">105</span> Li quens Rollant par mi le champ chevalchet,<br>Tient Durendal, ki ben trenchet e taillet,<br>Des Sarrazins lur fait mult grant damage.<br>Ki lui veïst l’un geter mort su l’altre,<br>Li sanc tuz clers gesir par cele place&#160;!<br>Sanglant en ad e l’osberc e la brace,<br>Sun bon cheval le col e les espalles,<br>E Oliver de ferir ne se target,<br>Li .XII. per n’en deivent aveir blasme,<br>Et li Franceis i fierent e si caplent.<br>Moerent paien e alquanz en i pasment.<br>Dist l’arcevesque&#160;: «&#160;Ben ait nostre barnage&#160;!&#160;»<br>Munjoie escriet, ço est l’enseigne Carle. AOI.</p>" },
    { n: 106, html: "<p><span class=\"bk-n\">106</span> E Oliver chevalchet par l’estor,<br>Sa hanste est fraite, n’en ad que un trunçun,<br>E vait ferir un paien, Malun.<br>L’escut li freint, ki est ad or e a flur,<br>Fors de la teste li met les oilz ansdous,<br>E la cervele li chet as piez desuz,<br>Mort le tresturnet od tut .VII. C. des lur&#160;;<br>Pois ad ocis Turgis e Esturguz&#160;:<br>La hanste briset e esclicet josqu’az poinz.<br>Ço dist Rollant&#160;: «&#160;Cumpainz, que faites vos&#160;?<br>En tel bataille n’ai cure de bastun&#160;:<br>Fers e acers i deit aveir valor.<br>U est vostre espee, ki Halteclere ad num&#160;?<br>D’or est li helz e de cristal li punz.<br>— Ne la poi traire,&#160;» Oliver li respunt,<br>«&#160;Kar de ferir oi jo si grant bosoign&#160;!&#160;» AOI.</p>" },
    { n: 107, html: "<p><span class=\"bk-n\">107</span> Danz Oliver trait ad sa bone espee<br>Que ses cumpainz Rollant li ad tant demandee,<br>E il li ad cum chevaler mustree.<br>Fiert un paien, Justin de Val Ferree.<br>Tute la teste li ad par mi sevree,<br>Trenchet le cors e la bronie safree,<br>La bone sele, ki a or est gemmee,<br>E al ceval a l’eschine trenchee&#160;:<br>Tut abat mort devant loi en la pree.<br>Ço dist Rollant&#160;: «&#160;Vos receif jo frere.<br>Por itels colps nos eimet li emperere.&#160;»<br>De tutes parz est Munjoe escriee. AOI.</p>" },
    { n: 108, html: "<p><span class=\"bk-n\">108</span> Li quens Gerins set el ceval Sorel<br>E sis cumpainz Gerers en Passecerf.<br>Laschent lor reisnes, brochent amdui a ait,<br>E vunt ferir un paien, Timozel,<br>L’un en l’escut e li altre en l’osberc.<br>Lur dous espiez enz el cors li unt frait,<br>Mort le tresturnent trés en mi un guaret.<br>Ne l’oï dire ne jo mie nel sai<br>Liquels d’els dous en fut li plus isnels.<br>Esprieris, icil fut filz […] Burdel […]<br>E l’arcevesque lor ocist Siglorel,<br>L’encanteür ki ja fut en enfer&#160;:<br>Par artimal l’i cundoist Jupiter.<br>Ço dist Turpin&#160;: «&#160;Icist nos ert forsfait.&#160;»<br>Respunt Rollant&#160;: «&#160;Vencut est le culvert.<br>Oliver, frere, itels colps me sunt bel.&#160;»</p>" },
    { n: 109, html: "<p><span class=\"bk-n\">109</span> La bataille est aduree endementres.<br>Franc e paien merveilus colps i rendent.<br>Fierent li un, li altre se defendent.<br>Tant’ hanste i ad e fraite e sanglente,<br>Tant gunfanun rumpu e tant’enseigne&#160;!<br>Tant bon Franceis i perdent lor juvente&#160;!<br>Ne reverront lor meres ne lor femmes,<br>Ne cels de France ki as porz les atendent. AOI.<br>Karles li magnes en pluret, si se dementet.<br>De ço qui calt&#160;? N’en avrunt sucurance.<br>Malvais servise le jur li rendit Guenes,<br>Qu’en Sarraguce sa maisnee alat vendre&#160;;<br>Puis en perdit e sa vie e ses membres&#160;;<br>El plait ad Ais en fut juget a pendre,<br>De ses parenz ensembl’ od lui tels trente<br>Ki de murir nen ourent esperance. AOI.</p>" },
    { n: 110, html: "<p><span class=\"bk-n\">110</span> La bataille est merveilluse e pesant.<br>Mult ben i fiert Oliver e Rollant,<br>Li arcevesques plus de mil colps i rent,<br>Li .XII. per ne s’en targent nient,<br>E li Franceis i fierent cumunement.<br>Moerent paien a millers e a cent&#160;:<br>Ki ne s’en fuit de mort n’i ad guarent&#160;;<br>Voillet o nun, tut i laisset sun tens.<br>Franceis i perdent lor meillors garnemenz.<br>Ne reverrunt lor peres ne lor parenz,<br>Ne Carlemagne ki as porz les atent.<br>En France en ad mult merveillus turment&#160;:<br>Orez i ad de tuneire e de vent,<br>Pluies e gresilz desmesureement&#160;;<br>Chiedent i fuildres e menut e suvent,<br>E terremoete ço i ad veirement.<br>De seint Michel del Peril josqu’as Seinz,<br>Dès Besençun tresqu’al port de Guitsand,<br>N’en ad recet dunt del mur ne cravent.<br>Cuntre midi tenebres i ad granz.<br>N’i ad clartet, se li ciels nen i fent.<br>Hume nel veit ki mult ne s’espaent.<br>Dient plusor&#160;: «&#160;Ço est li definement,<br>La fin del secle ki nus est en present.&#160;»<br>Il nel sevent, ne dient veir nient&#160;:<br>Ço est li granz dulors por la mort de Rollant.</p>" },
    { n: 111, html: "<p><span class=\"bk-n\">111</span> Franceis i unt ferut de coer e de vigur&#160;;<br>Paien sunt morz a millers e a fuls&#160;:<br>De cent millers n’en poent guarir dous.<br>Dist l’arcevesques&#160;: «&#160;Nostre hume sunt mult proz&#160;;<br>Suz ciel n’ad home plus en ait de meillors.<br>Il est escrit en la Geste Francor<br>Que vassals est li nostre empereür.&#160;»<br>Vunt par le camp, si requerent les lor,<br>Plurent des oilz de doel e de tendrur<br>Por lor parenz par coer e par amor.<br>Li reis Marsilie od sa grant ost lor surt. AOI.</p>" },
    { n: 112, html: "<p><span class=\"bk-n\">112</span> Marsilie vient par mi une valee<br>Od sa grant ost que il out asemblee.<br>.XX. escheles ad li reis anumbrees.<br>Luisent cil elme as perres d’or gemmees,<br>E cil escuz e cez bronies sasfrees.<br>.VII. milie graisles i sunent la menee,<br>Grant est la noise par tute la contree.<br>Ço dist Rollant&#160;: «&#160;Oliver, compaign, frere,<br>Guenes li fels ad nostre mort juree.<br>La traïsun ne poet estre celee&#160;;<br>Mult grant venjance en prendrat l’emperere.<br>Bataille avrum e forte e aduree,<br>Unches mais hom tel ne vit ajustee.<br>Jo i ferrai de Durendal, m’espee,<br>E vos, compainz, ferrez de Halteclere.<br>En tanz lius les avum nos portees&#160;!<br>Tantes batailles en avum afinees&#160;!<br>Male chançun n’en deit estre cantee.&#160;» AOI.</p>" },
    { n: 113, html: "<p><span class=\"bk-n\">113</span> Marsilies veit de sa gent le martirie,<br>Si fait suner ses cors e ses buisines,<br>Puis si chevalchet od sa grant ost banie.<br>Devant chevalchet un Sarrazin, Abisme&#160;:<br>Plus fel de lui n’out en sa cumpagnie.<br>Teches ad males e mult granz felonies&#160;;<br>Ne creit en Deu, le filz seinte Marie&#160;;<br>Issi est neirs cume peiz ki est demise&#160;;<br>Plus aimet il traïsun e murdrie<br>Qu’il ne fesist trestut l’or de Galice&#160;;<br>Unches nuls hom nel vit juer ne rire.<br>Vasselage ad e mult grant estultie&#160;:<br>Por ço est drud al felun rei Marsilie&#160;;<br>Sun dragun portet a qui sa gent s’alient.<br>Li arcevesque ne l’amerat ja mie&#160;;<br>Cum il le vit, a ferir le desiret.<br>Mult quiement le dit a sei meïsme&#160;:<br>«&#160;Cel Sarrazin me semblet mult herite&#160;;<br>Mielz est mult que jo l’alge ocire.<br>Unches n’amai cuard ne cuardie.&#160;» AOI.</p>" },
    { n: 114, html: "<p><span class=\"bk-n\">114</span> Li arcevesque cumencet la bataille.<br>Siet el cheval qu’il tolit a Grossaille,<br>Ço ert uns reis qu’il ocist en Denemarche.<br>Li destrers est e curanz e aates,<br>Piez a copiez e les gambes ad plates,<br>Curte la quisse e la crupe bien large,<br>Lungs les costez e l’eschine ad ben halte,<br>Blanche la cue e la crignete jalne,<br>Petites les oreilles, la teste tute falve&#160;;<br>Beste nen est nule ki encontre lui alge.<br>Li arcevesque brochet, par tant grant vasselage&#160;!<br>Ne laisserat qu’Abisme nen asaillet.<br>Vait le ferir en l’escut amiracle&#160;:<br>Pierres i ad, ametistes e topazes,<br>Esterminals e carbuncles ki ardent&#160;;<br>En Val Metas li dunat uns diables,<br>Si li tramist li amiralz Galafes.<br>Turpins i fiert, ki nient ne l’esparignet,<br>Enprès sun colp ne quid qu’un dener vaillet,<br>Le cors li trenchet trés l’un costet qu’a l’altre,<br>Que mort l’abat en une voide place.<br>Dient Franceis&#160;: «&#160;Ci ad grant vasselage&#160;!<br>En l’arcevesque est ben la croce salve.&#160;»</p>" },
    { n: 115, html: "<p><span class=\"bk-n\">115</span> Franceis veient que paiens i ad tant,<br>De tutes parz en sunt cuvert li camp.<br>Suvent regretent Oliver e Rollant,<br>Les .XII. pers, qu’il lor seient guarant.<br>E l’arcevesque lur dist de sun semblant&#160;:<br>«&#160;Seignors barons, n’en alez mespensant&#160;!<br>Pur Deu vos pri que ne seiez fuiant,<br>Que nuls prozdom malvaisement n’en chant.<br>Asez est mielz que moerium cumbatant.<br>Pramis nus est fin prendrum a itant,<br>Ultre cest jurn ne serum plus vivant&#160;;<br>Mais d’une chose vos soi jo ben guarant&#160;:<br>Seint pareïs vos est abandunant&#160;;<br>As Innocenz vos en serez seant.&#160;»<br>A icest mot si s’esbaldissent Franc<br>Cel nen i ad Munjoie ne demant. AOI.</p>" },
    { n: 116, html: "<p><span class=\"bk-n\">116</span> Un Sarrazin i out de Sarraguce,<br>De la citet l’une meitet est sue&#160;:<br>Ço est Climborins, ki pas ne fut produme.<br>Fiance prist de Guenelun le cunte,<br>Par amistiet l’en baisat en la buche,<br>Si l’en dunat sun helme e s’escarbuncle.<br>Tere Major, ço dit, metrat a hunte,<br>A l’emperere si toldrat la curone.<br>Siet el ceval qu’il cleimet Barbamusche,<br>Plus est isnels qu’esprever ne arunde.<br>Brochet le bien, le frein li abandunet,<br>Si vait ferir Engeler de Guascoigne.<br>Nel poet guarir sun escut ne sa bronie&#160;:<br>De sun espiet el cors li met la mure,<br>Empeint le ben, tut le fer li mist ultre,<br>Pleine sa hanste el camp mort le tresturnet.<br>Après escriet&#160;: «&#160;Cist sunt bon a cunfundre&#160;!<br>Ferez, paien, pur la presse derumpre&#160;!&#160;»<br>Dient Franceis&#160;: «&#160;Deus, quel doel de prodome&#160;!&#160;» AOI.</p>" },
    { n: 117, html: "<p><span class=\"bk-n\">117</span> Li quens Rollant en apelet Oliver&#160;:<br>«&#160;Sire cumpainz, ja est morz Engeler&#160;;<br>Nus n’avium plus vaillant chevaler.&#160;»<br>Respont li quens&#160;: «&#160;Deus le me doinst venger&#160;!&#160;»<br>Sun cheval brochet des esperuns d’or mier,<br>Tient Halteclere, sanglent en est l’acer,<br>Par grant vertut vait ferir le paien.<br>Brandist sun colp e li Sarrazins chiet&#160;;<br>L’anme de lui en portent aversers.<br>Puis ad ocis le duc Alphaïen&#160;;<br>Escababi i ad le chef trenchet&#160;;<br>.VII. Arrabiz i ad deschevalcet&#160;:<br>Cil ne sunt proz ja mais pur guerreier.<br>Ço dist Rollant&#160;: «&#160;Mis cumpainz est irez&#160;!<br>Encontre mei fait asez a preiser.<br>Pur itels colps nos ad Charles plus cher.&#160;»<br>A voiz escriet&#160;: «&#160;Ferez i, chevaler&#160;!&#160;» AOI.</p>" },
    { n: 118, html: "<p><span class=\"bk-n\">118</span> D’altre part est un paien, Valdabrun&#160;:<br>Celoi levat le rei Marsiliun.<br>Sire est par mer de .IIII. C. drodmunz&#160;;<br>N’i ad eschipre quis cleimt se par loi nun.<br>&#160;Jerusalem prist ja par traïsun,<br>Si violat le temple Salomon,<br>Le patriarche ocist devant les funz.<br>Cil ot fiance del cunte Guenelon&#160;:<br>Il li dunat s’espee e mil manguns.<br>Siet el cheval qu’il cleimet Gramimund,<br>Plus est isnels que nen est uns falcuns.<br>Brochet le bien des aguz esperuns,<br>Si vait ferir li riche duc Sansun.<br>L’escut li freint e l’osberc li derumpt,<br>El cors li met les pans del gunfanun,<br>Pleine sa hanste l’abat mort des arçuns.....<br>«&#160;Ferez, paien, car trés ben les veintrum&#160;!&#160;»<br>Dient Franceis&#160;: «&#160;Deus, quel doel de baron&#160;!&#160;» AOI.</p>" },
    { n: 119, html: "<p><span class=\"bk-n\">119</span> Li quens Rollant, quant il veit Sansun mort,<br>Poez saveir que mult grant doel en out.<br>Sun ceval brochet, si li curt ad esforz.<br>Tient Durendal, qui plus valt que fin or&#160;;<br>Vait le ferir li bers, quanque il pout,<br>Desur sun elme, ki gemmet fut ad or,<br>Trenchet la teste e la bronie e le cors,<br>La bone sele, ki est gemmet ad or,<br>E al cheval parfundement le dos&#160;;<br>Ambure ocit, ki quel blasme ne quil lot.<br>Dient paien&#160;: «&#160;Cist colp nus est mult fort&#160;!&#160;»<br>Respont Rollant&#160;: «&#160;Ne pois amer les voz&#160;;<br>Devers vos est li orguilz e li torz.&#160;» AOI.</p>" },
    { n: 120, html: "<p><span class=\"bk-n\">120</span> D’affrike i ad un Affrican venut,<br>Ço est Malquiant, le filz al rei Malcud.<br>Si guarnement sunt tut a or batud&#160;:<br>Cuntre le ciel sur tuz les altres luist.<br>Siet el ceval qu’il cleimet Salt Perdut&#160;:<br>Beste nen est ki poisset curre a lui.<br>Il vait ferir Anseïs en l’escut&#160;:<br>Tut li trenchat le vermeill e l’azur&#160;;<br>De sun osberc li ad les pans rumput,<br>El cors li met e le fer e le fust&#160;;<br>Morz est li quens, de sun tens n’i ad plus.<br>Dient Franceis&#160;: «&#160;Barun, tant mare fus&#160;!&#160;»</p>" },
    { n: 121, html: "<p><span class=\"bk-n\">121</span> Par le camp vait Turpin, li arcevesque.<br>Tel coronet ne chantat unches messe<br>Ki de sun cors feïst tantes proecces.<br>Dist al paien&#160;: «&#160;Deus tut mal te tramette&#160;!<br>Tel as ocis dunt al coer me regrette.&#160;»<br>Sun bon ceval i ad fait esdemetre,<br>Si l’ad ferut sur l’escut de Tulette<br>Que mort l’abat desur l’herbe verte……<br>. . . . . . . . . . . . . . . . . . . . .</p>" },
    { n: 122, html: "<p><span class=\"bk-n\">122</span> De l’altre part est un paien, Grandonies,<br>Filz Capuel, le rei de Capadoce.<br>Siet el cheval que il cleimet Marmorie,<br>Plus est isnels que n’est oisel ki volet.<br>Laschet la resne, des esperuns le brochet,<br>Si vait ferir Gerin par sa grant force.<br>L’escut vermeill li freint, de col li portet&#160;;<br>Aprof li ad sa bronie desclose,<br>El cors li met tute l’enseingne bloie,<br>Que mort l’abat en une halte roche.<br>Sun cumpaignun Gerers ocit uncore<br>E Berenger e Guiun de Seint Antonie&#160;;<br>Puis vait ferir un riche duc, Austorje.<br>Ki tint Valence e Envers sur le Rosne.<br>Il l’abat mort, paien en unt grant joie.<br>Dient Franceis&#160;: «&#160;Mult decheent li nostre&#160;!&#160;»</p>" },
    { n: 123, html: "<p><span class=\"bk-n\">123</span> Li quens Rollant tint s’espee sanglente.<br>Ben ad oït que Franceis se dementent&#160;;<br>Si grant doel ad que par mi quiet fendre&#160;;<br>Dist al paien&#160;: «&#160;Deus tut mal te consente&#160;!<br>Tel as ocis que mult cher te quid vendre&#160;!&#160;»<br>Sun ceval brochet, ki [oït del cuntence].<br>Ki quel cumpert, venuz en sunt ensemble.</p>" },
    { n: 124, html: "<p><span class=\"bk-n\">124</span> Grandonie fut e prozdom e vaillant<br>E vertuus e vassal cumbatant.<br>En mi sa veie ad encuntret Rollant.<br>Enceis nel vit, sil recunut veirement<br>Al fier visage e al cors qu’il out gent<br>E al reguart e al contenement&#160;:<br>Ne poet muer qu’il ne s’en espaent.<br>Fuïr s’en voel, mais ne li valt nient&#160;:<br>Li quens le fiert tant vertuusement<br>Tresqu’al nasel tut le elme li fent,<br>Trenchet le nés e la buche e les denz.<br>Trestut le cors e l’osberc jazerenc,<br>De l’oree sele lé dous alves d’argent<br>E al ceval le dos parfundement&#160;;<br>Ambure ocist seinz nul recoevrement,<br>E cil d’Espaigne s’en cleiment tuit dolent.<br>Dient Franceis&#160;: «&#160;Ben fiert nostre guarent&#160;!&#160;»</p>" },
    { n: 125, html: "<p><span class=\"bk-n\">125</span> La bataille est merveilluse e hastive.<br>Franceis i ferent par vigur e par ire,<br>Trenchent cez poinz, cez costez, cez eschines,<br>Cez vestemenz entresque as chars vives.<br>Sur l’erbe verte li cler sancs s’en afilet.....<br>. . . . . . . . . . . . . . . . . . . . . . .<br>«&#160;Tere Major, Mahummet te maldie&#160;!<br>Sur tute gent est la tue hardie.&#160;»<br>Cel nen i ad ki ne criet&#160;: «&#160;Marsilie&#160;!<br>Cevalche, rei&#160;! Bosuign avum d’aïe&#160;!&#160;»</p>" },
    { n: 126, html: "<p><span class=\"bk-n\">126</span> La bataille est e merveillose e grant.<br>Franceis i ferent des espiez brunisant.<br>La veïssez si grant dulor de gent,<br>Tant hume mort e nasfret e sanglent&#160;!<br>L’un gist sur l’altre e envers e adenz.<br>Li Sarrazin nel poent susfrir tant&#160;:<br>Voelent u nun, si guerpissent le camp.<br>Par vive force les encacerent Franc. AOI.</p>" },
    { n: 127, html: "<p><span class=\"bk-n\">127</span> Li quens Rollant apelet Oliver&#160;:<br>«&#160;Sire cumpaign, sel volez otrier,<br>Li arcevesque est mult bon chevaler,<br>N’en ad meillor en tere ne suz cel&#160;;<br>Ben set ferir e de lance e d’espiet.&#160;»<br>Respunt li quens&#160;: «&#160;Kar li aluns aider&#160;!&#160;»<br>A icest mot l’unt Francs recumencet.<br>Dur sunt li colps e li caples est grefs&#160;;<br>Mult grant dulor i ad de chrestiens.<br>Ki puis veïst Rollant e Oliver<br>De lur espees e ferir e capler&#160;!<br>Li arcevesque i fiert de sun espiet.<br>Cels qu’il unt mort, ben les poet hom preiser,<br>Il est escrit es cartres e es brefs,<br>Ço dit la Geste, plus de .IIII. milliers.<br>As quatre turs lor est avenut ben&#160;;<br>Li quint après lor est pesant e gref.<br>Tuz sunt ocis cist Franceis chevalers,<br>Ne mès seisante, que Deus i ad esparniez&#160;:<br>Einz que il moergent se vendrunt mult cher. AOI.</p>" },
    { n: 128, html: "<p><span class=\"bk-n\">128</span> Li quens Rollant des soens i veit grant perte.<br>Sun cumpaignun Oliver en apelet&#160;:<br>«&#160;Bel sire, chers cumpainz, pur Deu, que vos en haitet&#160;?<br>Tanz bons vassals veez gesir par tere&#160;!<br>Pleindre poüms France dulce, la bele.<br>De tels barons cum or remeint deserte&#160;!<br>E&#160;! reis, amis, que vos ici nen estes&#160;?<br>Oliver, frere, cum le purrum nus faire&#160;?<br>Cumfaitement li manderum nuveles&#160;?&#160;»<br>Dist Oliver&#160;: «&#160;Jo nel sai cument quere.<br>Mielz voeill murir que hunte nus seit retraite.&#160;» AOI.</p>" },
    { n: 129, html: "<p><span class=\"bk-n\">129</span> Ço dist Rollant&#160;: «&#160;Cornerai l’olifant,<br>Si l’orrat Carles, ki est as porz passant.<br>Jo vos plevis ja returnerunt Franc.&#160;»<br>Dist Oliver&#160;: «&#160;Vergoigne sereit grant<br>E repruver a trestuz voz parenz&#160;;<br>Iceste hunte dureit al lur vivant&#160;!<br>Quant jel vos dis, n’en feïstes nient&#160;;<br>Mais nel ferez par le men loement.<br>Se vos cornez, n’er mie hardement.<br>Ja avez vos ambsdous les braz sanglanz&#160;!&#160;»<br>Respont li quens&#160;: «&#160;Colps i ai fait mult genz&#160;!&#160;» AOI.</p>" },
    { n: 130, html: "<p><span class=\"bk-n\">130</span> Ço dit Rollant&#160;: «&#160;Forz est nostre bataille&#160;;<br>Jo cornerai, si l’orrat li reis Karles.&#160;»<br>Dist Oliver&#160;: «&#160;Ne sereit vasselage&#160;!<br>Quant jel vos dis, cumpainz, vos ne deignastes.<br>S’i fust li reis, n’i oüsum damage.<br>Cil ki la sunt n’en deivent aveir blasme.&#160;»<br>Dist Oliver&#160;: «&#160;Par ceste meie barbe,<br>Se puis veeir ma gente sorur Alde,<br>Ne jerreiez ja mais entre sa brace&#160;!&#160;» AOI.</p>" },
    { n: 131, html: "<p><span class=\"bk-n\">131</span> Ço dist Rollant&#160;: «&#160;Por quei me portez ire&#160;?&#160;»<br>E il respont&#160;: «&#160;Cumpainz, vos le feïstes,<br>Kar vasselage par sens nen est folie&#160;;<br>Mielz valt mesure que ne fait estultie.<br>Franceis sunt morz par vostre legerie.<br>Jamais Karlon de nus n’avrat servise.<br>Sem creïsez, venuz i fust mi sire&#160;;<br>Ceste bataille oüsum [faite u prise]<br>U pris u mort i fust li reis Marsilie.<br>Vostre proecce, Rollant, mar la veïmes&#160;!<br>Karles li Magnes de nos n’avrat aïe.<br>N’ert mais tel home dès qu’a Deu juïse.<br>Vos i murrez e France en ert hunie.<br>Oi nus defalt la leial cumpaignie&#160;:<br>Einz le vespre mult ert gref la departie.&#160;» AOI.</p>" },
    { n: 132, html: "<p><span class=\"bk-n\">132</span> Li arcevesques les ot cuntrarïer,<br>Le cheval brochet des esperuns d’or mer,<br>Vint tresqu’a els, sis prist a castïer&#160;:<br>«&#160;Sire Rollant, e vos, sire Oliver,<br>Pur Deu vos pri, ne vos cuntralïez&#160;!<br>Ja li corners ne nos avreit mester,<br>Mais nepurquant si est il asez melz&#160;:<br>Venget li reis, si nus purrat venger&#160;;<br>Ja cil d’Espaigne ne s’en deivent turner liez.<br>Nostre Franceis i descendrunt a pied,<br>Truverunt nos e morz e detrenchez,<br>Leverunt nos en bieres sur sumers,<br>Si nus plurrunt de doel e de pitet,<br>Enfuerunt nos en aitres de musters&#160;;<br>N’en mangerunt ne lu ne porc ne chen.&#160;»<br>Respunt Rollant&#160;: «&#160;Sire, mult dites bien.&#160;» AOI.</p>" },
    { n: 133, html: "<p><span class=\"bk-n\">133</span> Rollant ad mis l’olifan a sa buche,<br>Empeint le ben, par grant vertut le sunet.<br>Halt sunt li pui e la voiz est mult lunge,<br>Granz .XXX. liwes l’oïrent il respundre.<br>Karles l’oït e ses cumpaignes tutes.<br>Ço dit li reis&#160;: «&#160;Bataille funt nostre hume&#160;!&#160;»<br>E Guenelun li respundit encuntre&#160;:<br>«&#160;S’altre le desist, ja semblast grant mençunge&#160;!&#160;» AOI.</p>" },
    { n: 134, html: "<p><span class=\"bk-n\">134</span> Li quens Rollant, par peine e par ahans,<br>Par grant dulor sunet sun olifan.<br>Par mi la buche en salt fors li cler sancs.<br>De sun cervel le temple en est rumpant.<br>Del corn qu’il tient l’oïe en est mult grant&#160;:<br>Karles l’entent, ki est as porz passant.<br>Naimes li duc l’oïd, si l’escultent li Franc.<br>Ce dist li reis&#160;: «&#160;Jo oi le corn Rollant&#160;!<br>Unc nel sunast, se ne fust cumbatant.&#160;»<br>Guenes respunt&#160;: «&#160;De bataille est nient&#160;!<br>Ja estes veilz e fluriz e blancs&#160;;<br>Par tels paroles vus resemblez enfant.<br>Asez savez le grant orgoill Rollant&#160;;<br>Ço est merveille que Deus le soefret tant.<br>Ja prist il Noples seinz le vostre comant&#160;;<br>Fors s’en eissirent li Sarrazins dedenz,<br>Sis cumbatirent al bon vassal Rollant,<br>Puis od les ewes lavat les prez del sanc&#160;;<br>Pur cel le fist ne fust […]arissant.<br>Pur un sul levre vait tute jur cornant.<br>Devant ses pers vait il ore gabant.<br>Suz cel n’ad gent ki l’osast querre en champ.<br>Car chevalcez&#160;! Pur qu’alez arestant&#160;?<br>Tere Major mult est loinz ça devant.&#160;» AOI.</p>" },
    { n: 135, html: "<p><span class=\"bk-n\">135</span> Li quens Rollant ad la buche sanglente.<br>De sun cervel rumput en est li temples.<br>L’olifan sunet a dulor e a peine.<br>Karles l’oït e ses Franceis l’entendent.<br>Ço dist li reis&#160;: «&#160;Cel corn ad lunge aleine&#160;!&#160;»<br>Respont dux Neimes&#160;: «&#160;Baron i fait la peine&#160;!<br>Bataille i ad, par le men escientre.<br>Cil l’at traït ki vos en roevet feindre.<br>Adubez vos, si criez vostre enseigne,<br>Si sucurez vostre maisnee gente&#160;:<br>Asez oez que Rollant se dementet&#160;!&#160;»</p>" },
    { n: 136, html: "<p><span class=\"bk-n\">136</span> Li empereres ad fait suner ses corns.<br>Franceis descendent, si adubent lor cors<br>D’osbercs e de helmes e d’espees a or.<br>Escuz unt genz e espiez granz e forz,<br>E gunfanuns blancs e vermeilz e blois.<br>Es destrers muntent tuit li barun de l’ost,<br>Brochent ad ait tant cum durent li port.<br>N’i ad celoi a l’altre ne parolt&#160;:<br>«&#160;Se veïssum Rollant einz qu’il fust mort,<br>Ensembl’ od lui i durriums granz colps.&#160;»<br>De ço qui calt&#160;? car demuret i unt trop.</p>" },
    { n: 137, html: "<p><span class=\"bk-n\">137</span> Esclargiz est li vespres e li jurz.<br>Cuntre le soleil reluisent cil adub,<br>Osbercs e helmes i getent grant flabur,<br>E cil escuz, ki ben sunt peinz a flurs,<br>E cil espiez, cil oret gunfanun.<br>Li empereres cevalchet par irur<br>E li Franceis dolenz e curoçus&#160;;<br>N’i ad celoi ki durement ne plurt,<br>E de Rollant sunt en grant poür.<br>Li reis fait prendre le cunte Guenelun,<br>Sil cumandat as cous de sa maisun.<br>Tut li plus maistre en apelet, Besgun&#160;:<br>«&#160;Ben le me guarde, si cume tel felon&#160;!<br>De ma maisnee ad faite traïsun.&#160;»<br>Cil le receit, s’i met .C. cumpaignons<br>De la quisine des mielz e des peiurs.<br>Icil li peilent la barbe e les gernuns,<br>Cascun le fiert .IIII. colps de son puign,<br>Ben le batirent a fuz e a bastuns<br>E si li metent el col un caeignun,<br>Si l’encaeinent altresi cum un urs&#160;;<br>Sur un sumer l’unt mis a deshonor.<br>Tant le guardent quel rendent a Charlun.</p>" },
    { n: 138, html: "<p><span class=\"bk-n\">138</span> Halt sunt li pui e tenebrus e grant, AOI.<br>Li val parfunt e les ewes curant.<br>Sunent cil graisle e derere e devant<br>E tuit rachatent encuntre l’olifant.<br>Li empereres chevalchet ireement<br>E li Franceis curuçus e dolent&#160;;<br>N’i ad celoi n’i plurt e se dement,<br>E prient Deu qu’il guarisset Rollant<br>Josque il vengent el camp cumunement&#160;:<br>Ensembl’ od lui i ferrunt veirement.<br>De ço qui calt&#160;? car ne lur valt nient.<br>Demurent trop, n’i poedent estre a tens. AOI.</p>" },
    { n: 139, html: "<p><span class=\"bk-n\">139</span> Par grant irur chevalchet li reis Charles&#160;;<br>Desur sa brunie li gist sa blanche barbe.<br>Puignent ad ait tuit li barun de France&#160;;<br>N’i ad icel ne demeint irance<br>Que il ne sunt a Rollant le cataigne,<br>Ki se cumbat as Sarrazins d’Espaigne,<br>Si est blecet, ne quit qu’anme i remaigne.<br>Deus&#160;! quels seisante humes i ad en sa cumpaigne&#160;!<br>Unches meillurs n’en out reis ne cataignes. AOI.</p>" },
    { n: 140, html: "<p><span class=\"bk-n\">140</span> Rollant reguardet es munz e es lariz&#160;;<br>De cels de France i veit tanz morz gesir,<br>E il les pluret cum chevaler gentill&#160;:<br>«&#160;Seignors barons, de vos ait Deus mercit&#160;!<br>Tutes voz anmes otreit il pareïs&#160;!<br>En seintes flurs il les facet gesir&#160;!<br>Meillors vassals de vos unkes ne vi.<br>Si lungement tuz tens m’avez servit,<br>A oes Carlon si granz païs cunquis&#160;!<br>Li empereres tant mare vos nurrit&#160;!<br>Tere de France, mult estes dulz païs,<br>Oi desertet [a tant rubostl exill].<br>Barons franceis, pur mei vos vei murir&#160;:<br>Jo ne vos pois tenser ne guarantir&#160;;<br>Aït vos Deus, ki unkes ne mentit&#160;!<br>Oliver frere, vos ne dei jo faillir.<br>De doel murra, s’altre ne m’i ocit.<br>Sire cumpainz, alum i referir&#160;!&#160;»</p>" },
    { n: 141, html: "<p><span class=\"bk-n\">141</span> Li quens Rollant el champ est repairet.<br>Tient Durendal, cume vassal i fiert.<br>Faldrun de Pui i ad par mi trenchet,<br>E .XXIIII. de tuz les melz preisez&#160;:<br>Jamais n’iert home plus se voeillet venger.<br>Si cum li cerfs s’en vait devant les chiens,<br>Devant Rollant si s’en fuient paiens.<br>Dist l’arcevesque&#160;: «&#160;Asez le faites ben&#160;!<br>Itel valor deit aveir chevaler<br>Ki armes portet e en bon cheval set&#160;:<br>En bataille deit estre forz e fiers,<br>U altrement ne valt .IIII. deners,<br>Einz deit monie estre en un de cez mustiers,<br>Si prierat tuz jurz por noz peccez.&#160;»<br>Respunt Rollant&#160;: «&#160;Ferez, nes esparignez&#160;!&#160;»<br>A icest mot l’unt Francs recumencet.<br>Mult grant damage i out de chrestiens.</p>" },
    { n: 142, html: "<p><span class=\"bk-n\">142</span> Home ki ço set que ja n’avrat prisun<br>En tel bataill fait grant defension&#160;:<br>Pur ço sunt Francs si fiers cume leuns.<br>As vus Marsilie en guise de barun.<br>Siet el cheval qu’il apelet Gaignun,<br>Brochet le ben, si vait ferir Bevon&#160;:<br>Icil ert sire de Belne e de Digun.<br>L’escut li freint e l’osberc li derumpt,<br>Que mort l’abat seinz altre descunfisun,<br>Puis ad ocis Yvoeries e Ivon,<br>Ensembl’ od els Gerard de Russillun.<br>Li quens Rollant ne li est guaires loign&#160;;<br>Dist al paien&#160;: «&#160;Damnesdeus mal te duinst&#160;!<br>A si grant tort m’ociz mes cumpaignuns&#160;!<br>Colp en avras einz que nos departum.<br>E de m’espee enquoi savras le nom.&#160;»<br>Vait le ferir en guise de baron.<br>Trenchet li ad li quens le destre poign,<br>Puis prent la teste de Jurfaleu le blund&#160;;<br>Icil ert filz al rei Marsiliun.<br>Paien escrient&#160;: «&#160;Aïe nos, Mahum&#160;!<br>Li nostre deu, vengez nos de Carlun&#160;!<br>En ceste tere nus ad mis tels feluns<br>Ja pur murir le camp ne guerpirunt.&#160;»<br>Dist l’un a l’altre&#160;: «&#160;E&#160;! car nos en fuiums&#160;!&#160;»<br>A icest mot tels .C. milie s’en vunt,<br>Ki ques rapelt, ja n’en returnerunt. AOI.</p>" },
    { n: 143, html: "<p><span class=\"bk-n\">143</span> De ço qui calt&#160;? Se fuït s’en est Marsilies,<br>Remés i est sis uncles, Marganices,<br>Ki tint Kartagene [al frere Garmalie]<br>E Ethiope, une tere maldite.<br>La neire gent en ad en sa baillie&#160;;<br>Granz unt les nés e lees les oreilles,<br>E sunt ensemble plus de cinquante milie.<br>Icil chevalchent fierement e a ire,<br>Puis escrient l’enseigne paenime.<br>Ço dist Rollant&#160;: «&#160;Ci recevrums matyrie,<br>E or sai ben n’avons guaires a vivre&#160;;<br>Mais tut seit fel cher ne se vende primes&#160;!<br>Ferez, seignurs, des espees furbies,<br>Si calengez e voz morz e voz vies,<br>Que dulce France par nus ne seit hunie&#160;!<br>Quant en cest camp vendrat Carles, mi sire,<br>De Sarrazins verrat tel discipline<br>Cuntre un des noz en truverat morz .XV.,<br>Ne lesserat que nos ne beneïsse.&#160;» AOI.</p>" },
    { n: 144, html: "<p><span class=\"bk-n\">144</span> Quan Rollant veit la contredite gent<br>Ki plus sunt neirs que nen est arrement<br>Ne n’unt de blanc ne mais que sul les denz,<br>Ço dist li quens&#160;: «&#160;Or sai jo veirement<br>Que hoi murrum par le mien escient.<br>Ferez, Franceis, car jol vos recumenz&#160;!&#160;»<br>Dist Oliver&#160;: «&#160;Dehet ait li plus lenz&#160;!&#160;»<br>A icest mot Franceis se fierent enz.</p>" },
    { n: 145, html: "<p><span class=\"bk-n\">145</span> Quant paien virent que Franceis i out poi,<br>Entr’els en unt e orgoil e cunfort.<br>Dist l’un a l’altre&#160;: «&#160;L’empereor ad tort.&#160;»<br>Li Marganices sist sur un ceval sor,<br>Brochet le ben des esperuns a or,<br>Fiert Oliver derere en mi le dos.<br>Le blanc osberc li ad descust el cors,<br>Par mi le piz sun espiet li mist fors,<br>E dit après&#160;: «&#160;Un col avez pris fort&#160;!<br>Carles li Magnes mar vos laissat as porz&#160;!<br>Tort nos ad fait, nen est dreiz qu’il s’en lot,<br>Kar de vos sul ai ben venget les noz.&#160;»</p>" },
    { n: 146, html: "<p><span class=\"bk-n\">146</span> Oliver sent que a mort est ferut.<br>Tient Halteclere, dunt li acer fut bruns,<br>Fiert Marganices sur l’elme a or, agut,<br>E flurs e cristaus en acraventet jus&#160;;<br>Trenchet la teste d’ici qu’as denz menuz,<br>Brandist sun colp, si l’ad mort abatut,<br>E dist après&#160;: «&#160;Paien, mal aies tu&#160;!<br>Iço ne di que Karles n’i ait perdut.<br>Ne a muiler ne a dame qu’aies veüd<br>N’en vanteras el regne dunt tu fus<br>Vaillant a un dener que m’i aies tolut,<br>Ne fait damage ne de mei ne d’altrui.&#160;»<br>Après escriet Rollant qu’il li aiut. AOI.</p>" },
    { n: 147, html: "<p><span class=\"bk-n\">147</span> Oliver sent qu’il est a mort nasfret.<br>De lui venger ja mais ne li ert sez.<br>En la grant presse or i fiert cume ber,<br>Trenchet cez hanstes e cez escuz buclers<br>E piez e poinz e seles e costez.<br>Ki lui veïst Sarrazins desmembrer,<br>Un mort sur altre geter,<br>De bon vassal li poüst remembrer.<br>L’enseigne Carle n’i volt mie ublier,<br>«&#160;Munjoie&#160;!&#160;» escriet e haltement e cler,<br>Rollant apelet, sun ami e sun per&#160;:<br>«&#160;Sire cumpaign, a mei car vus justez&#160;!<br>A grant dulor ermes hoi desevrez.&#160;» AOI.</p>" },
    { n: 148, html: "<p><span class=\"bk-n\">148</span> Rollant reguardet Oliver al visage&#160;:<br>Teint fut e pers, desculuret e pale.<br>Li sancs tuz clers par mi le cors li raiet,<br>Encuntre tere en cheent les esclaces.<br>«&#160;Deus&#160;!&#160;» dist li quens, «&#160;or ne sai jo que face.<br>Sire cumpainz, mar fut vostre barnage&#160;!<br>Jamais n’iert hume ki tun cors cuntrevaillet.<br>E&#160;! France dulce, cun hoi remendras guaste<br>De bons vassals, cunfundue e chaiete&#160;!<br>Li emperere en avrat grant damage.&#160;»<br>A icest mot sur sun cheval se pasmet. AOI.</p>" },
    { n: 149, html: "<p><span class=\"bk-n\">149</span> As vus Rollant sur sun cheval pasmet<br>E Oliver ki est a mort naffret.<br>Tant ad seinet li oil li sunt trublet.<br>Ne loinz ne près ne poet vedeir si cler<br>Que reconoistre poisset nuls hom mortel.<br>Sun cumpaignun, cum il l’at encuntret,<br>Sil fiert amunt sur l’elme a or gemet,<br>Tut li detrenchet d’ici qu’al nasel&#160;;<br>Mais en la teste ne l’ad mie adeset.<br>A icel colp l’ad Rollant reguardet,<br>Si li demandet dulcement e suef&#160;:<br>«&#160;Sire cumpain, faites le vos de gred&#160;?<br>Ja est ço Rollant, ki tant vos soelt amer&#160;!<br>Par nule guise ne m’aviez desfiet&#160;!&#160;»<br>Dist Oliver&#160;: «&#160;Or vos oi jo parler.<br>Jo ne vos vei, veied vus Damnedeu&#160;!<br>Ferut vos ai, car le me pardunez&#160;!&#160;»<br>Rollant respunt&#160;: «&#160;Jo n’ai nient de mel.<br>Jol vos parduins ici e devant Deu.&#160;»<br>A icel mot l’un a l’altre ad clinet.<br>Par tel amur as les vus desevred.</p>" },
    { n: 150, html: "<p><span class=\"bk-n\">150</span> Oliver sent que la mort mult l’angoisset.<br>Ansdous les oilz en la teste li turnent,<br>L’oïe pert e la veüe tute&#160;;<br>Descent a piet, a la tere se culchet,<br>Durement en halt si recleimet sa culpe,<br>Cuntre le ciel ambesdous ses mains juintes,<br>Si priet Deu que pareïs li dunget<br>E beneïst Karlun e France dulce,<br>Sun cumpaignun Rollant sur tuz humes.<br>Falt li le coer, le helme li embrunchet,<br>Trestut le cors a la tere li justet.<br>Morz est li quens, que plus ne se demuret.<br>Rollant li ber le pluret, sil duluset&#160;;<br>Jamais en tere n’orrez plus dolent hume.</p>" },
    { n: 151, html: "<p><span class=\"bk-n\">151</span> Or veit Rollant que mort est sun ami,<br>Gesir adenz, a la tere sun vis.<br>Mult dulcement a regreter le prist&#160;:<br>«&#160;Sire cumpaign, tant mar fustes hardiz&#160;!<br>Ensemble avum estet e anz e dis,<br>Nem fesis mal ne jo nel te forsfis.<br>Quant tu es mor, dulur est que jo vif.&#160;»<br>A icest mot se pasmet li marchis<br>Sur sun ceval que cleimet Veillantif.<br>Afermet est a ses estreus d’or fin&#160;:<br>Quel part qu’il alt, ne poet mie chaïr.</p>" },
    { n: 152, html: "<p><span class=\"bk-n\">152</span> Ainz que Rollant se seit aperceüt,<br>De pasmeisuns guariz ne revenuz.<br>Mult grant damage li est apareüt&#160;:<br>Morz sunt Franceis, tuz les i ad perdut,<br>Senz l’arcevesque e senz Gualter de l’Hum.<br>Repairez est des muntaignes jus&#160;;<br>A cels d’Espaigne mult s’i est cumbatuz&#160;;<br>Mort sunt si hume, sis unt paiens vencut&#160;;<br>Voeillet o nun, desuz cez vals s’en fuit,<br>Si reclaimet Rollant, qu’il li aiut&#160;:<br>«&#160;E&#160;! gentilz quens, vaillanz hom, u ies tu&#160;?<br>Unkes nen oi poür, la u tu fus.<br>Ço est Gualter, ki cunquist Maelgut,<br>Li niés Droün, al vieill e al canut&#160;!<br>Pur vasselage suleie estre tun drut.<br>Ma hanste est fraite e percet mun escut<br>E mis osbercs desmailet e rumput&#160;;<br>Par mi le cors. . . . . . . . . .<br>Sempres murrai, mais cher me sui vendut.&#160;»<br>A icel mot l’at Rollant entendut&#160;;<br>Le cheval brochet, si vient poignant vers lui. AOI.<br>. . . . . . . . . . . . . . . . . . . . . . . . .</p>" },
    { n: 153, html: "<p><span class=\"bk-n\">153</span> Rollant ad doel, si fut maltalentifs&#160;;<br>En la grant presse cumencet a ferir.<br>De cels d’Espaigne en ad getet mort .XX.,<br>E Gualter .VI. e l’arcevesque .V.<br>Dient paien&#160;: «&#160;Feluns humes ad ci&#160;!<br>Guardez, seignurs, qu’il n’en algent vif.<br>Tut par seit fel ki nes vait envaïr<br>E recreant ki les lerrat guarir&#160;!&#160;»<br>Dunc recumencent e le hu e le cri&#160;;<br>De tutes parz lé revunt envaïr. AOI.</p>" },
    { n: 154, html: "<p><span class=\"bk-n\">154</span> Li quens Rollant fut noble guerrer,<br>Gualter de Hums est bien bon chevaler,<br>Li arcevesque prozdom e essaiet&#160;:<br>Li uns ne volt l’altre nient laisser.<br>En la grant presse i fierent as paiens.<br>Mil Sarrazins i descendent a piet<br>E a cheval sunt .XL. millers.<br>Men escientre nes osent aproismer.<br>Il lor lancent e lances e espiez<br>E wigres e darz e museras e agiez e gieser.<br>As premers colps i unt ocis Gualter,<br>Turpins de Reins tut sun escut percet,<br>Quasset sun elme, si l’unt nasfret el chef,<br>E sun osberc rumput e desmailet,<br>Par mi le cors nasfret de .IIII. espiez&#160;;<br>Dedesuz lui ocient sun destrer.<br>Or est grant doel, quant l’arcevesque chiet. AOI.</p>" },
    { n: 155, html: "<p><span class=\"bk-n\">155</span> Turpins de Reins, quant se sent abatut,<br>De .IIII. espiez par mi le cors ferut,<br>Isnelement li ber resailit sus,<br>Rollant reguardet, puis si li est curut,<br>E dist un mot&#160;: «&#160;Ne sui mie vencut&#160;!<br>Ja bon vassal nen ert vif recreüt.&#160;»<br>Il trait Almace, s’espee d’acer brun,<br>En la grant presse mil colps i fiert e plus.<br>Puis le dist Carles qu’il n’en esparignat nul&#160;:<br>Tels .IIII. cenz i troevet entur lui,<br>Alquanz nafrez, alquanz par mi ferut,<br>S’i out d’icels ki les chefs unt perdut.<br>Ço dit la Geste e cil ki el camp fut&#160;;<br>Li ber Gilie, por qui Deus fait vertuz,<br>E fist la chartre el muster de Loüm.<br>Ki tant ne set ne l’ad prod entendut.</p>" },
    { n: 156, html: "<p><span class=\"bk-n\">156</span> Li quens Rollant gentement se cumbat,<br>Mais le cors ad tressuet e mult chalt.<br>En la teste ad e dulor e grant mal&#160;:<br>Rumput est li temples, por ço que il cornat.<br>Mais saveir volt se Charles i vendrat&#160;:<br>Trait l’olifan, fieblement le sunat.<br>Li emperere s’estut, si l’escultat&#160;:<br>«&#160;Seignurs&#160;», dist il, «&#160;mult malement nos vait&#160;!<br>Rollant mis niés hoi cest jur nus defalt.<br>Jo oi al corner que guaires ne vivrat.<br>Ki estre i voelt isnelement chevalzt&#160;!<br>Sunez voz grasles tant que en cest ost ad&#160;!&#160;»<br>Seisante milie en i cornent si halt<br>Sunent li munt e respondent li val&#160;:<br>Paien l’entendent, nel tindrent mie en gab&#160;;<br>Dit l’un a l’altre&#160;: «&#160;Karlun avrum nus ja&#160;!&#160;»</p>" },
    { n: 157, html: "<p><span class=\"bk-n\">157</span> Dient paien&#160;: «&#160;L’emperere repairet. AOI.<br>De cels de France oez suner les graisles&#160;!<br>Se Carles vient, de nus i avrat perte.<br>Se Rollant vit, nostre guerre novelet,<br>Perdud avuns Espaigne, nostre tere.&#160;»<br>Tels .IIII. cenz s’en asemblent a helmes,<br>E des meillors ki el camp quient estre&#160;:<br>A Rollant rendent un estur fort e pesme.<br>Or ad li quens endreit sei asez que faire. AOI.</p>" },
    { n: 158, html: "<p><span class=\"bk-n\">158</span> Li quens Rollant, quant il les veit venir,<br>Tant se fait fort e fiers e maneviz&#160;!<br>Ne lur lerat tant cum il serat vif.<br>Siet el cheval qu’om cleimet Veillantif,<br>Brochet le bien des esperuns d’or fin,<br>En la grant presse les vait tuz envaïr,<br>Ensembl’ od lui arcevesques Turpin.<br>Dist l’un a l’altre&#160;: «&#160;Ça vus traiez, ami&#160;!<br>De cels de France les corns avuns oït&#160;:<br>Carles repairet, li reis poesteïfs.&#160;»</p>" },
    { n: 159, html: "<p><span class=\"bk-n\">159</span> Li quens Rollant unkes n’amat cuard,<br>Ne orguillos, ne malvais hume de male part,<br>Ne chevaler, s’il ne fust bon vassal.<br>Li arcevesques Turpin en apelat&#160;:<br>«&#160;Sire, a pied estes e jo sui a ceval&#160;:<br>Pur vostre amur ici prendrai estal&#160;;<br>Ensemble avruns e le ben e le mal,<br>Ne vos lerrai pur nul hume de car.<br>Encui rendruns a paiens cest asalt.<br>Les colps des mielz, cels sunt de Durendal.&#160;»<br>Dist l’arcevesque&#160;: «&#160;Fel seit ki ben n’i ferrat&#160;!<br>Carles repairet, ki ben nus vengerat.&#160;»</p>" },
    { n: 160, html: "<p><span class=\"bk-n\">160</span> Paien dient&#160;: «&#160;Si mare fumes nez&#160;!<br>Cum pesmes jurz nus est hoi ajurnez&#160;!<br>Perdut avum noz seignurs e noz pers&#160;;<br>Carles repeiret od sa grant ost, li ber&#160;;<br>De cels de France odum les graisles clers&#160;;<br>Grant est la noise de Munjoie escrier.<br>Li quens Rollant est de tant grant fiertet<br>Ja n’ert vencut pur nul hume carnel.<br>Lançuns a lui, puis sil laissums ester.&#160;»<br>E il si firent darz e wigres asez,<br>Espiez e lances e museraz enpennez&#160;;<br>L’escut Rollant unt frait e estroet<br>E sun osberc rumput e desmailet&#160;;<br>Mais enz el cors ne l’unt mie adeset.<br>Mais Veillantif unt en .XXX. lius nafret<br>Desuz le cunte, si l’i unt mort laisset.<br>Paien s’en fuient, puis sil laisent ester.<br>Li quens Rollant i est remés a pied. AOI.</p>" },
    { n: 161, html: "<p><span class=\"bk-n\">161</span> Paien s’en fuient, curuçus e irez&#160;;<br>Envers Espaigne tendent de l’espleiter.<br>Li quens Rollant nes ad dunt encalcer&#160;:<br>Perdut i ad Veillantif, sun destrer&#160;;<br>Voeilet o nun, remés i est a piet.<br>A l’arcevesque Turpin alat aider.<br>Sun elme ad or li deslaçat del chef,<br>Si li tolit le blanc osberc leger,<br>E sun blialt li ad tut detrenchet,<br>En ses granz plaies les pans li ad butet,<br>Cuntre sun piz puis si l’ad enbracet,<br>Sur l’erbe verte puis l’at suef culchet.<br>Mult dulcement li ad Rollant preiet&#160;:<br>«&#160;E&#160;! gentilz hom, car me dunez cunget&#160;!<br>Noz cumpaignuns, que oümes tanz chers,<br>Or sunt il morz, nes i devuns laiser.<br>Joes voell aler querre e entercer,<br>Dedevant vos juster e enrenger.&#160;»<br>Dist l’arcevesque&#160;: «&#160;Alez e repairez&#160;!<br>Cist camp est vostre, mercit Deu, e mien.&#160;»</p>" },
    { n: 162, html: "<p><span class=\"bk-n\">162</span> Rollant s’en turnet, par le camp vait tut suls,<br>Cercet les vals e si cercet les munz…<br>Iloec truvat Gerin e Gerer sun cumpaignun,<br>E si truvat Berenger e Attun&#160;;<br>Iloec truvat Anseïs e Sansun,<br>Truvat Gerard le veill de Russillun.<br>Par uns e uns les ad pris le barun,<br>A l’arcevesque en est venuz a tut,<br>Sis mist en reng dedevant ses genuilz.<br>Li arcevesque ne poet muer n’en plurt,<br>Lievet sa main, fait sa beneïcun,<br>Après ad dit&#160;: «&#160;Mare fustes, seignurs&#160;!<br>Tutes voz anmes ait Deus li Glorius&#160;!<br>En pareïs les metet en sentes flurs&#160;!<br>La meie mort me rent si anguissus&#160;!<br>Ja ne verrai le riche empereür.&#160;»</p>" },
    { n: 163, html: "<p><span class=\"bk-n\">163</span> Rollant s’en turnet, le camp vait recercer,<br>Sun cumpaignun ad truvet Oliver&#160;:<br>Encuntre sun piz estreit l’ad enbracet,<br>Si cum il poet a l’arcevesques en vent,<br>Sur un escut l’ad as altres culchet,<br>E l’arcevesque l’ad asols e seignet.<br>Idunc agreget le doel e la pitet.<br>Ço dit Rollant&#160;: «&#160;Bels cumpainz Oliver,<br>Vos fustes filz al duc Reiner<br>Ki tint la marche del val de Runers.<br>Pur hanste freindre e pur escuz peceier,<br>Pur orgoillos veintre e esmaier<br>E pur prozdomes tenir e cunseiller<br>E pur glutun veintre e esmaier,<br>En nule tere n’ad meillor chevaler…&#160;»</p>" },
    { n: 164, html: "<p><span class=\"bk-n\">164</span> Li quens Rollant, quant il veit mort ses pers<br>E Oliver, qu’il tant poeit amer,<br>Tendrur en out, cumencet a plurer.<br>En sun visage fut mult desculurez&#160;;<br>Si grant doel out que mais ne pout ester&#160;:<br>Voeillet o nun, a tere chet pasmet.<br>Dist l’arcevesques&#160;: «&#160;Tant mare fustes, ber&#160;!&#160;»</p>" },
    { n: 165, html: "<p><span class=\"bk-n\">165</span> Li arcevesques, quant vit pasmer Rollant,<br>Dunc out tel doel unkes mais n’out si grant.<br>Tendit sa main, si ad pris l’olifan&#160;:<br>En Rencesvals ad un’ ewe curant&#160;;<br>Aler i volt, sin durrat a Rollant.<br>Sun petit pas s’en turnet cancelant.<br>Il est si fieble qu’il ne poet en avant&#160;;<br>N’en ad vertut, trop ad perdut del sanc.<br>Einz qu’om alast un sul arpent de camp,<br>Falt li le coer, si est chaeit avant.<br>La sue mort li vait mult angoissant.</p>" },
    { n: 166, html: "<p><span class=\"bk-n\">166</span> Li quens Rollant revient de pasmeisuns&#160;:<br>Sur piez se drecet, mais il ad grant dulur.<br>Guardet aval e si guardet amunt&#160;:<br>Sur l’erbe verte, ultre ses cumpaignuns,<br>La veit gesir le nobilie barun,<br>Ço est l’arcevesque, que Deus mist en sun num.<br>Cleimet sa culpe, si reguardet amunt,<br>Cuntre le ciel amsdous ses mains ad juinz,<br>Si priet Deu que pareïs li duinst.<br>Morz est Turpin, le guerreier Charlun.<br>Par granz batailles e par mult bels sermons<br>Cuntre paiens fut tuz tens campiuns.<br>Deus li otreit seinte beneïçun&#160;! AOI.</p>" },
    { n: 167, html: "<p><span class=\"bk-n\">167</span> Li quens Rollant veit l’arcevesque a tere&#160;:<br>Defors sun cors veit gesir la buele,<br>Desuz le frunt li buillit la cervele&#160;;<br>Desur sun piz, entre les dous furceles,<br>Cruisiedes ad ses blanches mains, les beles.<br>Forment le pleignet a la lei de sa tere&#160;:<br>«&#160;E&#160;! gentilz hom, chevaler de bon aire,<br>Hoi te cumant al Glorius celeste.<br>Jamais n’ert hume plus volenters le serve.<br>Dès les apostles ne fut hom tel prophete<br>Pur lei tenir e pur humes atraire.<br>Ja la vostre anme nen ait sufraite&#160;!<br>De pareïs li seit la porte uverte&#160;!&#160;»</p>" },
    { n: 168, html: "<p><span class=\"bk-n\">168</span> Ço sent Rollant que la mort li est près&#160;:<br>Par les oreilles fors se ist la cervel.<br>De ses pers priet Deu ques apelt,<br>E pois de lui a l’angle Gabriel.<br>Prist l’olifan, que reproce n’en ait,<br>E Durendal s’espee en l’altre main.<br>Plus qu’arcbaleste ne poet traire un quarrel,<br>Devers Espaigne en vait en un guaret&#160;;<br>Muntet sur un tertre&#160;; desuz un arbre bel<br>Quatre perruns i ad, de marbre faiz&#160;;<br>Sur l’erbe verte si est caeit envers&#160;:<br>La s’est pasmet, kar la mort li est près.</p>" },
    { n: 169, html: "<p><span class=\"bk-n\">169</span> Halt sunt li pui e mult halt les arbres.<br>Quatre perruns i ad luisant de marbre.<br>Sur l’erbe verte li quens Rollant se pasmet.<br>Uns Sarrazins tute veie l’esguardet,<br>Si se feinst mort, si gist entre les altres.<br>Del sanc luat sun cors e sun visage.<br>Met sei en piez e de curre s’astet.<br>Bels fut e forz e de grant vasselage&#160;;<br>Par sun orgoill cumencet mortel rage.<br>Rollant saisit e sun cors e ses armes<br>E dist un mot&#160;: «&#160;Vencut est li niés Carles&#160;!<br>Iceste espee porterai en Arabe.&#160;»<br>En cet tirer li quens s’aperçut alques.</p>" },
    { n: 170, html: "<p><span class=\"bk-n\">170</span> Ço sent Rollant que s’espee li tolt.<br>Uvrit les oilz, si li ad dit un mot&#160;:<br>«&#160;Men escientre, tu n’ies mie des noz&#160;!&#160;»<br>Tient l’olifan, qu’unkes perdre ne volt,<br>Sil fiert en l’elme, ki gemmet fut a or&#160;:<br>Fruisset l’acer e la teste e les os,<br>Amsdous les oilz del chef li ad mi fors,<br>Jus a ses piez si l’ad tresturnet mort.<br>Après li dit&#160;: «&#160;Culvert paien, cum fus unkes si os<br>Que me saisis, ne a dreit ne a tort&#160;?<br>Ne l’orrat hume ne t’en tienget por fol.<br>Fenduz en est mis olifans el gros,<br>Caiuz en est li cristals e li ors.&#160;»</p>" },
    { n: 171, html: "<p><span class=\"bk-n\">171</span> Ço sent Rollant la veüe ad perdue,<br>Met sei sur piez, quanqu’il poet s’esvertuet&#160;;<br>En sun visage sa culur ad perdue.<br>Dedevant lui ad une perre brune.<br>.X. colps i fiert par doel e par rancune.<br>Cruist li acers, ne freint ne ne s’esgruignet.<br>«&#160;E&#160;!&#160;» dist li quens, «&#160;seinte Marie, aiue&#160;!<br>E&#160;! Durendal, bone, si mare fustes&#160;!<br>Quant jo mei perd, de vos n’en ai mais cure.<br>Tantes batailles en camp en ai vencues<br>E tantes teres larges escumbatues,<br>Que Carles tient, ki la barbe ad canue&#160;!<br>Ne vos ait hume ki pur altre fuiet&#160;!<br>Mult bon vassal vos ad lung tens tenue.<br>Jamais n’ert tel en France la solue.&#160;»</p>" },
    { n: 172, html: "<p><span class=\"bk-n\">172</span> Rollant ferit el perrun de sardonie.<br>Cruist li acers, ne briset ne n’esgrunie.<br>Quant il ço vit que n’en pout mie freindre,<br>A sei meïsme la cumencet a pleindre&#160;:<br>«&#160;E&#160;! Durendal, cum es bele e clere e blanche&#160;!<br>Cuntre soleill si luises e reflambes&#160;!<br>Carles esteit es vals de Moriane,<br>Quan Deus del cel li mandat par sun angle<br>Qu’il te dunast a un cunte cataignie&#160;:<br>Dunc la me ceinst li gentilz reis, li magnes.<br>Jo l’en cunquis e Anjou e Bretaigne,<br>Si l’en cunquis e Peitou e le Maine&#160;;<br>Jo l’en cunquis Normendie la franche,<br>Si l’en cunquis Provence e Equitaigne<br>E Lumbardie e trestute Romaine&#160;;<br>Jo l’en cunquis Baiver et tute Flandres<br>E Burguigne e trestute Puillanie,<br>Costentinnoble, dunt il out la fiance,<br>E en Saisonie fait il ço qu’il demandet&#160;;<br>Jo l’en cunquis e Escoce e [Vales islonde]<br>E Engletere, que il teneit sa cambre&#160;;<br>Cunquis l’en ai païs e teres tantes,<br>Que Carles tient, ki ad la barbe blanche.<br>Pur cette espee ai dulor e pesance.<br>Mielz voeill murir qu’entre paiens remaigne.<br>Deus&#160;! perre, n’en laiser hunir France&#160;!&#160;»</p>" },
    { n: 173, html: "<p><span class=\"bk-n\">173</span> Rollant ferit en une perre bise.<br>Plus en abat que jo ne vos sai dire.<br>L’espee cruist, ne fruisset ne ne brise,<br>Cuntre ciel amunt est resortie.<br>Quant veit li quens que ne la freindrat mie,<br>Mult dulcement la pleinst a sei meïsme&#160;:<br>«&#160;E&#160;! Durendal, cum es bele e seintisme&#160;!<br>En l’oriet punt asez i ad reliques,<br>La dent seint Perre e del sanc seint Basilie<br>E des chevels mun seignor seint Denise,<br>Del vestement i ad seinte Marie&#160;:<br>Il nen est dreiz que paiens te baillisent&#160;;<br>De chrestiens devez estre servie.<br>Ne vos ait hume ki facet cuardie&#160;!<br>Mult larges teres de vus avrai conquises,<br>Que Carles tent, ki la barbe ad flurie,<br>E li empereres en est ber e riches.&#160;»</p>" },
    { n: 174, html: "<p><span class=\"bk-n\">174</span> Ço sent Rollant que la mort le tresprent,<br>Devers la teste sur le quer li descent.<br>Desuz un pin i est alet curant,<br>Sur l’erbe verte s’i est culchet adenz,<br>Desuz lui met s’espee e l’olifan,<br>Turnat sa teste vers la paiene gent&#160;:<br>Pur ço l’at fait que il voelt veirement<br>Que Carles diet e trestute sa gent,<br>Li gentilz quens, qu’il fut mort cunquerant.<br>Cleimet sa culpe e menut e suvent,<br>Pur ses pecchez Deu en puroffrid lo guant. AOI.</p>" },
    { n: 175, html: "<p><span class=\"bk-n\">175</span> Ço sent Rollant de sun tens n’i ad plus.<br>Devers Espaigne est en un pui agut,<br>A l’une main si ad sun piz batud&#160;:<br>«&#160;Deus, meie culpe vers les tues vertuz<br>De mes pecchez, des granz e des menuz,<br>Que jo ai fait dès l’ure que nez fui<br>Tresqu’a cest jur que ci sui consoüt&#160;!&#160;»<br>Sun destre guant en ad vers Deu tendut.<br>Angles del ciel i descendent a lui. AOI.</p>" },
    { n: 176, html: "<p><span class=\"bk-n\">176</span> Li quens Rollant se jut desuz un pin,<br>Envers Espaigne en ad turnet sun vis.<br>De plusurs choses a remembrer li prist,<br>De tantes teres cum li bers cunquist,<br>De dulce France, des humes de sun lign,<br>De Carlemagne, sun seignor, kil nurrit&#160;;<br>Ne poet muer n’en plurt e ne suspirt.<br>Mais lui meïsme ne volt mettre en ubli,<br>Cleimet sa culpe, si priet Deu mercit&#160;:<br>«&#160;Veire Patene, ki unkes ne mentis,<br>Seint Lazaron de mort resurrexis<br>E Daniel des leons guaresis,<br>Guaris de mei l’anme de tuz perilz<br>Pur les pecchez que en ma vie fis&#160;!&#160;»<br>Sun destre guant a Deu en puroffrit.<br>Seint Gabriel de sa main l’ad pris.<br>Desur sun braz teneit le chef enclin&#160;;<br>Juntes ses mains est alet a sa fin.<br>Deus tramist sun angle Cherubin<br>E seint Michel del Peril&#160;;<br>Ensembl’ od els sent Gabriel i vint.<br>L’anme del cunte portent en pareïs.</p>" },
    { n: 177, html: "<p><span class=\"bk-n\">177</span> Morz est Rollant, Deus en ad l’anme es cels.<br>Li emperere en Rencesval parvient.<br>Il nen i ad ne veie ne senter,<br>Ne voide tere ne alne ne plein pied<br>Que il n’i ait o Franceis o paien.<br>Carles escriet&#160;: «&#160;U estes vos, bels niés&#160;?<br>U est l’arcevesque&#160;? e li quens Oliver&#160;?<br>U est Gerins e sis cumpainz Gerers&#160;?<br>U est Otes&#160;? e li quens Berengers&#160;?<br>Ive e Ivorie, que jo aveie tant chers&#160;?<br>Qu’est devenuz li Guascuinz Engeler&#160;?<br>Sansun li dux&#160;? e Anseïs li bers&#160;?<br>U est Gerard de Russillun li veilz&#160;?<br>Li .XII. per que jo aveie laiset&#160;?&#160;»<br>De ço qui chelt, quant nul n’en respundiet&#160;?<br>«&#160;Deus&#160;!&#160;» dist li reis, «&#160;tant me pois esmaier<br>Que jo ne fui a l’estur cumencer&#160;!&#160;»<br>Tiret sa barbe cum hom ki est iret&#160;;<br>Plurent des oilz si baron chevaler&#160;;<br>Encuntre tere se pasment .XX. millers&#160;;<br>Naimes li dux en ad mult grant pitet.</p>" },
    { n: 178, html: "<p><span class=\"bk-n\">178</span> Il n’en i ad chevaler ne barun<br>Que de pitet mult durement ne plurt&#160;;<br>Plurent lur filz, lur freres, lur nevolz<br>E lur amis e lur lige seignurs&#160;;<br>Encuntre tere se pasment li plusur.<br>Naimes li dux d’iço ad fait que proz,<br>Tuz premereins l’ad dit l’empereür&#160;:<br>«&#160;Veez avant de dous liwes de nus,<br>Vedeir puez les granz chemins puldrus,<br>Qu’asez i ad de la gent paienur.<br>Car chevalchez&#160;! Vengez ceste dulor&#160;!<br>— E&#160;! Deus&#160;!&#160;» dist Carles, «&#160;ja sunt il ja si luinz&#160;!<br>Cunseillez mei e dreiture e honur&#160;;<br>De France dulce m’unt tolue la flur.&#160;»<br>Li reis cumandet Gebuin e Otun,<br>Tedbalt de Reins e le cunte Milun&#160;:<br>«&#160;Guardez le champ e les vals e les munz.<br>Lessez gesir les morz tut issi cun il sunt,<br>Que n’i adeist ne beste ne lion,<br>Ne n’i adeist esquier ne garçun&#160;;<br>Jo vus defend que n’i adeist nuls hom,<br>Josque Deus voeille qu’en cest camp revengum.&#160;»<br>E cil respundent dulcement, par amur&#160;:<br>«&#160;Dreiz emperere, cher sire, si ferum&#160;!&#160;»<br>Mil chevaler i retienent des lur. AOI.</p>" },
    { n: 179, html: "<p><span class=\"bk-n\">179</span> Li empereres fait ses graisles suner,<br>Puis si chevalchet od sa grant ost li ber.<br>De cels d’Espaigne unt lur les dos turnez,<br>Tenent l’enchalz, tuit en sunt cumunel.<br>Quant veit li reis le vespres decliner,<br>Sur l’erbe verte descent li reis en un pred,<br>Culchet sei a tere, si priet Damnedeu<br>Que li soleilz facet pur lui arester,<br>La nuit targer e le jur demurer.<br>Ais li un angle ki od lui soelt parler,<br>Isnelement si li ad comandet&#160;:<br>«&#160;Charle, chevalche, car tei ne falt clartet.<br>La flur de France as perdut, ço set Deus.<br>Venger te poez de la gent criminel.&#160;»<br>A icel mot est l’emperere muntet. AOI.</p>" },
    { n: 180, html: "<p><span class=\"bk-n\">180</span> Pur Karlemagne fist Deus vertuz mult granz,<br>Car li soleilz est remés en estant.<br>Paien s’en fuient, ben les chalcent Franc.<br>El Val Tenebrus la les vunt ateignant,<br>Vers Sarraguce les enchalcent ferant,<br>A colps pleners les en vunt ociant,<br>Tolent lur veies e les chemins plus granz.<br>L’ewe de Sebre, el lur est dedevant&#160;;<br>Mult est parfunde, merveilluse e curant&#160;;<br>Il nen i ad barge, ne drodmund ne caland.<br>Paiens recleiment un lur deu, Tervagant,<br>Puis saillent enz, mais il n’i unt guarant.<br>Li adubez en sunt li plus pesant,<br>Envers les funz s’en turnerent alquanz&#160;;<br>Li altre en vunt cuntreval flotant&#160;;<br>Li miez guariz en unt boüd itant<br>Tuz sunt neiez par merveillus ahan.<br>Franceis escrient&#160;: «&#160;Mar veïstes Rollant&#160;!&#160;» AOI.</p>" },
    { n: 181, html: "<p><span class=\"bk-n\">181</span> Quant Carles veit que tuit sunt mort paiens,<br>Alquanz ocis e li plusur neiet,<br>Mult grant eschec en unt si chevaler,<br>Li gentilz reis descendut est a piet,<br>Culchet sei a tere, sin ad Deu graciet.<br>Quant il se drecet, li soleilz est culchet.<br>Dist l’emperere&#160;: «&#160;Tens est del herberger&#160;;<br>En Rencesvals est tart del repairer.<br>Noz chevals sunt e las e ennuiez.<br>Tolez lur les seles, lé freins qu’il unt es chefs,<br>E par cez prez les laisez refreider.&#160;»<br>Respundent Franc&#160;: «&#160;Sire, vos dites bien.&#160;»</p>" },
    { n: 182, html: "<p><span class=\"bk-n\">182</span> Li emperere ad prise sa herberge.<br>Franceis descendent en la tere deserte,<br>A lur chevals unt toleites les seles,<br>Les freins a or e metent jus des testes,<br>Livrent lur prez, asez i ad fresche herbe&#160;:<br>D’altre cunreid ne lur poeent plus faire.<br>Ki mult est las, il se dort cuntre tere.<br>Icele noit n’unt unkes escalguaite.</p>" },
    { n: 183, html: "<p><span class=\"bk-n\">183</span> Li emperere s’est culcet en un pret.<br>Sun grant espiet met a sun chef li ber.<br>Icele noit ne se volt il desarmer,<br>Si ad vestut sun blanc osberc sasfret,<br>Laciet sun elme, ki est a or gemmet,<br>Ceinte Joiuse, unches ne fut sa per,<br>Ki cascun jur muet .XXX. clartez.<br>Asez savum de la lance parler,<br>Dunt Nostre Sire fut en la cruiz nasfret&#160;:<br>Carles en ad la mure, mercit Deu&#160;;<br>En l’oret punt l’ad faite manuvrer.<br>Pur ceste honur e pur ceste bontet,<br>Li nums Joiuse l’espee fut dunet.<br>Baruns franceis nel deivent ublier&#160;:<br>Enseigne en unt de Munjoie crier&#160;;<br>Pur ço nes poet nule gent cuntrester.</p>" },
    { n: 184, html: "<p><span class=\"bk-n\">184</span> Clere est la noit e la lune luisant.<br>Carles se gist, mais doel ad de Rollant<br>E d’Oliver li peiset mult forment,<br>Des .XII. pers e de la franceise gent<br>Qu’en Rencesvals ad laiset morz sanglenz.<br>Ne poet muer n’en plurt e nes dement<br>E priet Deu qu’as anmes seit guarent.<br>Las est li reis, kar la peine est mult grant&#160;;<br>Endormiz est, ne pout mais en avant.<br>Par tuz les prez or se dorment li Franc.<br>N’i ad cheval ki puisset ester en estant&#160;:<br>Ki herbe voelt, il la prent en gisant.<br>Mult ad apris ki bien conuist ahan.</p>" },
    { n: 185, html: "<p><span class=\"bk-n\">185</span> Carles se dort cum hume traveillet.<br>Seint Gabriel li ad Deus enveiet&#160;:<br>L’empereür li cumandet a guarder.<br>Li angles est tute noit a sun chef.<br>Par avisiun li ad anunciet<br>D’une bataille ki encuntre lui ert&#160;:<br>Senefiance l’en demustrat mult gref.<br>Carles guardat amunt envers le ciel,<br>Veit les tuneires e les venz e les giels<br>E les orez, les merveillus tempez,<br>E fous e flambes i est apareillez&#160;:<br>Isnelement sur tute sa gent chet.<br>Ardent cez hanstes de fraisne e de pumer<br>E cez escuz jesqu’as bucles d’or mier,<br>Fruissent cez hanstes de cez trenchanz espiez,<br>Cruissent osbercs e cez helmes d’acer.<br>En grant dulor i veit ses chevalers.<br>Urs e leuparz les voelent puis manger,<br>Serpenz e guivres, dragun e averser.<br>Grifuns i ad, plus de trente millers,<br>N’en i ad cel a Franceis ne sagiet.<br>E Franceis crient&#160;: «&#160;Carlemagne, aidez&#160;!&#160;»<br>Li reis en ad e dulur e pitet&#160;;<br>Aler i volt, mais il ad desturber&#160;:<br>Devers un gualt uns granz leons li vient,<br>Mult par ert pesmes e orguillus e fiers,<br>Sun cors meïsmes i asalt e requert<br>E prenent sei a braz ambesdous por loiter&#160;;<br>Mais ço ne set liquels abat ne quels chiet.<br>Li emperere n’est mie esveillet.</p>" },
    { n: 186, html: "<p><span class=\"bk-n\">186</span> Après icel li vien un’altre avisiun,<br>Qu’il ert en France, ad Ais, a un perrun,<br>En dous chaeines si teneit un brohun.<br>Devers Ardene veeit venir .XXX. urs,<br>Cascun parolet altresi cume hum,<br>Diseient li&#160;: «&#160;Sire, rendez le nus&#160;!<br>Il nen est dreiz que il seit mais od vos&#160;;<br>Nostre parent devum estre a sucurs.&#160;»<br>De sun paleis uns veltres i acurt&#160;:<br>Entre les altres asaillit le greignur<br>Sur l’erbe verte, ultre ses cumpaignuns.<br>La vit li reis si merveillus estur&#160;;<br>Mais ço ne set liquels veint ne quels nun.<br>Li angles Deu ço ad mustret al barun.<br>Carles se dort tresqu’al demain, al cler jur.</p>" },
    { n: 187, html: "<p><span class=\"bk-n\">187</span> Li reis Marsilie s’en fuit en Sarraguce.<br>Suz un’ olive est descendut en l’umbre.<br>S’espee rent e sun elme e sa bronie&#160;;<br>Sur la verte herbe mult laidement se culcet&#160;;<br>La destre main ad perdue trestute&#160;;<br>Del sanc qu’en ist se pasmet e angoiset.<br>Dedevant lui sa muiller Bramimunde<br>Pluret e criet, mult forment se doluset,<br>Ensembl’ od li plus de .XX. mil humes,<br>Si maldient Carlun e France dulce.<br>Ad Apolin en curent en une crute,<br>Tencent a lui, laidement le despersunent&#160;:<br>«&#160;E&#160;! malvais deus, por quei nus fais tel hunte&#160;?<br>C’est nostre rei por quei lessas cunfundre&#160;?<br>Ki mult te sert, malvais luer l’en dunes&#160;!&#160;»<br>Puis si li tolent sun sceptre e sa curune,<br>Par les mains le pendent sur une culumbe,<br>Entre lur piez a tere le tresturnent,<br>A granz bastuns le batent e defruisent&#160;;<br>E Tervagan tolent sun escarbuncle<br>E Mahumet enz en un fosset butent<br>E porc e chen le mordent e defulent.</p>" },
    { n: 188, html: "<p><span class=\"bk-n\">188</span> CLXXXVIII<br>De pasmeisuns en est venuz Marsilies,<br>Fait sei porter en sa cambre voltice&#160;;<br>Plusurs culurs i ad peinz e escrites&#160;;<br>E Bramimunde le pluret, la reïne,<br>Trait ses chevels, si se cleimet caitive,<br>A l’altre mot mult haltement s’escriet&#160;:<br>«&#160;E&#160;! Sarraguce, cum ies oi desguarnie<br>Del gentil rei ki t’aveit en baillie&#160;!<br>Li nostre deu i unt fait felonie,<br>Ki en bataille oi matin le faillirent.<br>Li amiralz i ferat cuardie,<br>S’il ne cumbat a cele gent hardie<br>Ki si sunt fiers n’unt cure de lur vies.<br>Li emperere od la barbe flurie<br>Vasselage ad e mult grant estultie&#160;;<br>S’il ad bataille, il ne s’en fuirat mie.<br>Mult est grant doel que nen est ki l’ociet.&#160;»</p>" },
    { n: 189, html: "<p><span class=\"bk-n\">189</span> Li emperere par sa grant poestet<br>.VII. anz tuz plens ad en Espaigne estet&#160;;<br>Prent i chastels e alquantes citez.<br>Li reis Marsilie s’en purcacet asez&#160;:<br>Al premer an fist ses brefs seieler,<br>En Babilonie Baligant ad mandet,<br>Ço est l’amiraill, le viel d’antiquitet,<br>Tut survesquiet e Virgilie e Omer&#160;;<br>En Sarraguce alt sucurre li ber<br>E, s’il nel fait, il guerpirat ses deus<br>E tuz ses ydeles que il soelt adorer,<br>Si recevrat seinte chrestientet,<br>A Charlemagne se vuldrat acorder.<br>E cil est loinz, si ad mult demuret&#160;;<br>Mandet sa gent de .XL. regnez,<br>Ses granz drodmunz en ad fait aprester,<br>Eschiez e barges e galies e nefs&#160;;<br>Suz Alixandre, ad un port juste mer,<br>Tut sun navilie i ad fait aprester.<br>Ço est en mai, al premer jur d’ested&#160;:<br>Tutes ses oz ad empeintes en mer.</p>" },
    { n: 190, html: "<p><span class=\"bk-n\">190</span> Granz sunt les oz de cele gent averse&#160;;<br>Siglent a fort e nagent e guvernent.<br>En sum cez maz e en cez haltes vernes<br>Asez i ad carbuncles e lanternes&#160;;<br>La sus amunt pargetent tel luiserne<br>Par la noit la mer en est plus bele,<br>E cum il vienent en Espaigne la tere,<br>Tut li païs en reluist e esclairet.<br>Jesqu’a Marsilie en parvunt les noveles. AOI.</p>" },
    { n: 191, html: "<p><span class=\"bk-n\">191</span> Gent paienor ne voelent cesser unkes,<br>Issent de mer, venent as ewes dulces,<br>Laisent Marbrise e si laisent Marbrose,<br>Par Sebre amunt tut lur naviries turnent.<br>Asez i ad lanternes e carbuncles&#160;:<br>Tute la noit mult grant clartet lur dunent.<br>A icel jur venent a Sarraguce. AOI.</p>" },
    { n: 192, html: "<p><span class=\"bk-n\">192</span> Clers est li jurz e li soleilz luisant.<br>Li amiralz est issut del calan.<br>Espaneliz fors le vait adestrant,<br>.XVII. reis après le vunt siwant&#160;;<br>Cuntes e dux i ad ben ne sai quanz.<br>Suz un lorer, ki est en mi un camp,<br>Sur l’erbe verte getent un palie blanc&#160;;<br>Un faldestoed i unt mis d’olifan&#160;;<br>Desur s’asiet li paien Baligant.<br>Tuit li altre sunt remés en estant.<br>Li sire d’els premer parlat avant&#160;:<br>«&#160;Oiez ore, franc chevaler vaillant&#160;!<br>Carles li reis, l’emperere des Francs,<br>Ne deit manger, se jo ne li cumant.<br>Par tute Espaigne m’at fait guere mult grant.<br>En France dulce le voeil aler querant.<br>Ne finerai en trestut mun vivant<br>Josqu’il seit mort u tut vif recreant.&#160;»<br>Sur sun genoill en fiert sun destre guant.</p>" },
    { n: 193, html: "<p><span class=\"bk-n\">193</span> Puis qu’il l’ad dit, mult s’en est afichet<br>Que ne lairat pur tut l’or desuz ciel<br>Qu’il n’alt ad Ais, o Carles soelt plaider.<br>Si hume li lodent, si li unt cunseillet.<br>Puis apelat dous de ses chevalers,<br>L’un Clarifan e l’altre Clarïen&#160;:<br>«&#160;Vos estes filz al rei Maltraïen,<br>Ki messages soleit faire volenters.<br>Jo vos cumant qu’en Sarraguce algez.<br>Marsiliun de meie part li nunciez<br>Cuntre Franceis li sui venut aider&#160;:<br>Se jo truis o, mult grant bataille i ert&#160;;<br>Si l’en dunez cest guant ad or pleiet,<br>El destre poign si li faites chalcer&#160;;<br>Si li portez cest bastuncel d’or mer,<br>E a mei venget pur reconoistre sun feu.<br>En France irai pur Carle guerreier.<br>S’en ma mercit ne se culzt a mes piez<br>E ne guerpisset la lei de chrestiens,<br>Jo li toldrai la corune del chef.&#160;»<br>Paien respundent&#160;: «&#160;Sire, mult dites bien.&#160;»</p>" },
    { n: 194, html: "<p><span class=\"bk-n\">194</span> Dist Baligant&#160;: «&#160;Car chevalchez, barun&#160;!<br>L’un port le guant, li alte le bastun&#160;!&#160;»<br>E cil respundent&#160;: «&#160;Cher sire, si ferum.&#160;»<br>Tant chevalcherent qu’en Sarraguce sunt.<br>Passent .X. portes, traversent .IIII. punz,<br>Tutes les rues u li burgeis estunt.<br>Cum il aproisment en la citet amunt,<br>Vers le paleis oïrent grant fremur&#160;:<br>Asez i ad de cele gent paienur,<br>Plurent e crient, demeinent grant dolor,<br>Pleignent lur deus, Tervagan e Mahum<br>E Apollin, dunt il mie n’en unt,<br>Dist cascun a l’altre&#160;: «&#160;Caitifs, que devendrum&#160;?<br>Sur nus est venue male confusiun&#160;;<br>Perdut avum le rei Marsiliun&#160;;<br>Li quens Rollant li trenchat ier le destre poign&#160;;<br>Nus n’avum mie de Jurfaleu le blunt&#160;;<br>Trestute Espaigne iert hoi en lur bandun.&#160;»<br>Li dui message descendent al perrun.</p>" },
    { n: 195, html: "<p><span class=\"bk-n\">195</span> Lur chevals laisent dedesuz un’ olive.<br>Dui Sarrazin par les resnes les pristrent,<br>E li message par les mantels se tindrent,<br>Puis sunt muntez sus el paleis altisme.<br>Cum il entrerent en la cambre voltice,<br>Par bel’ amur malvais saluz li firent&#160;:<br>«&#160;Cil Mahumet ki nus ad en baillie<br>E Tervagan e Apollin, nostre sire,<br>Salvent le rei e guardent la reïne&#160;!&#160;»<br>Dist Bramimunde&#160;: «&#160;Or oi mult grant folie&#160;!<br>Cist nostre deu sunt en recreantise.<br>En Rencesval malvaises vertuz firent&#160;:<br>Noz chevalers i unt lesset ocire&#160;;<br>Cest mien seignur en bataille faillirent&#160;;<br>Le destre poign ad perdut, n’en ad mie,<br>Si li trenchat li quens Rollant, li riches.<br>Trestute Espaigne avrat Carles en baillie.<br>Que devendrai, duluruse, caitive&#160;?<br>E&#160;! lasse, que nen ai un hume ki m’ociet&#160;!&#160;» AOI.</p>" },
    { n: 196, html: "<p><span class=\"bk-n\">196</span> Dist Clarïen&#160;: «&#160;Dame, ne parlez mie itant&#160;!<br>Messages sumes al paien Baligant.<br>Marsiliun, ço dit, serat guarant,<br>Si l’en enveiet sun bastun e sun guant.<br>En Sebre avum .IIII. milie calant,<br>Eschiez e barges e galees curant&#160;;<br>Drodmunz i ad ne vos sai dire quanz.<br>Li amiralz est riches e puisant&#160;:<br>En France irat Carlemagne querant&#160;;<br>Rendre le quidet u mort o recreant.&#160;»<br>Dist Bramimunde&#160;: «&#160;Mar en irat itant&#160;!<br>Plus près d’ici purrez truver les Francs&#160;:<br>En ceste tere ad estet ja .VII. anz.<br>Li emperere est ber e cumbatant&#160;:<br>Meilz voel murir que ja fuiet de camp&#160;;<br>Suz ciel n’ad rei qu’il prist a un enfant.<br>Carles ne creint nuls hom ki seit vivant.&#160;»</p>" },
    { n: 197, html: "<p><span class=\"bk-n\">197</span> «&#160;Laissez ço ester&#160;!&#160;» dist Marsilies li reis.<br>Dist as messages&#160;: «&#160;Seignurs, parlez a mei&#160;!<br>Ja veez vos que a mort sui destreit,<br>Jo si nen ai filz ne fille ne heir&#160;:<br>Un en aveie, cil fut ocis her seir.<br>Mun seignur dites qu’il me vienge veeir.<br>Li amiraill ad en Espaigne dreit&#160;:<br>Quite li cleim, se il la voelt aveir,<br>Puis la defendet encuntre li Franceis&#160;!<br>Vers Carlemagne li durrai bon conseill&#160;:<br>Cunquis l’avrat d’oi cest jur en un meis.<br>De Sarraguce les clefs li portereiz,<br>Pui li dites il n’en irat, s’il me creit.&#160;»<br>Cil respundent&#160;: «&#160;Sire, vus dites veir.&#160;» AOI.</p>" },
    { n: 198, html: "<p><span class=\"bk-n\">198</span> Ço dist Marsilie&#160;: «&#160;Carles l’emperere<br>Mort m’ad mes homes, ma tere deguastee<br>E mes citez fraites e violees.<br>Il jut anuit sur cel’ ewe de Sebre&#160;:<br>Jo ai cunté n’i ad mais que .VII. liwes.<br>L’amirail dites que sun host i amein.<br>Par vos li mand bataille i seit justee.&#160;»<br>De Sarraguce les clefs li ad livrees.<br>Li messager ambedui l’enclinerent,<br>Prenent cunget, a cel mot s’en turnerent.</p>" },
    { n: 199, html: "<p><span class=\"bk-n\">199</span> Li dui message es chevals sunt muntet.<br>Isnelement issent de la citet,<br>A l’amiraill en vunt esfreedement,<br>De Sarraguce li presentent les clés.<br>Dist Baligant&#160;: «&#160;Que avez vos truvet&#160;?<br>U est Marsilie, que jo aveie mandet&#160;?&#160;»<br>Dist Clarïen&#160;: «&#160;Il est a mort naffret.<br>Li emperere fut ier as porz passer,<br>Si s’en vuleit en dulce France aler.<br>Par grant honur se fist rereguarder&#160;:<br>Li quens Rollant i fut remés, sis niés,<br>E Oliver e tuit li .XII. per,<br>De cels de France .XX. milie adubez.<br>Li reis Marsilie s’i cumbatit, li bers.<br>Il e Rollant el camp furent remés&#160;:<br>De Durendal li dunat un colp tel<br>Le destre poign li ad del cors sevret.<br>Sun filz ad mort, qu’il tant suleit amer,<br>E li baron qu’il i out amenet.<br>Fuiant s’en vint, qu’il n’i pout mès ester.<br>Li emperere l’ad enchacet asez.<br>Li reis vos mandet que vos le sucurez.<br>Quite vus cleimet d’Espaigne le regnet.&#160;»<br>E Baligant cumencet a penser&#160;;<br>Si grant doel ad por poi qu’il n’est desvet. AOI.</p>" },
    { n: 200, html: "<p><span class=\"bk-n\">200</span> «&#160;Sire amiralz,&#160;» dist Clarïens,<br>«&#160;En Rencesvals une bataille out ier.<br>Morz est Rollant e li quens Oliver,<br>Li .XII. per, que Carles aveit tant cher&#160;;<br>De lur Franceis i ad mort .XX. millers.<br>Li reis Marsilie le destre poign i perdiet<br>E l’emperere asez l’ad enchalcet.<br>En ceste tere n’est remés chevaler<br>Ne seit ocis o en Sebre neiet.<br>Desur la rive sunt Francès herbergiez&#160;:<br>En cest païs nus sunt tant aproeciez,<br>Se vos volez, li repaires ert grefs.&#160;»<br>E Baligant le reguart en ad fiers,<br>En sun curage en est joüs e liet.<br>Del faldestod se redrecet en piez,<br>Puis escriet&#160;: «&#160;Baruns, ne vos targez&#160;!<br>Eissez des nefs, muntez, si chevalciez&#160;!<br>S’or ne s’en fuit Karlemagne li veilz,<br>Li reis Marsilie enqui serat venget&#160;:<br>Pur sun poign destre l’en livrerai le chef.&#160;»</p>" },
    { n: 201, html: "<p><span class=\"bk-n\">201</span> Paien d’Arabe des nefs se sunt eissut,<br>Puis sunt muntez es chevals e es muls,<br>Si chevalcherent, que fereient il plus&#160;?<br>Li amiralz, ki trestuz les esmut,<br>Sin apelet Gemalfin, un sun drut&#160;:<br>«&#160;Jo te cumant de tutes mes oz…&#160;»<br>Puis est munté en un sun destrer brun&#160;;<br>Ensembl’ od lui em meinet .IIII. dux.<br>Tant chevalchat qu’en Saraguce fut.<br>A un perron de marbre est descenduz<br>E quatre cuntes l’estreu li unt tenut.<br>Par les degrez el paleis muntet sus,<br>E Bramidonie vient curant cuntre lui,<br>Si li ad dit&#160;: «&#160;Dolente, si mare fui&#160;!<br>A itel hunte, sire, mon seignor ai perdut&#160;!&#160;»<br>Chet li as piez, li amiralz la reçut&#160;;<br>Sus en la chambre ad doel en sunt venut. AOI.</p>" },
    { n: 202, html: "<p><span class=\"bk-n\">202</span> Li reis Marsilie, cum il veit Baligant,<br>Dunc apelat dui Sarrazin espans&#160;:<br>«&#160;Pernez m’as braz, sim drecez en seant.&#160;»<br>Al puign senestre ad pris un de ses guanz.<br>Ço dist Marsilie&#160;: «&#160;Sire reis, amiralz,<br>Teres tutes ici . . . . . . . . . . . . .<br>E Sarraguce e l’onur qu’i apent.<br>Mei ai perdut e tute ma gent.&#160;»<br>E cil respunt&#160;: «&#160;Tant sui jo plus dolent.<br>Ne pois a vos tenir lung parlement&#160;:<br>Jo sai asez que Carles ne m’atent,<br>E nepurquant de vos receif le guant.&#160;»<br>Al doel qu’il ad s’en est turnet plurant. AOI.<br>Par les degrez jus del paleis descent,<br>Muntet el ceval, vient a sa gent puignant.<br>Tant chevalchat qu’il est premers devant,<br>D’ures ad altres si se vait escriant&#160;:<br>«&#160;Venez, paien, car ja s’en fuient ferant&#160;!&#160;» AOI.</p>" },
    { n: 203, html: "<p><span class=\"bk-n\">203</span> Al matin, quant primes pert li albe,<br>Esveillez est li emperere Carles.<br>Sein Gabriel, ki de part Deu le guarde,<br>Levet sa main, sur lui fait sun signacle.<br>Li reis descent, si ad rendut ses armes.<br>Si se desarment par tute l’ost li altre.<br>Puis sunt muntet, par grant vertut chevalchent<br>Cez veiez lunges e cez chemins mult larges,<br>Si vunt vedeir le merveillus damage<br>En Rencesvals, la o fut la bataille. AOI.</p>" },
    { n: 204, html: "<p><span class=\"bk-n\">204</span> En Rencesvals en est Carles venuz.<br>Des morz qu’il troevet cumencet a plurer.<br>Dist a Franceis&#160;: «&#160;Segnus, le pas tenez,<br>Kar mei meïsme estoet avant aler<br>Pur mun nevold que vuldreie truver.<br>A Eis esteie, a une feste anoel,<br>Si se vanterent mi vaillant chevaler<br>De granz batailles, de forz esturs pleners.<br>D’une raisun oï Rollant parler&#160;:<br>Ja ne murreit en estrange regnet<br>Ne trespassast ses humes e ses pers&#160;;<br>Vers lur païs avreit sun chef turnet&#160;;<br>Cunquerrantment si finereit li bers.&#160;»<br>Plus qu’en ne poet un bastuncel jeter,<br>Devant les altres est en un pui muntet.</p>" },
    { n: 205, html: "<p><span class=\"bk-n\">205</span> Quant l’empereres vait querre sun nevold,<br>De tantes herbes el pré truvat les flors<br>Ki sunt vermeilles del sanc de noz barons&#160;!<br>Pitet en ad, ne poet muer n’en plurt.<br>Desuz dous arbres parvenuz est…<br>Les colps Rollant conut en treis perruns&#160;;<br>Sur l’erbe verte veit gesir sun nevuld.<br>Nen est merveille se Karles ad irur.<br>Descent a pied, aled i est pleins curs.<br>Entre ses mains ansdous…<br>Sur lui se pasmet, tant par est anguissus.</p>" },
    { n: 206, html: "<p><span class=\"bk-n\">206</span> Li empereres de pasmeisuns revint.<br>Naimes li dux e li quens Acelin,<br>Gefrei d’Anjou e sun frere Henri<br>Prenent le rei, sil drecent suz un pin.<br>Guardet a la tere, veit sun nevold gesir.<br>Tant dulcement a regreter le prist&#160;:<br>«&#160;Amis Rollant, de tei ait Deus mercit&#160;!<br>Unques nuls hom tel chevaler ne vit<br>Por granz batailles juster e defenir.<br>La meie honor est turnet en declin.&#160;»<br>Carles se pasmet, ne s’en pout astenir. AO.</p>" },
    { n: 207, html: "<p><span class=\"bk-n\">207</span> Carles li reis se vint de pasmeisuns&#160;;<br>Par les mains le tienent .IIII. de ses barons.<br>Guardet a tere, vei gesir sun nevuld.<br>Cors ad gaillard, perdue ad sa culur,<br>Turnez ses oilz, mult li sunt tenebros.<br>Carles le pleint par feid e par amur&#160;:<br>«&#160;Ami Rollant, Deus metet t’anme en flors,<br>En pareïs, entre les glorius&#160;!<br>Cum en Espaigne venis a mal seignur&#160;!<br>Jamais n’ert jurn de tei n’aie dulur.<br>Cum decarrat ma force e ma baldur&#160;!<br>N’en avrai ja ki sustienget m’onur.<br>Suz ciel ne quid aveir ami un sul&#160;;<br>Se jo ai parenz, n’en i ad nul si proz.&#160;»<br>Trait ses crignels pleines ses mains amsdous&#160;;<br>Cent milie Franc en unt si grant dulur<br>N’en i ad cet ki durement ne plurt. AOI.</p>" },
    { n: 208, html: "<p><span class=\"bk-n\">208</span> «&#160;Ami Rollant, jo m’en irai en France.<br>Cum jo serai a Loün, en ma chambre,<br>De plusurs regnes vendrunt li hume estrange,<br>Demanderunt&#160;: «&#160;U est li quens cataignes&#160;?&#160;»<br>Jo lur dirrai qu’il est morz en Espaigne.<br>A grant dulur tendrai puis mun reialme&#160;;<br>Jamais n’ert jur que ne plur ne n’en pleigne.</p>" },
    { n: 209, html: "<p><span class=\"bk-n\">209</span> «&#160;Ami Rollant, prozdoem, juvente bele,<br>Cum jo serai a Eis, em ma chapele,<br>Vendrunt li hume, demanderunt noveles.<br>Jes lur dirrai, merveilluses e pesmes&#160;:<br>«&#160;Morz est mis niés, ki tant me fist cunquere.&#160;»<br>Encuntre mei revelerunt li Seisne<br>E Hungre e Bugre e tante gent averse,<br>Romain, Puillain e tuit icil de Palerne<br>E cil d’Affrike e cil de Califerne.<br>Puis en trerunt mes peines e mes suffraites.<br>Ki guierat mes oz a tel poeste,<br>Quant cil est morz ki tuz jurz nos cadelet&#160;?<br>E&#160;! France, cum remeines deserte&#160;!<br>Si grant doel ai que jo ne vuldreie estre&#160;!&#160;»<br>Sa barbe blanche cumencet a detraire,<br>Ad ambes mains les chevels de sa teste.<br>Cent milie Francs s’en pasment cuntre tere.</p>" },
    { n: 210, html: "<p><span class=\"bk-n\">210</span> «&#160;Ami Rollant, de tei ait Deus mercit&#160;!<br>L’anme de tei seit mise en pareïs&#160;!<br>Ki tei ad mort France ad mis en exill.<br>Si grant dol ai que ne voldreie vivre<br>De ma maisnee, ki pur mei est ocise&#160;!<br>Ço duinset Deus, le filz seinte Marie,<br>Einz que jo vienge as maistres porz de Sirie,<br>L’anme del cors me seit oi departie,<br>Entre les lur aluee e mise<br>E ma car fust delez els enfuïe&#160;!&#160;»<br>Ploret des oilz, sa blanche barbe tiret,<br>E dist dux Naimes&#160;: «&#160;Or ad Carles grant ire.&#160;» AOI.</p>" },
    { n: 211, html: "<p><span class=\"bk-n\">211</span> «&#160;Sire emperere,&#160;» ço dist Gefrei d’Anjou,<br>«&#160;Ceste dolor ne demenez tant fort&#160;!<br>Par fut le camp faites querre les noz,<br>Que cil d’Espaigne en la bataille unt mort.<br>En un carner cumandez qu’hom les port.&#160;»<br>Co dist li reis&#160;: «&#160;Sunez en vostre corn&#160;!&#160;» AOI.</p>" },
    { n: 212, html: "<p><span class=\"bk-n\">212</span> Gefreid d’Anjou ad sun greisle sunet.<br>Franceis descendent, Carles l’ad comandet.<br>Tuz lur amis qu’il i unt morz truvet,<br>Ad un carner sempres les unt portet.<br>Asez i ad evesques e abez,<br>Munies, canonies, proveires coronez,<br>Sis unt asols e seignez de part Deu.<br>Mirre e timonie i firent alumer,<br>Gaillardement tuz les unt encensez&#160;:<br>A grant honor pois les unt enterrez,<br>Sis unt laisez, qu’en fereient il el&#160;? AOI.</p>" },
    { n: 213, html: "<p><span class=\"bk-n\">213</span> Li emperere fait Rollant costeïr<br>E Oliver e l’arcevesque Turpin.<br>Devant sei les ad fait tuz uvrir<br>E tuz les quers e paile recuillir&#160;:<br>Un blanc sarcou de marbre sunt enz mis,<br>E puis les cors des barons si unt pris,<br>En quirs de cerf les seignurs unt mis&#160;;<br>Ben sunt lavez de piment e de vin.<br>Li reis cumandet Tedbalt e Gebuin,<br>Milun le cunte e Otes le marchis&#160;:<br>«&#160;En .III. carettes les guiez.…&#160;»<br>Bien sunt cuverz d’un palie galazin. AOI.</p>" },
    { n: 214, html: "<p><span class=\"bk-n\">214</span> Venir s’en volt li emperere Carles,<br>Quant de paiens li surdent les enguardes.<br>De cels devant i vindrent dui messages,<br>De l’amirail li nuncent la bataille&#160;:<br>«&#160;Reis orguillos, nen est fins que t’en alges&#160;!<br>Veiz Baligant, ki après tei chevalchet.<br>Granz sunt les oz qu’il ameinet d’Arabe.<br>Encoi verrum se tu as vasselage.&#160;» AOI.<br>Carles li reis en ad prise sa barbe,<br>Si li remembret del doel e del damage,<br>Mult fierement tute sa gent reguardet,<br>Puis si s’escriet a sa voiz grand e halte&#160;:<br>«&#160;Barons franceis, as chevals e as armes&#160;!&#160;» AOI.</p>" },
    { n: 215, html: "<p><span class=\"bk-n\">215</span> Li empereres tuz premereins s’adubet.<br>Isnelement ad vestue sa brunie,<br>Lacet sun helme, si ad ceinte Joiuse,<br>Ki pur soleill sa clartet n’en muet,<br>Pent a sun col un escut de Biterne,<br>Tient sun espiet, sin fait brandir la hanste,<br>En Tencendur, sun bon cheval, puis muntet<br>— Il le cunquist es guez desuz Marsune,<br>Sin getat mort Malpalin de Nerbone, —<br>Laschet la resne, mult suvent l’esperonet,<br>Fait sun eslais, veant cent mil humes, AOI.<br>Recleimet Deu e l’apostle de Rome.</p>" },
    { n: 216, html: "<p><span class=\"bk-n\">216</span> Par fut le champ cil de France descendent.<br>Plus de cent milie s’en adubent ensemble.<br>Guarnemenz unt ki ben lor atalentent,<br>Cevals curanz e lur armes mult gentes,<br>Puis sunt muntez e unt grant science.<br>S’il troevent oi, bataille quident rendre.<br>Cil gunfanun sur les helmes lur pendent.<br>Quant Carles veit si beles cuntenances,<br>Sin apelat Jozeran de Provence,<br>Naimon li duc, Antelme de Maience&#160;:<br>«&#160;En tels vassals deit hom aveir fiance&#160;!<br>Asez est fols ki entr’els se demente.<br>Si Arrabiz de venir ne se repentent,<br>La mort Rollant lur quid cherement rendre.&#160;»<br>Respunt dux Neimes&#160;: «&#160;E Deus le nos cunsente&#160;!&#160;» AOI</p>" },
    { n: 217, html: "<p><span class=\"bk-n\">217</span> Carles apelet Rabel e Guineman.<br>Ço dist li reis&#160;: «&#160;Seignurs, jo vos cumant,<br>Seiez es lius Oliver e Rollant&#160;:<br>L’un port l’espee e l’altre l’olifant,<br>Si chevalez el premer chef devant,<br>Ensembl’od vos. XV. milie de Francs,<br>De bachelers, de noz meillors vaillanz.<br>Après icels en avrat altretant,<br>Sis guierat Gibuins e Guinemans.&#160;»<br>Naimes li dux e li quens Jozerans<br>Icez eschieles ben les vunt ajustant.<br>S’il troevent oi, bataille i ert mult grant. AOI.</p>" },
    { n: 218, html: "<p><span class=\"bk-n\">218</span> Le Franceis sunt les premeres escheles.<br>Après les dous establisent la terce.<br>En cele sunt li vassal de Baivere&#160;:<br>A .XX. milie chevalers la preiserent&#160;;<br>Ja devers els bataille n’ert lessee.<br>Suz cet n’ad gent que Carles ait plus chere,<br>Fors cels de France, ki les regnes cunquerent.<br>Li quens Oger li Daneis, li puinneres,<br>Les guierat, kar la cumpaigne est fiere. AOI.</p>" },
    { n: 219, html: "<p><span class=\"bk-n\">219</span> Treis escheles ad l’emperere Carles.<br>Naimes li dux puis establist la quarte<br>De tels barons qu’asez unt vasselage&#160;:<br>Alemans sunt e si sunt d’Alemaigne&#160;;<br>Vint milie sunt, ço dient tuit li altre.<br>Ben sunt guarniz e de chevals e d’armes&#160;;<br>Ja por murir ne guerpirunt bataille,<br>Sis guierat Hermans, li dux de Trace&#160;:<br>Einz i murat que cuardise i facet. AOI.</p>" },
    { n: 220, html: "<p><span class=\"bk-n\">220</span> Naimes li dux e li quens Jozerans<br>La quinte eschele unt faite de Normans&#160;:<br>.XX. milie sunt, ço dient tuit li Franc.<br>Armes unt beles e bons cevals curanz&#160;;<br>Ja pur murir cil n’erent recreanz.<br>Suz ciel n’ad gent ki plus poissent en camp.<br>Richard li velz les guierat el camp&#160;;<br>Cil i ferrat de sun espiet trenchant. AOI.</p>" },
    { n: 221, html: "<p><span class=\"bk-n\">221</span> La siste eschele unt faite de Bretuns&#160;:<br>.XXX. milie chevalers od els unt.<br>Icil chevalchent en guise de baron,<br>Peintes lur hanstes, fermez lur gunfanun.<br>Le seignur d’els est apelet Oedun&#160;:<br>Icil cumandet le cunte Nevelun,<br>Tedbald de Reins e le marchis Otun&#160;:<br>«&#160;Guiez ma gent, jo vos en faz le dun&#160;!&#160;» AOI.</p>" },
    { n: 222, html: "<p><span class=\"bk-n\">222</span> Li emperere ad .VI. escheles faites.<br>Naimes li dux puis establist la sedme.<br>De Peitevins e des barons d’Alverne&#160;:<br>.XL. milie chevalers poeent estre.<br>Chevals unt bons e les armes mult beles.<br>Cil sunt par els en un val suz un tertre,<br>Sis beneïst Carles de sa main destre.<br>Els guierat Jozerans e Godselmes. AOI.</p>" },
    { n: 223, html: "<p><span class=\"bk-n\">223</span> E l’oidme eschele ad Naimes establie.<br>De Flamengs est e des barons de Frise.<br>Chevalers unt plus de .XL. milie.<br>Ja devers els n’ert bataille guerpie.<br>Ço dist li reis&#160;: «&#160;Cist ferunt mun servise.&#160;»<br>Entre Rembalt e Hamon de Galice<br>Les guierunt tut par chevalerie. AOI.</p>" },
    { n: 224, html: "<p><span class=\"bk-n\">224</span> Entre Naimon et Jozeran le cunte<br>La noefme eschele unt faite de prozdomes,<br>De Loherengs e de cels de Borgoigne.<br>.L. milie chevalers unt par cunte,<br>Helmes laciez e vestues lor bronies&#160;;<br>Espiez unt forz e les hanstes sunt curtes.<br>Si Arrabiz de venir ne demurent,<br>Cil les ferrunt, s’il a els s’abandunent&#160;;<br>Sis guierat Tierris, li dux d’Argone. AOI.</p>" },
    { n: 225, html: "<p><span class=\"bk-n\">225</span> La disme eschele est des baruns de France.<br>Cent milie sunt de noz meillors cataignes&#160;;<br>Cors unt gaillarz e fieres cuntenances&#160;;<br>Les chefs fluriz e les barbes unt blanches,<br>Osbercs vestuz e lur brunies dubleines,<br>Ceintes espees franceises e d’Espaigne&#160;;<br>Escuz unt genz, de multes cunoisances.<br>Puis sunt muntez, la bataille demandent&#160;;<br>Munjoie escrient&#160;; od els est Carlemagne.<br>Gefreid d’Anjou portet l’orie flambe&#160;:<br>Seint Piere fut, si aveit num Romaine&#160;;<br>Mais de Munjoie iloec out pris eschange. AOI.</p>" },
    { n: 226, html: "<p><span class=\"bk-n\">226</span> Li emperere de sun cheval descent,<br>Sur l’erbe verte se est culchet adenz,<br>Turnet sun vis vers le soleill levant,<br>Recleimet Deu mult escordusement&#160;:<br>«&#160;Veire Paterne, hoi cest jor me defend,<br>Ki guaresis Jonas fut veirement<br>De la baleine ki en sun cors l’aveit,<br>E esparignas le rei de Niniven<br>E Danïel del merveilles turment<br>Enz en la fosse des leons o fut enz,<br>Les .III. enfanz fut en un fou ardant&#160;!<br>La tue amurs me sei hoi en present&#160;!<br>Par ta mercit, se tei plaist, me cunsent<br>Que mun nevold poisse venger Rollant&#160;!&#160;»<br>Cum ad oret, si se drecet en estant,<br>Seignat sun chef de la vertut poisant.<br>Muntet li reis en sun cheval curant&#160;;<br>L’estreu li tindrent Neimes e Jocerans&#160;;<br>Prent sun escut e sun espiet trenchant.<br>Gent ad le cors, gaillart e ben seant,<br>Cler le visage e de bon cuntenant.<br>Puis si chevalchet mult aficheement.<br>Sunent cil greisle e derere e devant&#160;;<br>Sur tuz les altres bundist li olifant.<br>Plurent Franceis pur pitet de Rollant.</p>" },
    { n: 227, html: "<p><span class=\"bk-n\">227</span> Mult gentiment li emperere chevalchet.<br>Desur sa bronie fors ad mise sa barbe.<br>Pur sue amor altretel funt li altre&#160;:<br>Cent milie Francs en sunt reconoisable.<br>Passent cez puis e cez roches plus haltes,<br>Cez vals parfunz, cez destreiz anguisables,<br>Issent des porz e de la tere guaste,<br>Devers Espaigne sunt alez en la marche,<br>En un emplein unt prise lur estage.<br>A Baligant repairent ses enguardes.<br>Uns Sulians li ad dit sun message&#160;:<br>«&#160;Veüd avum li orguillus reis Carles.<br>Fiers sunt si hume, n’unt talent qu’il li faillent.<br>Adubez vus, sempres avrez bataille&#160;!&#160;»<br>Dist Baligant&#160;: «&#160;Or oi grant vasselage.<br>Sunez voz graisles, que mi paien le sacent&#160;!&#160;»</p>" },
    { n: 228, html: "<p><span class=\"bk-n\">228</span> Par tute l’ost funt lur taburs suner<br>E cez buisines e cez greisles mult cler&#160;:<br>Paien descendent pur lur cors aduber.<br>Li amiralz ne se voelt demurer,<br>Vest une bronie dunt li par sunt sasfret,<br>Lacet sun elme, ki ad or est gemmet,<br>Puis ceint s’espee al senestre costet.<br>Par sun orgoill li ad un num truvet&#160;:<br>Pur la Carlun dunt il oït parler<br>. . . . . . . . . . . . . . . . . .<br>Ço ert s’enseigne en bataille campel&#160;;<br>Ses chevalers en ad fait escrier.<br>Pent a sun col un soen grant escut let&#160;:<br>D’or est la bucle e de cristal listet,<br>La guige en est d’un bon palie roet&#160;;<br>Tient sun espiet, si l’apelet Maltet&#160;:<br>La hanste fut grosse cume uns tinels&#160;;<br>De sul le fer fust uns mulez trusset.<br>En sun destrer Baligant est muntet&#160;;<br>L’estreu li tint Marcules d’ultre mer.<br>La forcheüre ad asez grant li ber,<br>Graisles les flancs e larges les costez&#160;;<br>Gros ad le piz, belement est mollet,<br>Lees les espalles e le vis ad mult cler,<br>Fier le visage, le chef recercelet,<br>Tant par ert blancs cume flur en estet&#160;;<br>De vasselage est suvent esprovet&#160;;<br>Deus&#160;! quel baron, s’oüst chrestientet&#160;!<br>Le cheval brochet, li sancs en ist tuz clers,<br>Fait sun eslais, si tressalt un fosset,<br>Cinquante pez i poet hom mesurer.<br>Paien escrient&#160;: «&#160;Cist deit marches tenser&#160;!<br>N’i ad Franceis, si a lui vient juster,<br>Voeillet o nun, n’i perdet sun edet.<br>Carles est fols que ne s’en est alet.&#160;» AOI.</p>" },
    { n: 229, html: "<p><span class=\"bk-n\">229</span> Li amiralz ben resemblet barun.<br>Blanche ad la barbe ensement cume flur<br>E de sa lei mult par est saives hom<br>E en bataille est fiers e orgoillus.<br>Ses filz Malpramis mult est chevalerus&#160;;<br>Granz est e forz e trait as anceisurs.<br>Dist a sun perre&#160;: «&#160;Sire, car cevalchum&#160;!<br>Mult me merveill se ja verrum Carlun.&#160;»<br>Dist Baligant&#160;: «&#160;Oïl, car mult est proz.<br>En plusurs gestes de lui sunt granz honurs.<br>Il n’en at mie de Rollant sun nevold&#160;:<br>N’avrat vertut ques tienget contre nus. AOI.</p>" },
    { n: 230, html: "<p><span class=\"bk-n\">230</span> Bels filz Malpramis,&#160;» ço li dist Baligant,<br>«&#160;Li altrer fut ocis le bon vassal Rollant<br>E Oliver, li proz e li vaillanz,<br>Li .XII. per, qui Carles amat tant,<br>De cels de France .XX. milie cumbatanz.<br>Trestuz les altres ne pris jo mie un guant.<br>Li empereres repairet virement,<br>Sil m’at nunciet mes mès, li Sulians,<br>.X. escheles..... mult granz.<br>Cil est mult proz ki sunet l’olifant&#160;:<br>D’un graisle cler racatet ses cumpaignz<br>E si cevalcent el premer chef devant,<br>Ensembl’od els .XV. milie de Francs,<br>De bachelers que Carles cleimet enfanz.<br>Après icels en i ad ben altretanz.<br>Cil i ferrunt mult orgoillusement.&#160;»<br>Dist Malpramis&#160;: «&#160;Le colp vos en demant.&#160;» AOI</p>" },
    { n: 231, html: "<p><span class=\"bk-n\">231</span> «&#160;Filz Malpramis, Baligant li ad dit,<br>«&#160;Jo vos otri quanque m’avez ci quis.<br>Cuntre Franceis sempres irez ferir,<br>Si i merrez Torleu, le rei persis,<br>E Dapamort, un altre rei leutiz.<br>Le grant orgoill se ja puez matir,<br>Jo vos durrai un par de mun païs<br>Dès Cheriant entresqu’en Val Marchis.&#160;»<br>Cil respunt&#160;: «&#160;Sire, vostre mercit&#160;!&#160;»<br>Passet avant, le dun en requeillit,<br>Ço est de la terre ki fut al rei Flurit<br>A itel ore&#160;: unches puis ne la vit,<br>Ne il n’en fut ne vestut ne saisit.</p>" },
    { n: 232, html: "<p><span class=\"bk-n\">232</span> Li amiraill chevalchet par cez oz.<br>Sis filz le siut, ki mult ad grant le cors.<br>Li reis Torleus e li reis Dapamort<br>.XXX. escheles establissent mult tost.<br>Chevalers unt a merveillus esforz&#160;:<br>En la menur .L. milie en out.<br>La premere est de cels de Butentrot,<br>E l’altre après de Micenes as chefs gros&#160;:<br>Sur les eschines qu’il unt en mi les dos<br>Cil sunt seiet ensement cume porc&#160;; AOI.<br>E la terce est de Nubles e de Blos,<br>E la quarte est de Bruns e d’Esclavoz,<br>E la quinte est de Sorbres e de Sorz,<br>E la siste est d’Ermines e de Mors,<br>E la sedme est de cels de Jericho,<br>E l’oitme est de Nigres e la noefme de Gros,<br>E la disme est de Balide la fort&#160;:<br>Ço est une gent ki unches ben ne volt.<br>Li amiralz en juret quanqu’il poet<br>De Mahumet les vertuz e le cors&#160;:<br>«&#160;Karles de France chevalchet cume fols.<br>Bataille i ert, se il ne s’en destolt&#160;;<br>Jamais n’avrat el chef corone d’or.&#160;»</p>" },
    { n: 233, html: "<p><span class=\"bk-n\">233</span> Dis escheles establisent après.<br>La premere est des Canelius les laiz&#160;:<br>De Val Fuit sun venuz en traver&#160;;<br>L’altre est de Turcs e la terce de Pers,<br>E la quarte est de Pinceneis e de Pers,<br>E la quinte est de Solteras e d’Avers,<br>E la siste est d’Ormaleus e d’Eugiez,<br>E la sedme est de la gent Samuel,<br>L’oidme est de Bruise e la noefme de Clavers,<br>E la disme est d’Occian la desert&#160;:<br>Ço est une gent ki Damnedeu ne sert&#160;;<br>De plus feluns n’orrez parler jamais&#160;;<br>Durs unt les quirs ensement cume fer&#160;;<br>Pur ço n’unt soign de elme ne d’osberc&#160;;<br>En la bataille sunt felun e engrès. AOI.</p>" },
    { n: 234, html: "<p><span class=\"bk-n\">234</span> Li amiralz .X. escheles ad justedes.<br>La premere est des jaianz de Malprose,<br>L’altre est de Hums e la terce de Hungres,<br>E la quarte est de Baldise la lunge,<br>E la quinte est de cels de Val Penuse,<br>E la siste est de..... Maruse,<br>E la sedme est de Leus e d’Astrimonies,<br>L’oidme est d’Argoilles e la noefme de Clarbone,<br>E la disme est des barbez de Fronde&#160;:<br>Ço est une gent ki Deu nen amat unkes.<br>Geste Francor .XXX. escheles i numbrent.<br>Granz sunt les oz u cez buisines sunent.<br>Paien chevalchent en guise de produme. AOI.</p>" },
    { n: 235, html: "<p><span class=\"bk-n\">235</span> Li amiralz mult par est riches hoem.<br>Dedavant sei fait porter sun dragon<br>E l’estandart Tervagan e Mahum<br>E un’ ymagene Apolin le felun.<br>Des Canelius chevalchent envirun&#160;;<br>Mult haltement escrient un sermun&#160;:<br>«&#160;Ki par noz deus voelt aveir guarison,<br>Sis prit e servet par grant afflictiun&#160;!&#160;»<br>Paien i bassent lur chefs e lur mentun,<br>Lor helmes clers i suzclinent enbrunc.<br>Dient Franceis&#160;: «&#160;Sempres murrez, glutun&#160;!<br>De vos seit hoi male confusion&#160;!<br>Li nostre Deu, guarantisez Carlun&#160;!<br>Ceste bataille seit..... en sun num&#160;!&#160;» AOI.</p>" },
    { n: 236, html: "<p><span class=\"bk-n\">236</span> Li amiralz est mult de grant saveir&#160;;<br>A sei apelet sis filz e les dous reis&#160;:<br>«&#160;Seignurs barons, devant chevalchereiz.<br>Mes escheles, tutes les guiereiz&#160;;<br>Mais des meillors voeill jo retenir treis&#160;:<br>L’un’ ert de Turcs e l’altre d’Ormaleis<br>E la terce est des jaianz de Malpreis.<br>Cil d’Ociant ierent esembl’ ot mei,<br>Si justerunt a Charles e a Franceis.<br>Li emperere, s’il se cumbat od mei,<br>Desur le buc la teste perdre en deit.<br>Trestut seit fiz, n’i avrat altre dreit.&#160;» AOI.</p>" },
    { n: 237, html: "<p><span class=\"bk-n\">237</span> Granz sunt les oz e les escheles beles.<br>Entr’els nen at ne pui ne val ne tertre,<br>Selve ne bois&#160;; asconse n’i poet estre&#160;;<br>Ben s’entreveient en mi la pleine tere.<br>Dist Baligant&#160;: «&#160;La meie gent averse,<br>Car chevalchez pur la bataille quere&#160;!&#160;»<br>L’enseigne portet Amborres d’Oluferne.<br>Paien escrient, Preciuse l’apelent.<br>Dient Franceis&#160;: «&#160;De vos seit hoi grant perte&#160;!&#160;»<br>Mult haltement Munjoie renuvelent.<br>Li emperere i fait suner ses greisles<br>E l’olifan, ki trestuz les esclairet.<br>Dient paien&#160;: «&#160;La gent Carlun est bele.<br>Bataille avrum e aduree e pesme.&#160;» AOI.</p>" },
    { n: 238, html: "<p><span class=\"bk-n\">238</span> CCXXXVIII<br>Grant est la plaigne e large la cuntree.<br>Luisent cil elme as perres d’or gemmees<br>E cez escuz e cez bronies safrees<br>E cez espiez, cez enseignes fermees.<br>Sunent cez greisles, les voiz en sunt mult cleres&#160;;<br>De l’olifan haltes sunt les menees.<br>Li amiralz en apelet sun frere,<br>Ço est Canabeus, li reis de Floredee&#160;:<br>Cil tint la terre entresqu’en Val Sevree.<br>Les escheles Charlun li ad mustrees&#160;:<br>«&#160;Veez l’orgoil de France la loee&#160;!<br>Mult fierement chevalchet li emperere.<br>Il est darere od cele gent barbee&#160;:<br>Desur lur bronies lur barbes unt getees<br>Altresi blanches cume neif sur gelee.<br>Cil i ferrunt de lances e d’espees.<br>Bataille avrum e forte e aduree&#160;:<br>Unkes nuls hom ne vit tel ajustee.&#160;»<br>Plus qu’om ne lancet une verge pelee,<br>Baligant ad ses cumpaignes trespassees.<br>Une raison lur a dit’e mustree&#160;:<br>«&#160;Venez, paien, kar jon irai en l’estree.&#160;»<br>De sun espiet la hanste en ad branlee,<br>Envers Karlun la mure en ad turnee. AOI.</p>" },
    { n: 239, html: "<p><span class=\"bk-n\">239</span> Carles li magnes, cum il vit l’amiraill<br>E le dragon, l’enseigne e l’estandart,<br>— De cels d’Arabe si grant force i par ad,<br>De la contree unt porprises les parz<br>Ne mès que tant cume l’empereres en ad, —<br>Li reis de France s’en escriet mult halt&#160;:<br>«&#160;Barons franceis, vos estes bons vassals.<br>Tantes batailles avez faites en camps&#160;!<br>Veez, paien felun sunt e cuart.<br>Tutes lor leis un dener ne lur valt.<br>S’il unt grant gent, d’iço, seignurs, qui calt&#160;?<br>Ki or ne voelt a mei venir s’en alt&#160;!&#160;»<br>Des esperons puis brochet le cheval,<br>E Tencendor li ad fait .IIII. salz.<br>Dient Franceis&#160;: «&#160;Icist reis est vassals&#160;!<br>Chevalchez, bers&#160;! Nul de nus ne vus falt.&#160;»</p>" },
    { n: 240, html: "<p><span class=\"bk-n\">240</span> Clers fut li jurz e li soleilz luisanz.<br>Les oz sunt beles e les cumpaignes granz.<br>Justees sunt les escheles devant.<br>Li quens Rabels e li quens Guinemans<br>Lascent les resnes a lor cevals curanz,<br>Brochent a eit. Dunc laisent curre Francs,<br>Si vunt ferir de lur espiez trenchanz. AOI.</p>" },
    { n: 241, html: "<p><span class=\"bk-n\">241</span> Li quens Rabels est chevaler hardiz.<br>Le cheval brochet des esperuns d’or fin,<br>Si vait ferir Torleu, le rei persis.<br>N’escut ne bronie ne pout sun colp tenir&#160;:<br>L’espiet a or li ad enz el cors mis,<br>Que mort l’abat sur un boissun petit.<br>Dient Franceis&#160;: «&#160;Damnesdeus nos aït&#160;!<br>Carles ad dreit, ne li devom faillir.&#160;» AOI.</p>" },
    { n: 242, html: "<p><span class=\"bk-n\">242</span> E Guineman justet a un rei leutice.<br>Tute li freint la targe, ki est flurie&#160;;<br>Après li ad la bronie descunfite&#160;;<br>Tute l’enseigne li ad enz el cors mise,<br>Que mort l’abat, ki qu’en plurt u kin riet.<br>A icest colp cil de France s’escrient&#160;:<br>«&#160;Ferez, baron, ne vos targez mie&#160;!<br>Carles ad dreit vers la gent.....<br>Deus nus ad mis al plus verai juise.&#160;» AOI.</p>" },
    { n: 243, html: "<p><span class=\"bk-n\">243</span> Malpramis siet sur un cheval tut blanc&#160;;<br>Cunduit sun cors en la presse des Francs,<br>D’ures es altres granz colps i vait ferant,<br>L’un mort sur l’altre suvent vait tresturnant.<br>Tut premereins s’escriet Baligant&#160;:<br>«&#160;Li mien baron, nurrit vos ai lung tens.<br>Veez mun filz, Carlun vait querant,<br>A ses armes tanz barons calunjant&#160;:<br>Meillor vassal de lui ja ne demant.<br>Succurez le a voz espiez trenchant&#160;!&#160;»<br>A icest mot paien venent avant,<br>Durs colps i fierent, mult est li caples granz.<br>La bataille est merveilleuse e pesant&#160;:<br>Ne fut si fort enceis ne puis cet tens. AOI.</p>" },
    { n: 244, html: "<p><span class=\"bk-n\">244</span> Granz sunt les oz e les cumpaignes fieres,<br>Justees sunt trestutes les escheles,<br>E li paien merveillusement fierent.<br>Deus&#160;! tantes hanstes i ad par mi brisees,<br>Escuz fruisez e bronies desmaillees&#160;!<br>La veïsez la tere si junchee&#160;!<br>L’erbe del camp, ki est verte e delgee...<br>. . . . . . . . . . . . . .<br>Li amiralz recleimet sa maisnee&#160;:<br>Ferez, baron, sur la gent chrestiene&#160;!&#160;»<br>La bataille est mult dure e afichee&#160;;<br>Unc einz ne puis ne fut si fort ajustee&#160;;<br>Josqu’a la nuit n’en ert fins otriee. AOI.</p>" },
    { n: 245, html: "<p><span class=\"bk-n\">245</span> Li amiralz la sue gent apelet&#160;:<br>«&#160;Ferez, paien&#160;: por el venud n’i estes&#160;!<br>Jo vos durrai muillers gentes e beles,<br>Si vos durai feus e honors e teres.&#160;»<br>Paien respundent&#160;: «&#160;Nus le devuns ben fere.&#160;»<br>A colps pleners de lor espiez i perdent&#160;:<br>Plus de cent milie espees i unt traites.<br>Ais vos le caple e dulurus e pesmes&#160;;<br>Bataille veit cil ki entr’ els voit estre. AOI.</p>" },
    { n: 246, html: "<p><span class=\"bk-n\">246</span> Li emperere recleimet ses Franceis&#160;:<br>«&#160;Seignors barons, jo vos aim, si vos crei.<br>Tantes batailles avez faites pur mei,<br>Regnes cunquis e desordenet reis&#160;!<br>Ben le conuis que gueredun vos en dei<br>E de mun cors, de teres e d’aveir.<br>Vengez voz filz, voz freres e voz heirs,<br>Qu’en Rencesvals furent morz l’altre seir&#160;!<br>Ja savez vos cuntre paiens ai dreit.&#160;»<br>Respondent Franc&#160;: «&#160;Sire, vos dites veir.&#160;»<br>Itels .XX. miliers en ad od sei<br>Cumunement l’en prametent lor feiz<br>Ne li faldrunt pur mort ne pur destreit.<br>N’en i ad cet sa lance n’i empleit&#160;;<br>De lur espees i fierent demaneis&#160;;<br>La bataille est de merveillus destreit. AOI.</p>" },
    { n: 247, html: "<p><span class=\"bk-n\">247</span> E Malpramis par roi le camp chevalchet&#160;;<br>De cels de France i fait mult grant damage.<br>Naimes li dux fierement le reguardet,<br>Vait le ferir cum hume vertudable.<br>De sun escut li freint la pene halte,<br>De sun osberc les dous pans li desaffret,<br>El cors li met tute l’enseigne jalne,<br>Que mort l’abat entre .VII. C. des altres.</p>" },
    { n: 248, html: "<p><span class=\"bk-n\">248</span> Reis Canabeus, le frere a l’amiraill,<br>Des esporuns ben brochet sun cheval&#160;;<br>Trait ad l’espee, le punt est de cristal,<br>Si fiert Naimun en l’elme principal.<br>L’une meitiet l’en fruissed d’une part&#160;;<br>Al brant d’acer l’en trenchet .V. des laz.<br>Li capelers un dener ne li valt&#160;:<br>Trenchet la coife entres que a la char,<br>Jus a la tere une piece en abat.<br>Granz fut li colps, li dux en estonat&#160;:<br>Sempres caïst, se Deus ne li aidast.<br>De sun destrer le col en enbraçat.<br>Se li paiens une feiz recuvrast,<br>Sempres fust mort li nobilies vassal.<br>Carles de France i vint, kil sucurrat. AOI.</p>" },
    { n: 249, html: "<p><span class=\"bk-n\">249</span> Naimes li dux tant par est anguissables,<br>E li paiens de ferir mult le hastet.<br>Carles li dist&#160;: «&#160;Culvert, mar le baillastes&#160;!&#160;»<br>Vait le ferir par sun grant vasselage&#160;:<br>L’escut li freint, contre le coer li quasset,<br>De sun osberc li desrumpt la ventaille,<br>Que mort l’abat&#160;: la sele en remeint guaste.</p>" },
    { n: 250, html: "<p><span class=\"bk-n\">250</span> Mult ad grant doel Carlemagnes li reis,<br>Quant Naimun veit nafret devant sei,<br>Sur l’erbe verte le sanc tut cler caeir.<br>Li empereres li ad dit a cunseill&#160;:<br>«&#160;Bel sire Naimes, kar chevalez od mei&#160;!<br>Morz est li gluz ki en destreit vus teneit&#160;;<br>El cors li mis mun espiet une feiz.&#160;»<br>Respunt li dux&#160;: «&#160;Sire, jo vos en crei.<br>Se jo vif alques, mult grant prod i avreiz.&#160;»<br>Puis sunt justez par amur e par feid,<br>Ensembl’ od els tels .XX. milie Franceis<br>N’i ad celoi que n’i fierge o n’i capleit. AOI.<br>.</p>" },
    { n: 251, html: "<p><span class=\"bk-n\">251</span> Li amiralz chevalchet par le camp,<br>Si vait ferir le cunte Guneman.<br>Cuntre le coer li fruisset l’escut blanc,<br>De sun osberc li derumpit les pans,<br>Les dous costez li deseivret des flancs,<br>Que mort l’abat de sun cheval curant.<br>Puis ad ocis Gebuin e Lorant,<br>Richart le veill, li sire des Normans.<br>Paien escrient&#160;: «&#160;Preciuse est vaillant&#160;!<br>Ferez, baron, nus i avom guarant&#160;!&#160;» AOI.</p>" },
    { n: 252, html: "<p><span class=\"bk-n\">252</span> Ki puis veïst li chevaler d’Arabe,<br>Cels d’Occiant e d’Argoillie e de Bascle&#160;!<br>De lur espiez ben i fierent e caplent.<br>E li Franceis n’unt talent que s’en algent&#160;;<br>Asez i moerent e des uns e des altres.<br>Entresqu’al vespre est mult fort la bataille&#160;;<br>Des francs barons i ad mult gran damage&#160;;<br>Doel i avrat, enceis qu’ele departed. AOI.</p>" },
    { n: 253, html: "<p><span class=\"bk-n\">253</span> Mult ben i fierent Franceis e Arrabit.<br>Fruissent cez hanstes e cil espiez furbit.<br>Ki dunc veïst cez escuz si malmis,<br>Cez blancs osbercs ki dunc oïst fremir<br>E cez escuz sur cez helmes cruisir,<br>Cez chevalers ki dunc veïst caïr<br>E humes braire, contre tere murir,<br>De grant dulor li poüst suvenir&#160;!<br>Ceste bataille est mult fort a suffrir.<br>Li amiralz recleimet Apolin<br>E Tervagan e Mahumet altresi&#160;:<br>«&#160;Mi damnedeu, jo vos ai mult servit&#160;;<br>Tutes tes ymagenes ferai d’or fin… AOI.<br>. . . . . . . . . . . . . . . . . . . .&#160;»<br>As li devant un soen drut, Gemalfin&#160;;<br>Males nuveles li aportet e dit&#160;:<br>«&#160;Baligant, sire, mal estes oi baillit.<br>Perdut avez Malpramis, vostre filz,<br>E Canabeus, vostre frere, est ocis&#160;;<br>A dous Franceis belement en avint.<br>Li empereres en est l’uns, ço m’est vis&#160;:<br>Granz ad le cors, ben resenblet marchis,<br>Blanche ad la barbe cume flur en avrill.&#160;»<br>Li amiralz en ad le helme enclin<br>E en après sin enbrunket sun vis.<br>Si grant doel ad sempres quiad murir,<br>Sin apelat Jangleu l’ultremarin.</p>" },
    { n: 254, html: "<p><span class=\"bk-n\">254</span> Dist l’amiraill&#160;: «&#160;Jangleu, venez avant&#160;!<br>Vos estes proz e vostre saveir est grant&#160;;<br>Vostre conseill ai..... tuz tens.<br>Que vos en semblet d’Arrabiz e de Francs&#160;?<br>Avrum nos la victorie del champ&#160;?&#160;»<br>E cil respunt&#160;: «&#160;Morz estes, Baligant&#160;!<br>Ja vostre deu ne vos erent guarant.<br>Carles est fiers e si hume vaillant&#160;;<br>Unc ne vi gent ki si fust cumbatant.<br>Mais reclamez les barons d’Occiant,<br>Turcs e Enfruns, Arabiz e Jaianz.<br>Ço qu’estre en deit, ne l’alez demurant.&#160;»</p>" },
    { n: 255, html: "<p><span class=\"bk-n\">255</span> Li amiraill ad sa barbe fors mise,<br>Altresi blanche cume flur en espine&#160;:<br>Cument qu’il seit, ne s’i voelt celer mie.<br>Met a sa buche une clere buisine,<br>Sunet la cler, que si paien l’oïrent&#160;;<br>Par tut le camp ses cumpaignes ralient.<br>Cil d’Ociant i braient e hennissent,<br>Arguille si cume chen i glatissent&#160;;<br>Requerent Franc par si grant estultie,<br>El plus espès ses rumpent e partissent.<br>A icest colp en jetent mort .VII. milie.</p>" },
    { n: 256, html: "<p><span class=\"bk-n\">256</span> Li quens Oger cuardise n’out unkes&#160;;<br>Meillor vassal de lui ne vestit bronie.<br>Quant de Franceis les escheles vit rumpre,<br>Si apelat Tierri, le duc d’Argone,<br>Gefrei d’Anjou e Jozeran le cunte&#160;;<br>Mult fierement Carlun en araisunet&#160;:<br>«&#160;Veez paien cum ocient voz humes&#160;!<br>Ja Deu ne placet qu’el chef portez corone,<br>S’or n’i ferez pur venger vostre hunte&#160;!&#160;»<br>N’i ad icel ki un sul mot respundet&#160;;<br>Brochent ad eit, lor cevals laissent cure,<br>Vunt les ferir la o il les encuntrent. AOI.</p>" },
    { n: 257, html: "<p><span class=\"bk-n\">257</span> Mult ben i fiert Carlemagnes li reis,<br>Naimes li dux e Oger li Daneis,<br>Geifreid d’Anjou, ki l’enseigne teneit.<br>Mult par est proz danz Ogers li Daneis&#160;:<br>Puint le ceval, laisset curre ad espleit,<br>Si vait ferir celui ki le dragun teneit,<br>Qu’Ambure cravente en la place devant sei<br>E le dragon e l’enseigne le rei.<br>Baligant veit sun gunfanun cadeir<br>E l’estandart Mahumet remaneir&#160;:<br>Li amiralz alques s’en aperceit<br>Que il ad tort e Carlemagnes dreit.<br>Paien d’Arabe s’en turnent.....<br>Li emperere recleimet ses Franceis&#160;:<br>«&#160;Dites, baron, por Deu, si m’aidereiz.&#160;»<br>Respundent Francs&#160;: «&#160;Mar le demandereiz.<br>Trestut seit fel ki n’i fierget a espleit&#160;!&#160;» AOI.</p>" },
    { n: 258, html: "<p><span class=\"bk-n\">258</span> Passet li jurz, si turnet a la vespree.<br>Franc e paien i fierent des espees.<br>Cil sunt vassal ki les oz ajusterent.<br>Lor enseignes n’i unt mie ubliees&#160;:<br>Li amiralz «&#160;Preciuse&#160;!&#160;» ad criee,<br>Carles «&#160;Munjoie&#160;!&#160;» l’enseigne renumee.<br>L’un conuist l’altre as haltes voiz e as cleres.<br>En mi le camp amdui s’entr’encuntrerent,<br>Si se vunt ferir, granz colps s’entredunerent<br>De lor espiez en lor targes roees.<br>Fraites les unt desuz cez bucles lees&#160;;<br>De lor osbercs les pans en desevrerent&#160;:<br>Dedenz cez cors mie ne s’adeserent.<br>Rumpent cez cengles e cez seles verserent,<br>Cheent li rei a tere.....<br>Isnelement sur lor piez releverent.<br>Mult vassalment unt traites les espees.<br>Cette bataille n’en ert mais destornee&#160;:<br>Seinz hume mort ne poet estre achevee. AOI.</p>" },
    { n: 259, html: "<p><span class=\"bk-n\">259</span> Mult est vassal Carles de France dulce&#160;;<br>Li amiralz, il nel crent ne ne dutet.<br>Cez lor espees tutes nues i mustrent,<br>Sur cez escuz mult granz colps s’entredunent,<br>Trenchent les quirs e cez fuz ki sunt dubles&#160;;<br>Cheent li clou, si peceient les bucles&#160;;<br>Puis fierent il nud a nud sur lur bronies&#160;;<br>Des helmes clers li fuus en escarbunet.<br>Ceste bataille ne poet remaneir unkes,<br>Josque li uns sun tort i reconuisset. AOI.</p>" },
    { n: 260, html: "<p><span class=\"bk-n\">260</span> Dist l’amiraill&#160;: «&#160;Carles, kar te purpenses,<br>Si pren cunseill que vers mei te repentes&#160;!<br>Mort as mun filz, par le men esciente&#160;;<br>A mult grant tort mun païs me calenges.<br>Deven mes hom [en fedeltet voeill rendre]<br>Ven mei servir d’ici qu’en Oriente.&#160;»<br>Carles respunt&#160;: «&#160;Mult grant viltet me semble.<br>Pais ne amor ne dei a paien rendre.<br>Receif la lei que Deus nos apresentet,<br>Chrestientet, e pui t’amerai sempres&#160;;<br>Puis serf e crei le rei omnipotente.&#160;»<br>Dist Baligant&#160;: «&#160;Malvais sermun cumences&#160;!&#160;»<br>Puis vunt ferir des espees qu’unt ceintes. AOI.</p>" },
    { n: 261, html: "<p><span class=\"bk-n\">261</span> Li amiralz est mult de grant vertut.<br>Fier Carlemagne sur l’elme d’acer brun,<br>Desur la teste li ad frait e fendut&#160;;<br>Met li l’espee sur les chevels menuz,<br>Prent de la carn grant pleine palme e plus&#160;:<br>Iloec endreit remeint li os tut nut.<br>Carles cancelet, por poi qu’il n’est caüt&#160;;<br>Mais Deus ne volt qu’il seit mort ne vencut.<br>Seint Gabriel est repairet a lui,<br>Si li demandet&#160;: «&#160;Reis magnes, que fais tu&#160;?&#160;»</p>" },
    { n: 262, html: "<p><span class=\"bk-n\">262</span> Quant Carles oït la seinte voiz de l’angle,<br>Nen ad poür ne de murir dutance&#160;;<br>Repairet loi vigur e remembrance.<br>Fiert l’amiraill de l’espee de France,<br>L’elme li freint o li gemme reflambent,<br>Trenchet la teste pur la cervele espandre<br>E tut le vis tresqu’en la barbe blanche,<br>Que mort l’abat senz nule recouvrance.<br>«&#160;Munjoie&#160;!&#160;» escriet pur la reconuisance.<br>A icest mot venuz i est dux Neimes&#160;:<br>Prent Tencendur, muntet i est li reis magnes.<br>Paien s’en turnent, ne voit Deus qu’il i remainent.<br>Or sunt Franceis a icels qu’il demandent.</p>" },
    { n: 263, html: "<p><span class=\"bk-n\">263</span> Paien s’en fuient, cum Damnesdeus le volt.<br>Encalcent Franc e l’emperere avoec.<br>Ço dist li reis&#160;: «&#160;Seignurs, vengez voz doels,<br>Si esclargiez voz talenz e voz coers,<br>Kar hoi matin vos vi plurer des oilz.&#160;»<br>Respondent Franc&#160;: «&#160;Sire, ço nus estoet.&#160;»<br>Cascuns i fiert tanz granz colps cum il poet.<br>Poi s’en estoerstrent d’icels ki sunt iloec.</p>" },
    { n: 264, html: "<p><span class=\"bk-n\">264</span> Granz est li calz, si se levet la puldre.<br>Paien s’en fuient e Franceis les anguissent&#160;;<br>Li enchalz duret d’ici qu’en Sarraguce.<br>En sum sa tur muntee est Bramidonie,<br>Ensembl’ od li si clerc e si canonie<br>De false lei que Deus nen amat unkes&#160;:<br>Ordres nen unt ne en lor chefs corones.<br>Quant ele vit Arrabiz si cunfundre,<br>A halte voiz s’escrie&#160;: «&#160;Aiez nos, Mahum&#160;!...<br>E&#160;! gentils reis, ja sunt vencuz noz humes,<br>Li amiralz ocis a si grant hunte&#160;!&#160;»<br>Quant l’ot Marsilie, vers sa pareit se turnet,<br>Pluret des oilz, tute sa chere enbrunchet&#160;;<br>Morz est de doel, si cum pecchet l’encumbret.<br>L’anme de lui as vifs diables dunet. AOI.</p>" },
    { n: 265, html: "<p><span class=\"bk-n\">265</span> Paien sunt morz, alquant.....<br>E Carles ad sa bataille vencue.<br>De Sarraguce ad la porte abatue&#160;:<br>Or set il ben que n’est mais defendue.<br>Prent la citet, sa gent i est venue&#160;:<br>Par poestet icele noit i jurent.<br>Fiers est li reis a la barbe canue.<br>E Bramidonie les turs li ad rendues&#160;:<br>Les dis sunt grandes, les cinquante menues.<br>Mult ben espleitet qui Damnesdeus aiuet.</p>" },
    { n: 266, html: "<p><span class=\"bk-n\">266</span> Passet li jurz, la noit est aserie&#160;;<br>Clere est la lune e les esteiles flambient.<br>Li emperere ad Sarraguce prise.<br>A mil Franceis funt ben cercer la vile,<br>Les sinagoges e les mahumeries&#160;;<br>A mailz de fer e a cuignees qu’il tindrent,<br>Fruissent les ymagenes e trestutes les ydeles&#160;:<br>N’i remeindrat ne sorz ne falserie.<br>Li reis creit en Deu, faire voelt sun servise,<br>E si evesque les eves beneïssent,<br>Meinent paien entesqu’al baptisterie&#160;:<br>S’or i ad cel qui Carle cuntredie,<br>Il le fait pendre o ardeir ou ocire.<br>Baptizet sunt asez plus de .C. milie<br>Veir chrestien, ne mais sul la reïne.<br>En France dulce iert menee caitive&#160;:<br>Ço voelt li reis par amur cunvertisset.</p>" },
    { n: 267, html: "<p><span class=\"bk-n\">267</span> Passet la noit, si apert le cler jor.<br>De Sarraguce Carles guarnist les turs&#160;;<br>Mil chevalers i laissat puigneürs&#160;;<br>Guardent la vile a oes l’empereor.<br>Muntet li reis e si hume trestuz<br>E Bradimonie, qu’il meinet en sa prisun&#160;;<br>Mais n’ad talent que li facet se bien nun.<br>Repairez sunt a joie e a baldur.<br>Passent Nerbone par force e par vigur&#160;;<br>Vint a Burdeles, la citet de.....<br>Desur l’alter seint Sevrin le baron<br>Met l’oliphan plein d’or e de manguns&#160;:<br>Li pelerin le veient ki la vunt.<br>Passet Girunde a mult granz nefs qu’i sunt&#160;;<br>Entresqu’a Blaive ad cunduit sun nevold<br>E Oliver, sun nobilie cumpaignun,<br>E l’arcevesque, ki fut sages e proz.<br>En blancs sarcous fait metre les seignurs,<br>A Seint Romain&#160;: la gisent li baron.<br>Francs les cumandent a Deu e a ses nuns.<br>Carles cevalchet e les vals e les munz&#160;;<br>Entresqu’a Ais ne volt prendre sujurn.<br>Tant chevalchat qu’il descent al perrun.<br>Cume il est en sun paleis halçur,<br>Par ses messages mandet ses jugeors,<br>Baivers e Saisnes, Loherencs e Frisuns&#160;;<br>Alemans mandet, si mandet Borguignuns<br>E Peitevins e Normans e Bretuns,<br>De cels de France des plus saives qui sunt.<br>Des ore cumencet le plait de Guenelun.</p>" },
    { n: 268, html: "<p><span class=\"bk-n\">268</span> Li empereres est repairet d’Espaigne<br>E vient a Ais, a meillor sied de France&#160;;<br>Muntet el palais, est venut en la sale.<br>As li Alde venue, une bele damisele.<br>Ço dist al rei&#160;: «&#160;O est Rollant le catanie,<br>Ki me jurat cume sa per a prendre&#160;?&#160;»<br>Carles en ad e dulor e pesance,<br>Pluret des oilz, tiret sa barbe blance&#160;:<br>Soer, cher’amie, d’hume mort me demandes.<br>Jo t’en durai mult esforcet eschange&#160;:<br>Ço est Loewis, mielz ne sai a parler&#160;;<br>Il est mes filz e si tendrat mes marches.&#160;»<br>Alde respunt&#160;: «&#160;C’est mot mei est estrange.<br>Ne place Deu ne ses seinz ne ses angles<br>Après Rollant que jo vive remaigne&#160;!&#160;»<br>Pert la culor, chet as piez Carlemagne,<br>Sempres est morte. Deus ait mercit de l’anme&#160;!<br>Franceis barons en plurent e si la pleignent.</p>" },
    { n: 269, html: "<p><span class=\"bk-n\">269</span> Alde la bel’ est a sa fin alee.<br>Quidet li reis que el se seit pasmee&#160;;<br>Pited en ad, sin pluret l’emperere&#160;;<br>Prent la as mains, si l’en ad relevee.<br>Desur les espalles ad la teste clinee.<br>Quant Carles veit que morte l’ad truvee,<br>Quatre cuntesses sempres i ad mandees&#160;:<br>A un muster de nuneins est portee&#160;;<br>La noit la guaitent entresqu’a l’ajurnee.<br>Lunc un alter belement l’enterrerent.<br>Mult grant honur i ad li reis dunee. AOI.</p>" },
    { n: 270, html: "<p><span class=\"bk-n\">270</span> Li emperere est repairet ad Ais.<br>Guenes li fels, en caeines de fer,<br>En la citet est devant le paleis&#160;;<br>A un’ estache l’unt atachet cil serf.<br>Les mains li lient a curreies de cerf&#160;;<br>Tres ben le batent a fuz e a jamelz&#160;:<br>N’ad deservit que altre ben i ait&#160;;<br>A grant dulur iloec atent sun plait.</p>" },
    { n: 271, html: "<p><span class=\"bk-n\">271</span> Il est escrit en l’ancienne geste<br>Que Carles mandet humes de plusurs teres.<br>Asemblez sunt ad Ais, a la capele.<br>Halz est li jurz, mult par est grande la feste,<br>Dient alquanz del baron seint Silvestre.<br>Dès ore cumencet le plait et les noveles<br>De Guenelun, ki traïsun ad faite.<br>Li emperere devant sei l’ad fait traire. AOI.</p>" },
    { n: 272, html: "<p><span class=\"bk-n\">272</span> «&#160;Seignors barons,&#160;» dist Carlemagnes li reis,<br>«&#160;De Guenelun car me jugez le dreit&#160;!<br>Il fut en l’ost tresqu’en Espaigne od mei,<br>Si me tolit .XX. milie de mes Franceis<br>E mun nevold, que ja mais ne verreiz,<br>E Oliver, li proz e li curteis&#160;;<br>Les .XII. pers ad traït por aveir.&#160;»<br>Dist Guenelon&#160;: «&#160;Fel seie se jol ceil&#160;!<br>Rollant me forfist en or e en aveir,<br>Pur que jo quis sa mort e sun destreit&#160;;<br>Mais traïsun nule n’en i otrei.&#160;»<br>Respundent Franc&#160;: «&#160;Ore en tendrum cunseill.&#160;»</p>" },
    { n: 273, html: "<p><span class=\"bk-n\">273</span> Devant le rei la s’estut Guenelun.<br>Cors ad gaillard, el vis gente color&#160;;<br>S’il fust leials, ben resemblast barun.<br>Veit cels de France e tuz les jugeürs,<br>De ses parenz .XXX. ki od lui sunt&#160;;<br>Puis s’escriat haltement, a grant voeiz&#160;:<br>«&#160;Pur amor Deu, car m’entendez, barons&#160;!<br>Seignors, jo fui en l’ost avoec l’empereür,<br>Serveie le par feid e par amur.<br>Rollant sis niés me coillit en haür,<br>Si me jugat a mort e a dulur.<br>Message fui al rei Marsiliun&#160;;<br>Par mun saveir vinc jo a guarisun.<br>Jo desfiai Rollant le poigneor<br>E Oliver e tuiz lur cumpaignun&#160;:<br>Carles l’oïd e si nobilie baron.<br>Venget m’en sui, mais n’i ad traïsun.&#160;»<br>Respundent Francs&#160;: «&#160;A conseill en irums.&#160;»</p>" },
    { n: 274, html: "<p><span class=\"bk-n\">274</span> Quant Guenes veit que ses granz plaiz cumencet,<br>De ses parenz ensemble en i out trente.<br>Un en i ad a qui li altre entendent&#160;:<br>Ço est Pinabel, del castel de Sorence&#160;;<br>Ben set parler e dreite raisun rendre&#160;;<br>Vassals est bons por ses armes defendre. AOI.<br>Ço li dist Guenes&#160;: «&#160;En vos..... ami.....<br>Getez mei hoi de mort e de calunje&#160;!&#160;»<br>Dist Pinabel&#160;: «&#160;Vos serez guarit sempres.<br>N’i ad Francès ki vos juget a pendre,<br>U l’emperere les noz dous cors en asemble,<br>Al brant d’acer que jo ne l’en desmente.&#160;»<br>Guenes li quens a ses piez se presente.</p>" },
    { n: 275, html: "<p><span class=\"bk-n\">275</span> Bavier e Saisnes sunt alet a conseill<br>E Peitevin e Norman e Franceis&#160;;<br>Asez i ad Alemans e Tiedeis&#160;;<br>Icels d’Alverne i sunt li plus curteis.<br>Pur Pinabel se cuntienent plus quei.<br>Dist l’un a l’altre&#160;: «&#160;Bien fait a remaneir&#160;!<br>Laisum le plait e si preium le rei<br>Que Guenelun cleimt quite ceste feiz,<br>Puis si li servet par amur e par feid.<br>Morz est Rollant, ja mais nel revereiz&#160;;<br>N’ert recuvret por or ne por aveir&#160;:<br>Mult sereit fols ki… se cumbatreit.&#160;»<br>N’en i ad celoi nel graant e otreit,<br>Fors sul Tierri, le frere dam Geifreit. AOI.</p>" },
    { n: 276, html: "<p><span class=\"bk-n\">276</span> A Charlemagne repairent si barun&#160;;<br>Dient al rei&#160;: «&#160;Sire, nus vos prium<br>Que clamez quite le cunte Guenelun,<br>Puis si vos servet par feid e par amor.<br>Vivre le laisez, car mult est gentilz hoem.<br>Ja por murir n’en ert veüd gerun,<br>Ne por aveir ja nel recuverum.&#160;»<br>Ço dist li reis&#160;: «&#160;Vos estes mi felun.&#160;» AOI.</p>" },
    { n: 277, html: "<p><span class=\"bk-n\">277</span> Quant Carles veit que tuz li sunt faillid,<br>Mult l’enbrunchit e la chere e le vis,<br>Al doel qu’il ad si se cleimet caitifs.<br>Ais li devant uns chevalers, Tierris,<br>Frere Gefrei, a un duc angevin.<br>Heingre out le cors e graisle e eschewid,<br>Neirs les chevels e alques bruns le vis&#160;;<br>N’est gueres granz ne trop nen est petiz.<br>Curteisement a l’emperere ad dit&#160;:<br>«&#160;Bels sire reis, ne vos dementez si&#160;!<br>Ja savez vos que mult vos ai servit.<br>Par anceisurs dei jo tel plait tenir&#160;:<br>Que que Rollant a Guenelun forsfesist,<br>Vostre servise l’en doüst bien guarir.<br>Guenes est fels d’iço qu’il le traït&#160;;<br>Vers vos s’en est parjurez e malmis.<br>Pur ço le juz jo a pendre e a murir<br>E sun cors metre.....<br>Si cume fel ki felonie fist.<br>S’or ad parent ki m’en voeille desmentir,<br>A ceste espee, que jo ai ceinte ici,<br>Mun jugement voel sempres garantir.&#160;»<br>Respundent Franc&#160;: «&#160;Or avez vos ben dit.&#160;»</p>" },
    { n: 278, html: "<p><span class=\"bk-n\">278</span> CCLXXVIII<br>Devant lu rei est venuz Pinabel.<br>Granz est e forz e vassals e isnel&#160;;<br>Qu’il fiert a colp, de sun tens n’i ad mais&#160;;<br>E dist al rei&#160;: «&#160;Sire, vostre est li plaiz&#160;:<br>Car cumandez que tel noise n’i ait&#160;!<br>Ci vei Tierri, ki jugement ad fait.<br>Jo si li fals, od lui m’en cumbatrai.&#160;»<br>Met li el poign de cerf le destre guant.<br>Dist li empereres&#160;: «&#160;Bons pleges en demant.&#160;»<br>.XXX. parenz li plevissent leial.<br>Ço dist li reis&#160;: «&#160;E jol vos recrerai.&#160;»<br>Fait cels guarder tresque li dreiz en serat. AOI.</p>" },
    { n: 279, html: "<p><span class=\"bk-n\">279</span> Quant veit Tierri qu’or en ert la bataille,<br>Sun destre guant en ad presentet Carle.<br>Li emperere li recreit par hostage,<br>Puis fait porter .IIII. bancs en la place&#160;:<br>La vunt sedeir cil kis deivent cumbatre.<br>Ben sunt malez, par jugement des altres,<br>Sil purparlat Oger de Denemarche&#160;;<br>E puis demandent lur chevals e lur armes. AOI.</p>" },
    { n: 280, html: "<p><span class=\"bk-n\">280</span> Puis que il sunt a bataille justez,<br>Ben sunt cunfès e asols e seignez&#160;;<br>Oent lur messes e sunt acuminiez&#160;;<br>Mult granz offrendes metent par cez musters.<br>Devant Carlun andui sunt repairez.<br>Lur esperuns unt en lor piez calcez,<br>Vestent osberc blancs e forz e legers,<br>Lur helmes clers unt fermez en lor chefs,<br>Ceinent espees enheldees d’or mier,<br>En lur cols pendent lur escuz de quarters,<br>En lur puinz destres unt lur trenchanz espiez,<br>Puis sunt muntez en lur curanz destrers.<br>Idunc plurerent .C. milie chevalers<br>Qui pur Rollant de Tierri unt pitiet.<br>Deus set asez cument la fins en ert.</p>" },
    { n: 281, html: "<p><span class=\"bk-n\">281</span> Dedessuz Ais est la pree mult large.<br>Des dous baruns justee est la bataille.<br>Cil sunt produme e de grant vasselage<br>E lur chevals sunt curanz e aates.<br>Brochent les bien, tutes les resnes lasquent,<br>Par grant vertut vait ferir l’uns li altre.<br>Tuz lur escuz i fruissent e esquassent,<br>Lur osbercs rumpent e lur cengles depiecent,<br>Les alves turnent, les seles cheent a tere.<br>.C. mil humes i plurent, kis esguardent. AOI.</p>" },
    { n: 282, html: "<p><span class=\"bk-n\">282</span> A tere sunt ambdui li chevaler.<br>Isnelement se drecent sur lur piez.<br>Pinabels est forz e isnels e legers.<br>Li uns requiert l’altre, n’unt mie des destrers.<br>De cez espees enheldees d’or mer<br>Fierent e caplent sur cez helmes d’acer&#160;;<br>Granz sunt les colps as helmes detrencher.<br>Mult se dementent cil franceis chevaler.<br>«&#160;E&#160;! Deus,&#160;» dist Carles, «&#160;le dreit en esclargiez&#160;!&#160;»</p>" },
    { n: 283, html: "<p><span class=\"bk-n\">283</span> CCLXXXIII<br>Dist Pinabel&#160;: «&#160;Tierri, car te recreiz&#160;!<br>Tes hom serai par amur e par feid,<br>A tun plaisir te durrai mun aveir,<br>Mais Guenelun fai acorder al rei&#160;!&#160;»<br>Respont Tierri&#160;: «&#160;Ja n’en tendrai cunseill.<br>Tut seie fel, se jo mie l’otrei&#160;!<br>Deus facet hoi entre nus dous le dreit&#160;!&#160;» AOI.</p>" },
    { n: 284, html: "<p><span class=\"bk-n\">284</span> Ço dist Tierri&#160;: «&#160;Pinabel, mult ies ber,<br>Granz ies e forz e tis cors ben mollez&#160;;<br>De vasselage te conoissent ti per&#160;:<br>Ceste bataille car la laisses ester&#160;!<br>A Carlemagne te ferai acorder&#160;;<br>De Guenelun justise ert faite tel<br>Jamais n’ert jur que il n’en seit parlet.<br>Dist Pinabel&#160;: «&#160;Ne placet Damnedeu&#160;!<br>Sustenir voeill trestut mun parentet&#160;;<br>N’en recrerrai pur nul hume mortel&#160;;<br>Mielz voeill murir qu’il me seit reprovet.&#160;»<br>De lur espees cumencent a capler<br>Desur cez helmes, ki sunt a or gemez&#160;:<br>Cuntre le ciel en volet li fous tuz clers.<br>Il ne poet estre qu’il seient desevrez&#160;:<br>Seinz hume mort ne poet estre afinet. AOI.</p>" },
    { n: 285, html: "<p><span class=\"bk-n\">285</span> Mult par est proz Pinabel de Sorence,<br>Si fiert Tierri sur l’elme de Provence&#160;:<br>Salt en li fous, que l’erbe en fait esprendre.<br>Del brant d’acer la mure li presentet.<br>Desur le frunt li ad faite descendre,<br>Par mi le vis.....<br>La destre joe en ad tute sanglente,<br>L’osberc del dos josque par sum le ventre.<br>Deus le guarit, que mort ne l’acraventet. AOI.</p>" },
    { n: 286, html: "<p><span class=\"bk-n\">286</span> Ço veit Tierris que el vis est ferut&#160;:<br>Li sancs tuz clers en chiet el pred herbus.<br>Fiert Pinabel sur l’elme d’acer brun,<br>Jusqu’al nasel li ad frait e fendut,<br>Del chef li ad le cervel espandut,<br>Brandit sun colp, si l’ad mort abatut.<br>A icest colp est li esturs vencut.<br>Escrient Franc&#160;: «&#160;Deus i ad fait vertut&#160;!<br>Asez est dreiz que Guenes seit pendut<br>E si parent, ki plaidet unt pur lui.&#160;» AOI.</p>" },
    { n: 287, html: "<p><span class=\"bk-n\">287</span> CCLXXXVII<br>Quant Tierris ad vencue sa bataille,<br>Venuz i est li emperere Carles,<br>Ensembl’od lui de ses baruns ad quatre,<br>Naimes li dux, Oger de Danemarche,<br>Geifrei d’Anjou e Willalme de Blaive.<br>Li reis ad pris Tierri entre sa brace,<br>Tert lui le vis od ses granz pels de martre,<br>Celes met jus, puis li afublent altres&#160;;<br>Mult suavet le chevaler desarment.<br>Munter l’unt fait en une mule d’Arabe&#160;;<br>Repairet s’en a joie e a barnage&#160;;<br>Vienent ad Ais, descendent en la place.<br>Dès ore cumencet l’ocisiun des altres.</p>" },
    { n: 288, html: "<p><span class=\"bk-n\">288</span> CCLXXXVIII<br>Carles apelet ses cuntes e ses dux&#160;:<br>«&#160;Que me loez de cels qu’ai retenuz&#160;?<br>Pur Guenelun erent a plait venuz,<br>Pur Pinabel en ostage renduz.&#160;»<br>Respundent Franc&#160;: «&#160;Ja mar en vivrat uns&#160;!&#160;»<br>Li reis cumandet un soen veier, Basbrun&#160;:<br>«&#160;Va, sis pent tuz a l’arbre de mal fust&#160;!<br>Par ceste barbe dunt li peil sunt canuz,<br>Se uns escapet, morz iez e cunfunduz.&#160;»<br>Cil li respunt&#160;: «&#160;Qu’en fereie jo el&#160;?&#160;»<br>Od .C. serjanz par force les cunduit.<br>.XXX. en i ad d’icels ki sunt pendut.<br>Ki hume traïst sei ocit e altroi. AOI.</p>" },
    { n: 289, html: "<p><span class=\"bk-n\">289</span> Puis sunt turnet Bavier e Aleman<br>E Peitevin e Bretun e Norman.<br>Sor tuit li altre l’unt otriet li Franc<br>Que Guenes moerget par merveillus ahan.<br>Quatre destrers funt amener avant,<br>Puis si li lient e les piez e les mains.<br>Li cheval sunt orgoillus e curant&#160;:<br>Quatre serjanz les acoeillent devant<br>Devers un’ ewe ki est en mi un camp.<br>Guenes est turnet a perdiciun grant&#160;;<br>Trestuit si nerf mult li sunt estendant<br>E tuit li membre de sun cors derumpant&#160;:<br>Sur l’erbe verte en espant li cler sanc.<br>Guenes est mort cume fel recreant.<br>Hom ki traïst altre nen est dreiz qu’il s’en vant.</p>" },
    { n: 290, html: "<p><span class=\"bk-n\">290</span> Quant li empereres ad faite sa venjance,<br>Sin apelat ses evesques de France,<br>Cels de Baviere e icels d’Alemaigne&#160;:<br>«&#160;En ma maisun ad une caitive franche.<br>Tant ad oït e sermuns e essamples<br>Creire voelt Deu, chrestientet demandet.<br>Baptizez la, pur quei Deus en ait l’anme.&#160;»<br>Cil li respundent&#160;: «&#160;Or seit fait par marrenes&#160;!&#160;»<br>. . . . . . . . . . . . . . . . . . . . . . . .<br>As bainz ad Ais mult sunt granz les c....<br>La baptizent la reïne d’Espaigne&#160;:<br>Truvé li unt le num de Juliane.<br>Chrestiene est par veire conoisance.</p>" },
    { n: 291, html: "<p><span class=\"bk-n\">291</span> Quant l’emperere ad faite sa justise<br>E esclargiez est la sue grant ire.<br>En Bramidonie ad chrestientet mise,<br>Passet li jurz, la nuit est aserie.<br>Culcez s’est li reis en sa cambre voltice.<br>Seint Gabriel de part Deu li vint dire&#160;:<br>«&#160;Carles, sumun les oz de tun emperie&#160;!<br>Par force iras en la tere de Bire,<br>Reis Vivien si succuras en Imphe,<br>A la citet que paien unt asise&#160;:<br>Li chrestien te recleiment e crient.&#160;»<br>Li emperere n’i volsist aler mie&#160;:<br>«&#160;Deus,&#160;» dist li reis, «&#160;si penuse est ma vie&#160;!&#160;»<br>Pluret des oilz, sa barbe blanche tiret.<br>Ci falt la geste que Turoldus declinet.</p>" },
  ],
});
